(33, 1, 'ANP-101', 'اناتومي او فزیولوژي ۱ — Anatomy & Physiology I', 'د انسان د بدن جوړښت او دنده، په ځانګړي ډول د ښځینه تناسلي سیسټم او لګن، چې د مامایي عملي کار بنسټ جوړوي.', '#6C4CF1', 4, 1, TRUE, '2026-09-13 04:39:29'),
(34, 1, 'MID-101', 'د قابلګي بنسټونه — Foundations of Midwifery', 'د قابلګي فلسفه، تاریخ، د قابلګي دندې او مسلکي معیارونه، او د ښځې پر محور روغتیايي پاملرنه.', '#E8557E', 3, 2, TRUE, '2026-09-13 04:39:29'),
