INSERT INTO lessons (id, subject_id, title, description, content, direction, video_type, video_url, video_file, duration_minutes, difficulty, recommended_day, is_required, sort_order, is_active, created_at) VALUES
(328, 33, 'اناتومي او فزیولوژي څه دي؟', '<p dir="rtl" style="text-align:right">اناتومي د بدن د جوړښت مطالعه ده او فزیولوژي د هغه د دندې. دا دواړه یوځای د روغتیايي زده کړې بنسټ جوړوي.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>د اناتومي او فزیولوژي ترمنځ توپیر بیان کړئ.</li><li>د اناتومي مختلفې څانګې وپیژنئ.</li><li>ووایاست چې ولې ماما ته دې دوو علومو ته اړتیا ده.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">اناتومي د بدن د جوړښت مطالعه ده او فزیولوژي د هغه د دندې. دا دواړه یوځای د روغتیايي زده کړې بنسټ جوړوي.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>اناتومي (Anatomy) د بدن د برخو جوړښت، شکل او موقعیت څیړي.</li><li>فزیولوژي (Physiology) دا څیړي چې هره برخه څنګه کار کوي.</li><li>ماکروسکوپیک اناتومي هغه څه دي چې په سترګو لیدل کیږي؛ مایکروسکوپیک اناتومي مایکروسکوپ ته اړتیا لري.</li><li>د جوړښت او دندې تر منځ نږدې اړیکه شته — جوړښت دنده ټاکي.</li><li>ماما باید د امیندوارۍ او زیږون په جریان کې د بدن د بدلونونو دلیل پوه شي.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>اناتومي</td><td dir="ltr" style="text-align:left">Anatomy</td></tr><tr><td>فزیولوژي</td><td dir="ltr" style="text-align:left">Physiology</td></tr><tr><td>جوړښت</td><td dir="ltr" style="text-align:left">Structure</td></tr><tr><td>دنده</td><td dir="ltr" style="text-align:left">Function</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>کله چې د لګن جوړښت وپیژنې، وروسته به پوه شې چې ولې ځینې زیږونونه اسانه او ځینې ستونزمن وي.</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'url', 'https://www.youtube.com/watch?v=uBGl2BujkPQ', NULL, 30, 'intro', 1, TRUE, 1, TRUE, '2026-09-13 04:39:29'),
(329, 33, 'د بدن د تنظیم کچې', '<p dir="rtl" style="text-align:right">د انسان بدن له اتومونو څخه تر بشپړ ارګانیزم پورې په منظمو کچو جوړ شوی دی.</p>', '<h3 dir="rtl" style="text-align:right"></h3><h1>د انسان د بدن د تنظیم کچې (Levels of Human Organization)</h1><h2>د درس پېژندنه</h2><p>ګرانو زده‌کوونکو! نن موږ د اناتومي او فزیولوژي له هغو بنسټیزو موضوعاتو څخه یوه زده کوو چې د راتلونکو ټولو درسونو لپاره ډېر اهمیت لري. زموږ موضوع ده:</p><p><strong>د انسان د بدن د تنظیم کچې (Levels of Human Organization)</strong></p><p>که تاسو دا موضوع په سمه توګه درک کړئ، نو وروسته به د حجرې (Cell)، نسج (Tissue)، غړي (Organ)، د غړو سیستم (Organ System) او ټول انسان (Organism) ترمنځ اړیکه په اسانۍ درک کړئ.</p><p>راځئ لومړی دا موضوع په ډېره ساده توګه درک کړو.</p><p>کله چې موږ یو انسان ګورو، له لرې څخه داسې ښکاري چې بدن یوازې یو واحد شی دی. خو په حقیقت کې د انسان بدن د میلیونونو او حتی میلیاردونو کوچنیو ژوندیو واحدونو څخه جوړ شوی دی. دا کوچني واحدونه یو له بل سره منظم کار کوي او په ګډه د بدن د ژوند لپاره اړین فعالیتونه ترسره کوي.</p><p>د بدن جوړښت له کوچني څخه لوی ته په څو پرله‌پسې کچو تنظیم شوی دی:</p><p><strong>کیمیاوي کچه → د حجرې کچه → د نسج کچه → د غړي کچه → د غړو د سیستم کچه → د ټول بدن کچه</strong></p><p>یعنې:</p><p><strong>Chemicals → Cells → Tissues → Organs → Organ Systems → Organism</strong></p><p>دا ترتیب یوازې د حفظ کولو لپاره نه دی. د دې ترتیب په پوهېدو سره موږ زده کوو چې <strong>څنګه یو کوچنی حجره په ګډه د داسې پیچلي بدن په جوړولو کې برخه اخلي چې انسان پرې فکر کوي، حرکت کوي، تنفس کوي، امیندواره کېږي، ماشوم زېږوي او خپل ژوند ساتي.</strong></p><hr><h1>۱. د انسان بدن ته عمومي کتنه</h1><p>راځئ تصور وکړو چې یوه قابله یوې امیندواره ښځې ته معاینه کوي.</p><p>قابله د هغې د زړه درزا ګوري، تنفس یې ارزوي، د وینې فشار یې اندازه کوي، د نس اندازه ګوري او د جنین حالت ارزوي.</p><p>ممکن زده‌کوونکې ووایي:</p><blockquote><p>"زه یوازې د زړه درزا او تنفس ګورم."</p></blockquote><p>خو د اناتومي او فزیولوژي له نظره، قابله په حقیقت کې د بدن د ډېرو تنظیمي کچو پایله مشاهده کوي.</p><p>مثلاً:</p><ul><li><p>د زړه حجرې (Cardiac Cells) کار کوي.</p></li><li><p>دغه حجرې د زړه نسج (Cardiac Tissue) جوړوي.</p></li><li><p>نسجونه د زړه غړی (Heart) جوړوي.</p></li><li><p>زړه د دوراني سیستم (Cardiovascular System) برخه ده.</p></li><li><p>دوراني سیستم د تنفسي، عصبي، هورموني او نورو سیستمونو سره یوځای کار کوي.</p></li><li><p>د دغو ټولو سیستمونو ګډ فعالیت د انسان ژوند ساتي.</p></li></ul><p><strong>دلته یو ډېر مهم ټکی شته:</strong></p><blockquote><p>د بدن هېڅ مهم فعالیت یوازې د یوې برخې په وسیله نه ترسره کېږي؛ د بدن بېلابېلې برخې په منظم ډول یو له بل سره همکاري کوي.</p></blockquote><hr><h1>۲. اناتومي او فزیولوژي څه دي؟</h1><p>مخکې له دې چې د بدن د تنظیم کچې زده کړو، دوه مهم اصطلاحات باید وپېژنو.</p><h2>اناتومي (Anatomy)</h2><p><strong>اناتومي (Anatomy)</strong> هغه علم دی چې د بدن <strong>جوړښت (Structure)</strong> مطالعه کوي.</p><p>یعنې:</p><ul><li><p>بدن له څه شي جوړ دی؟</p></li><li><p>زړه چېرته موقعیت لري؟</p></li><li><p>رحم کوم ځای کې دی؟</p></li><li><p>هډوکي څنګه جوړ شوي؟</p></li><li><p>د بدن غړي له یو بل سره څه اړیکه لري؟</p></li></ul><h3>ساده مثال</h3><p>که موږ ووایو:</p><blockquote><p>زړه په سینه کې موقعیت لري او څلور خونې لري.</p></blockquote><p>موږ د زړه د <strong>جوړښت</strong> په اړه خبرې کوو، نو دا اناتومي ده.</p><hr><h2>فزیولوژي (Physiology)</h2><p><strong>فزیولوژي (Physiology)</strong> هغه علم دی چې د بدن د برخو <strong>دندې او فعالیت (Function)</strong> مطالعه کوي.</p><p>یعنې:</p><ul><li><p>زړه څنګه وینه پمپ کوي؟</p></li><li><p>سږي څنګه اکسیجن اخلي؟</p></li><li><p>پښتورګي څنګه وینه تصفیه کوي؟</p></li><li><p>رحم د امیندوارۍ پر مهال څه ډول بدلون کوي؟</p></li><li><p>هورمونونه څنګه د بدن فعالیت تنظیموي؟</p></li></ul><h3>ساده مثال</h3><p>که ووایو:</p><blockquote><p>زړه وینه د بدن مختلفو برخو ته پمپ کوي.</p></blockquote><p>دا د زړه د <strong>فعالیت</strong> په اړه خبره ده، نو فزیولوژي ده.</p><hr><h2>اناتومي او فزیولوژي یو له بل سره اړیکه لري</h2><p>د انسان په بدن کې جوړښت او دنده له یو بل څخه جلا نه دي.</p><p>دې مهم اصل ته:</p><p><strong>د جوړښت او دندې بشپړوونکې اړیکه (Complementarity of Structure and Function)</strong></p><p>ویل کېږي.</p><p>مثلاً، د زړه جوړښت داسې دی چې وینه په اغېزمن ډول پمپ کړي.</p><p>د سږو جوړښت داسې دی چې د هوا او وینې ترمنځ د ګازونو تبادله ترسره شي.</p><p>د رحم جوړښت داسې دی چې د امیندوارۍ پر مهال وده کوونکی جنین پکې ځای پر ځای شي.</p><hr><h1>۳. د انسان د بدن د تنظیم کچې</h1><p>اوس راځئ اصلي موضوع ته داخل شو.</p><p>د انسان بدن په لاندې شپږو مهمو کچو مطالعه کولی شو:</p><ol><li><p><strong>کیمیاوي کچه (Chemical Level)</strong></p></li><li><p><strong>د حجرې کچه (Cellular Level)</strong></p></li><li><p><strong>د نسج کچه (Tissue Level)</strong></p></li><li><p><strong>د غړي کچه (Organ Level)</strong></p></li><li><p><strong>د غړو د سیستم کچه (Organ System Level)</strong></p></li><li><p><strong>د ټول بدن کچه (Organism Level)</strong></p></li></ol><p>د دې لپاره چې موضوع په ذهن کې ښه پاتې شي، دا لړۍ داسې تصور کړئ:</p><p><strong>مالیکول → حجره → نسج → غړی → سیستم → انسان</strong></p><hr><h1>۴. لومړۍ کچه: کیمیاوي کچه (Chemical Level)</h1><p>راځئ له تر ټولو کوچنۍ کچې پیل وکړو.</p><p>د انسان بدن له کیمیاوي موادو څخه جوړ شوی دی.</p><p>په دې کچه کې موږ د:</p><ul><li><p>اټوم (Atom)</p></li><li><p>مالیکول (Molecule)</p></li><li><p>او کیمیاوي مرکباتو (Chemical Compounds)</p></li></ul><p>په اړه خبرې کوو.</p><h2>اټوم (Atom) څه شی دی؟</h2><p><strong>اټوم (Atom)</strong> د یو عنصر تر ټولو کوچنی واحد دی چې د هغه عنصر ځانګړتیاوې ساتي.</p><p>په بدن کې بېلابېل عناصر شتون لري، لکه:</p><ul><li><p>اکسیجن (Oxygen)</p></li><li><p>کاربن (Carbon)</p></li><li><p>هایدروجن (Hydrogen)</p></li><li><p>نایتروجن (Nitrogen)</p></li><li><p>کلسیم (Calcium)</p></li><li><p>فاسفورس (Phosphorus)</p></li><li><p>سودیم (Sodium)</p></li><li><p>پوتاشیم (Potassium)</p></li></ul><p>دا عناصر د بدن د جوړښت او فعالیت لپاره ضروري دي.</p><hr><h2>مالیکول (Molecule)</h2><p>کله چې دوه یا څو اټومونه د کیمیاوي اړیکې له لارې یوځای شي، مالیکول جوړېږي.</p><p>د مثال په توګه:</p><p><strong>اوبه (Water)</strong> د هایدروجن او اکسیجن له اټومونو څخه جوړې دي.</p><p>د اوبو کیمیاوي فورمول:</p><p><strong>H₂O</strong></p><p>اوبه د انسان د بدن لپاره ډېرې مهمې دي، ځکه د بدن ډېری کیمیاوي او فزیولوژیکي فعالیتونه په اوبو پورې تړلي دي.</p><hr><h2>د بدن مهم کیمیاوي مواد</h2><p>په بدن کې ځینې مهم مالیکولونه عبارت دي له:</p><ul><li><p>اوبه (Water)</p></li><li><p>ګلوکوز (Glucose)</p></li><li><p>پروټینونه (Proteins)</p></li><li><p>شحمیات (Lipids)</p></li><li><p>کاربوهایډریټونه (Carbohydrates)</p></li><li><p>DNA</p></li><li><p>ATP</p></li><li><p>الکترولایتونه (Electrolytes)</p></li></ul><h3>ATP څه شی دی؟</h3><p><strong>ATP (Adenosine Triphosphate)</strong> د حجرې لپاره د انرژۍ مهمه سرچینه ده.</p><p>په ساده ډول یې داسې تصور کړئ:</p><blockquote><p>ATP د حجرې د انرژۍ د "کوچنۍ پیسې" په څېر دی.</p></blockquote><p>حجره د ATP له انرژۍ څخه د خپلو ډېرو فعالیتونو لپاره استفاده کوي.</p><hr><h1>۵. ولې کیمیاوي کچه مهمه ده؟</h1><p>ممکن تاسو له ځانه وپوښتئ:</p><blockquote><p>"که زه قابله کېږم، ولې باید اټوم او مالیکول زده کړم؟"</p></blockquote><p>ځواب ډېر مهم دی.</p><p>ځکه چې د بدن ټول فعالیتونه په پای کې د کیمیاوي تعاملاتو (Chemical Reactions) پر بنسټ ترسره کېږي.</p><p>مثلاً:</p><p><strong>اکسیجن → حجرې → انرژي → د بدن فعالیت</strong></p><p>که حجرې اکسیجن ترلاسه نه کړي، د انرژۍ تولید کمېږي او د بدن مهم فعالیتونه ګډوډېږي.</p><p>په امیندواره ښځه کې د مور او جنین د ژوند لپاره د اکسیجن مناسب انتقال ځانګړی اهمیت لري.</p><hr><h1>۶. دوهمه کچه: د حجرې کچه (Cellular Level)</h1><p>اوس له کیمیاوي کچې څخه یوه مرحله پورته ځو.</p><h2>حجره (Cell) څه ده؟</h2><p><strong>حجره (Cell)</strong> د ژوند تر ټولو کوچنی اساسي واحد دی چې د ژوند اړین فعالیتونه ترسره کولی شي.</p><p>په ساده ډول:</p><blockquote><p>حجره د انسان د بدن یوه کوچنۍ ژوندۍ کاري واحده ده.</p></blockquote><p>د دې لپاره چې موضوع ښه درک کړئ، د یوه ښار مثال واخلئ.</p><p>یو ښار له ډېرو کورونو، دفترونو، روغتونونو، فابریکو او نورو ودانیو جوړ وي.</p><p>همداسې انسان هم له ډېرو حجرو جوړ دی.</p><hr><h1>۷. حجره ولې مهمه ده؟</h1><p>هره حجره خپل ځانګړي فعالیتونه ترسره کوي.</p><p>ځینې حجرې:</p><ul><li><p>عصبي پیغامونه انتقالوي.</p></li><li><p>عضلات حرکت کوي.</p></li><li><p>وینه انتقالوي.</p></li><li><p>اکسیجن انتقالوي.</p></li><li><p>هورمونونه تولیدوي.</p></li><li><p>دفاعي فعالیت ترسره کوي.</p></li><li><p>نوي حجرې جوړوي.</p></li></ul><p>د مثال په توګه:</p><p><strong>د وینې سره حجرې (Red Blood Cells)</strong> د اکسیجن په انتقال کې مهم رول لري.</p><p><strong>عصبي حجرې (Neurons)</strong> عصبي پیغامونه انتقالوي.</p><p><strong>عضلاتي حجرې (Muscle Cells)</strong> د انقباض او حرکت لپاره کار کوي.</p><hr><h1>۸. د حجرې مهمې برخې</h1><p>د لومړي سمستر لپاره د حجرې څو مهمې برخې باید وپېژنو.</p><h2>حجره غشا (Cell Membrane)</h2><p><strong>Cell Membrane</strong> د حجرې بهرنۍ نرۍ پرده ده.</p><p>دا د حجرې او بهرني چاپېریال ترمنځ سرحد جوړوي.</p><p>دا د دې په تنظیم کې مرسته کوي چې کوم مواد حجرې ته داخل شي او کوم مواد له حجرې څخه بهر شي.</p><h3>ساده مثال</h3><p>د کور دروازه تصور کړئ.</p><p>هر څوک د کور دننه او بهر په ازاد ډول نه تېرېږي؛ دروازه د داخلېدو او وتلو په تنظیم کې مرسته کوي.</p><p>د حجرې غشا هم ورته دنده لري، خو بیولوژیکي او ډېر پیچلي ډول.</p><hr><h2>هسته (Nucleus)</h2><p><strong>Nucleus</strong> د ډېرو حجرو د کنټرول مهم مرکز دی.</p><p>په هسته کې <strong>DNA</strong> شتون لري.</p><p>DNA د جنیټیک معلوماتو (Genetic Information) مهمه ذخیره ده.</p><hr><h2>سایتوپلازم (Cytoplasm)</h2><p><strong>Cytoplasm</strong> د حجرې دننۍ برخه ده چې په کې ګڼ شمېر حجروي فعالیتونه ترسره کېږي او حجرې غړي پکې موجود وي.</p><hr><h2>مایتوکونډریا (Mitochondria)</h2><p><strong>Mitochondria</strong> د حجرې د انرژۍ په تولید کې مهم رول لري.</p><p>په ساده مثال:</p><blockquote><p>که حجره یوه فابریکه وي، مایتوکونډریا د هغې د انرژۍ د تولید له مهمو مرکزونو څخه دی.</p></blockquote><hr><h1>۹. درېیمه کچه: نسج (Tissue Level)</h1><p>اوس یوه مهمه پوښتنه:</p><blockquote><p>که حجرې سره یوځای شي، څه جوړوي؟</p></blockquote><p>ځواب:</p><p><strong>نسج (Tissue)</strong></p><h2>نسج څه شی دی؟</h2><p><strong>نسج (Tissue)</strong> د ورته یا اړوندو حجرو یوه ډله ده چې په ګډه یوه ځانګړې دنده ترسره کوي.</p><p>یعنې:</p><p><strong>حجرې → نسج</strong></p><hr><h1>۱۰. د نسجونو څلور اساسي ډولونه</h1><p>د انسان په بدن کې څلور اساسي نسجي ډولونه شته:</p><ol><li><p><strong>اپیټیلیال نسج (Epithelial Tissue)</strong></p></li><li><p><strong>ارتباطي نسج (Connective Tissue)</strong></p></li><li><p><strong>عضلاتي نسج (Muscle Tissue)</strong></p></li><li><p><strong>عصبي نسج (Nervous Tissue)</strong></p></li></ol><p>راځئ هر یو په ساده ډول وګورو.</p><hr><h2>۱۰.۱ اپیټیلیال نسج (Epithelial Tissue)</h2><p>دا نسج د بدن ځینې بهرني او داخلي سطحې پوښي.</p><p>مثلاً:</p><ul><li><p>د پوستکي سطحه</p></li><li><p>د بدن ځینې داخلي لارې</p></li><li><p>د ځینو غړو داخلي سطحې</p></li></ul><p>د دې نسج دندو کې پوښښ، ساتنه، جذب او ترشح شاملېدای شي.</p><h3>د قابلې لپاره مثال</h3><p>د تناسلي او تولیدي لارې ځینې داخلي سطحې له اپیټیلیال حجرو او نسجونو څخه جوړې دي.</p><hr><h1>۱۱. ارتباطي نسج (Connective Tissue)</h1><p>ارتباطي نسج د بدن د برخو په ملاتړ، نښلولو، ساتنې او نورو فعالیتونو کې برخه اخلي.</p><p>مثالونه:</p><ul><li><p>هډوکی (Bone)</p></li><li><p>وینه (Blood)</p></li><li><p>غضروف (Cartilage)</p></li><li><p>شحمي نسج (Adipose Tissue)</p></li></ul><h3>مهم ټکی</h3><p>ممکن تاسو حیران شئ چې وینه ولې نسج ګڼل کېږي؟</p><p>ځکه وینه د ځانګړو حجرو او د هغوی د مایع چاپېریال څخه جوړه ده او د بدن د ارتباط او انتقال مهمه دنده ترسره کوي.</p><hr><h1>۱۲. عضلاتي نسج (Muscle Tissue)</h1><p>عضلاتي نسج د انقباض (Contraction) وړتیا لري.</p><p>دا د:</p><ul><li><p>حرکت</p></li><li><p>د بدن د غړو حرکت</p></li><li><p>د زړه د پمپ کولو</p></li><li><p>او ځینو داخلي فعالیتونو</p></li></ul><p>لپاره مهم دی.</p><p>د رحم عضلاتي برخه په ځانګړې توګه د قابلې لپاره ډېره مهمه ده.</p><p>د ولادت پر مهال د رحم عضلات منظم انقباض کوي چې د جنین د زیږون په بهیر کې مرسته کوي.</p><hr><h1>۱۳. عصبي نسج (Nervous Tissue)</h1><p>عصبي نسج د پیغامونو د ترلاسه کولو، پروسس کولو او انتقال لپاره مهم دی.</p><p>عصبي سیستم د بدن د ارتباطي شبکې په څېر کار کوي.</p><p>د مثال په توګه:</p><p>کله چې یوه ښځه درد احساس کړي:</p><p><strong>حسي اخیستونکي → عصبي پیغام → عصبي سیستم → مغز → احساس او ځواب</strong></p><p>دا موضوع وروسته د درد، ولادت او عصبي فزیولوژي په درسونو کې لا پراخه زده کوو.</p><hr><h1>۱۴. څلورمه کچه: غړی (Organ Level)</h1><p>اوس څو ډوله نسجونه سره یوځای کېږي او یو <strong>غړی (Organ)</strong> جوړوي.</p><h2>غړی څه شی دی؟</h2><p><strong>غړی (Organ)</strong> د دوو یا ډېرو نسجونو داسې منظم جوړښت دی چې یو یا څو ځانګړي فعالیتونه ترسره کوي.</p><p>مثلاً:</p><p><strong>زړه (Heart)</strong> یو غړی دی.</p><p>زړه یوازې له عضلاتو نه دی جوړ.</p><p>په زړه کې:</p><ul><li><p>عضلاتي نسج</p></li><li><p>عصبي نسج</p></li><li><p>ارتباطي نسج</p></li><li><p>اپیټیلیال نسج</p></li></ul><p>او نور جوړښتي عناصر شتون لري.</p><p>دا ټول په ګډه د زړه د فعالیت لپاره کار کوي.</p><hr><h1>۱۵. د رحم مثال (Uterus)</h1><p>د قابلې لپاره تر ټولو مهم مثالونو څخه یو <strong>رحم (Uterus)</strong> دی.</p><p>رحم یو غړی دی چې د ښځینه تولیدي سیستم (Female Reproductive System) مهمه برخه ده.</p><p>رحم څو ډوله نسجونه لري چې په ګډه یې جوړښت او دنده ممکنه کوي.</p><p>د رحم مهمې برخې په عمومي ډول:</p><ul><li><p>د رحم داخلي پوښ (Endometrium)</p></li><li><p>عضلاتي طبقه (Myometrium)</p></li><li><p>بهرنۍ پوښ (Perimetrium)</p></li></ul><p>د امیندوارۍ پر مهال رحم د جنین د ودې لپاره مهم چاپېریال برابروي.</p><p>د ولادت پر مهال د رحم عضلاتي انقباضات د ولادت په بهیر کې مهم رول لري.</p><hr><h1>۱۶. پنځمه کچه: د غړو سیستم (Organ System Level)</h1><p>اوس تصور وکړئ چې څو غړي چې له یو بل سره اړوند فعالیت لري، په ګډه کار وکړي.</p><p>نو:</p><p><strong>د غړو سیستم (Organ System)</strong> جوړېږي.</p><p>د مثال په توګه:</p><p><strong>زړه + وینه + د وینې رګونه = دوراني سیستم (Cardiovascular System)</strong></p><p>دا سیستم د بدن په بېلابېلو برخو کې د وینې انتقال کې مرسته کوي.</p><hr><h1>۱۷. د انسان د بدن مهم سیستمونه</h1><p>د انسان بدن څو مهم سیستمونه لري، لکه:</p><table><thead><tr><th>سیستم</th><th>English Term</th><th>مهمه دنده</th></tr></thead><tbody><tr><td>پوښښي سیستم</td><td>Integumentary System</td><td>ساتنه او د بدن سطحه</td></tr><tr><td>هډوکيز سیستم</td><td>Skeletal System</td><td>ملاتړ او ساتنه</td></tr><tr><td>عضلاتي سیستم</td><td>Muscular System</td><td>حرکت</td></tr><tr><td>عصبي سیستم</td><td>Nervous System</td><td>چټک کنټرول او ارتباط</td></tr><tr><td>هورموني سیستم</td><td>Endocrine System</td><td>کیمیاوي تنظیم</td></tr><tr><td>دوراني سیستم</td><td>Cardiovascular System</td><td>د وینې انتقال</td></tr><tr><td>لمفاوي/معافیتي سیستم</td><td>Lymphatic/Immune System</td><td>دفاع او د مایعاتو تنظیم</td></tr><tr><td>تنفسي سیستم</td><td>Respiratory System</td><td>د اکسیجن او کاربن ډای اکساید تبادله</td></tr><tr><td>هضمي سیستم</td><td>Digestive System</td><td>د خوړو هضم او جذب</td></tr><tr><td>ادراري سیستم</td><td>Urinary System</td><td>د فاضله موادو او مایعاتو تنظیم</td></tr><tr><td>تولیدي سیستم</td><td>Reproductive System</td><td>تولید مثل</td></tr></tbody></table><hr><h1>۱۸. شپږمه کچه: ټول بدن (Organism Level)</h1><p>اوس د ټولو کچو تر ټولو لوړې کچې ته رسېږو.</p><p>کله چې:</p><p><strong>کیمیاوي مواد → حجرې → نسجونه → غړي → د غړو سیستمونه</strong></p><p>په منظم ډول سره یوځای کار وکړي، نو:</p><p><strong>ټول ژوندی انسان (Organism)</strong> جوړېږي.</p><p>انسان یوازې د غړو مجموعه نه ده.</p><p>انسان یو <strong>منظم، ژوندی او متقابل سیستم</strong> دی.</p><hr><h1>۱۹. د بدن د تنظیم کچو بشپړه سلسله</h1><p>راځئ ټول مفهوم یو ځل په یوه سلسله کې وګورو:</p><p><strong>اتومونه (Atoms)</strong><br>↓<br><strong>مالیکولونه (Molecules)</strong><br>↓<br><strong>حجرې (Cells)</strong><br>↓<br><strong>نسجونه (Tissues)</strong><br>↓<br><strong>غړي (Organs)</strong><br>↓<br><strong>د غړو سیستمونه (Organ Systems)</strong><br>↓<br><strong>ټول انسان (Organism)</strong></p><h3>یو مثال</h3><p>راځئ د زړه له لارې یې وګورو:</p><p><strong>پروټینونه او نور کیمیاوي مواد</strong><br>↓<br><strong>د زړه حجرې (Cardiac Cells)</strong><br>↓<br><strong>د زړه عضلاتي نسج (Cardiac Muscle Tissue)</strong><br>↓<br><strong>زړه (Heart)</strong><br>↓<br><strong>دوراني سیستم (Cardiovascular System)</strong><br>↓<br><strong>د انسان بدن (Human Organism)</strong></p><p>دا سلسله د نن ورځې د درس تر ټولو مهمه مفکوره ده.</p><hr><h1>۲۰. د ښار مثال</h1><p>راځئ د انسان بدن د یوه ښار سره مقایسه کړو.</p><p>تصور وکړئ چې یو لوی ښار لکه کابل ولرو.</p><ul><li><p>کوچني ساختماني مواد = کیمیاوي مواد</p></li><li><p>کورونه = حجرې</p></li><li><p>د کورونو یوه ځانګړې سیمه = نسج</p></li><li><p>روغتون، پوهنتون یا فابریکه = غړی</p></li><li><p>د ترانسپورت شبکه = یو سیستم</p></li><li><p>ټول ښار = ټول انسان</p></li></ul><p>خو پام وکړئ!</p><p>دا یوازې یوه تشبیه ده. انسان د ښار په څېر مصنوعي جوړ شوی سیستم نه دی؛ انسان یو ژوندی بیولوژیکي سیستم دی.</p><p>د تشبیه اصلي هدف دا دی چې پوه شو:</p><blockquote><p>کوچنۍ برخې په منظم ډول سره یوځای کېږي او لوی او پیچلي فعالیتونه رامنځته کوي.</p></blockquote><hr><h1>۲۱. ولې د بدن کچې یو له بل سره تړلې دي؟</h1><p>دا ډېر مهمه پوښتنه ده.</p><p>که د حجرې په کچه ستونزه رامنځته شي، ممکن نسج اغېزمن شي.</p><p>که نسج خراب شي، غړی اغېزمنېدای شي.</p><p>که غړی خراب شي، د غړو سیستم اغېزمنېدای شي.</p><p>او که یو مهم سیستم په کافي اندازه کار ونه کړي، د ټول بدن فعالیت اغېزمنېدای شي.</p><h3>مثال</h3><p>که د زړه ځینې حجرې خپل عادي فعالیت له لاسه ورکړي:</p><p><strong>حجره → د زړه نسج → زړه → دوراني سیستم → ټول بدن</strong></p><p>نو موږ وینو چې د یوې کوچنۍ کچې بدلون ممکن په لوړو کچو اغېز وکړي.</p><hr><h1>۲۲. د بدن سیستمونه یوازې نه کار کوي</h1><p>دلته یو ډېر مهم ټکی شته.</p><p>په بدن کې سیستمونه د جلا جلا ماشینونو په څېر نه دي.</p><p>دوی په دوامداره توګه یو له بل سره اړیکه لري.</p><h3>مثال: منډه وهل</h3><p>کله چې یو انسان منډه وهي:</p><ol><li><p>عضلات انرژي غواړي.</p></li><li><p>حجرې د انرژۍ لپاره اکسیجن ته اړتیا لري.</p></li><li><p>تنفسي سیستم اکسیجن اخلي.</p></li><li><p>دوراني سیستم اکسیجن عضلاتو ته رسوي.</p></li><li><p>زړه د وینې جریان زیاتوي.</p></li><li><p>عصبي سیستم د حرکت تنظیم کوي.</p></li><li><p>هورموني سیستم هم د بدن د اړتیا سره سم بدلونونه رامنځته کوي.</p></li></ol><p>نو یو ساده فعالیت لکه منډه وهل د څو سیستمونو ګډ کار ته اړتیا لري.</p><hr><h1>۲۳. د بدن کچې او هومیوستازس</h1><p>یو بل مهم مفهوم:</p><p><strong>هومیوستازس (Homeostasis)</strong></p><p>هومیوستازس د بدن هغه وړتیا ده چې خپل داخلي چاپېریال په نسبتاً ثابت حالت کې وساتي، سره له دې چې بهرني شرایط بدلېږي.</p><p>مثلاً:</p><ul><li><p>د بدن تودوخه تنظیمېږي.</p></li><li><p>د وینې ګلوکوز تنظیمېږي.</p></li><li><p>د اوبو اندازه تنظیمېږي.</p></li><li><p>د وینې فشار تنظیمېږي.</p></li><li><p>د اکسیجن او کاربن ډای اکساید کچه تنظیمېږي.</p></li></ul><h3>ساده مثال</h3><p>که هوا ډېره ګرمه شي، بدن د خولې له لارې د تودوخې په کمولو کې مرسته کوي.</p><p>که بدن اوبه له لاسه ورکړي، تنده زیاتېږي او بدن د اوبو د ساتلو لپاره ځینې تنظیمي میکانیزمونه فعالوي.</p><hr><h1>۲۴. د قابلې لپاره د هومیوستازس اهمیت</h1><p>قابله باید پوه شي چې د ناروغ یا امیندواره ښځې بدن هڅه کوي خپل داخلي حالت متوازن وساتي.</p><p>کله چې یو مهم بدلون رامنځته شي، لکه:</p><ul><li><p>ډېره وینه له لاسه ورکول</p></li><li><p>شدید کم‌اوبۍ</p></li><li><p>د اکسیجن کمښت</p></li><li><p>لوړه تبه</p></li><li><p>شدید فزیولوژیک فشار</p></li></ul><p>نو د بدن عادي توازن اغېزمنېدای شي.</p><p>د بدن د تنظیم کچو پوهه له قابلې سره مرسته کوي چې پوه شي:</p><blockquote><p>ستونزه یوازې په یوه نښه کې نه ده؛ ممکن د بدن په څو کچو اغېز ولري.</p></blockquote><hr><h1>۲۵. د امیندوارۍ سره اړیکه</h1><p>امیندوارۍ (Pregnancy) د بدن د څو سیستمونو ګډ فعالیت ته اړتیا لري.</p><p>کله چې ښځه امیندواره شي، یوازې رحم نه بدلېږي.</p><p>د بدن ګڼ سیستمونه له نوي حالت سره ځان عیاروي.</p><p>مثلاً:</p><ul><li><p>دوراني سیستم بدلونونه کوي.</p></li><li><p>تنفسي سیستم له بدلونونو سره مخ کېږي.</p></li><li><p>هورموني سیستم مهم رول لري.</p></li><li><p>ادراري سیستم بدلونونه تجربه کوي.</p></li><li><p>د تولیدي سیستم فعالیت بدلېږي.</p></li><li><p>د مور د بدن حجرې او نسجونه د نوي فزیولوژیک حالت سره سم کار کوي.</p></li></ul><p>نو قابله باید د بدن د یوې برخې تر څنګ د ټول بدن اړیکه هم درک کړي.</p><hr><h1>۲۶. ولادت او د بدن د تنظیم کچې</h1><p>د ولادت (Labour) پر مهال هم د بدن بېلابېلې کچې په ګډه کار کوي.</p><p>د رحم عضلاتي حجرې:</p><p>↓</p><p>عضلاتي نسج:</p><p>↓</p><p>رحم:</p><p>↓</p><p>د ښځینه تولیدي سیستم:</p><p>↓</p><p>د عصبي او هورموني سیستمونو سره تعامل:</p><p>↓</p><p>د ولادت فزیولوژیک بهیر.</p><p>دا موږ ته ښيي چې د ولادت درک یوازې د رحم د مطالعه کولو معنا نه لري.</p><hr><h1>۲۷. شیدې ورکول او د بدن د سیستمونو اړیکه</h1><p>د شیدو ورکولو (Breastfeeding) پر مهال هم ګڼې کچې او سیستمونه سره یوځای کار کوي.</p><p>د تیونو (Mammary Glands) ځانګړي حجرې او نسجونه د شیدو په جوړولو او ترشح کې برخه اخلي.</p><p>هورموني سیستم د شیدو جوړولو او خارجولو په تنظیم کې مهم رول لري.</p><p>عصبي محرکات هم د دې پروسې سره تړاو لري.</p><p>نو:</p><p><strong>حجره → نسج → غړی → سیستم → ټول بدن</strong></p><p>د شیدو ورکولو په فزیولوژي کې هم لیدل کېږي.</p><hr><h1>۲۸. سناریو ۱: د امیندواره ښځې زړه</h1><h3>سناریو</h3><p>یوه امیندواره ښځه روغتیايي مرکز ته مراجعه کوي. قابله د هغې د زړه درزا ارزوي.</p><h3>پوښتنه</h3><p>ولې د زړه فعالیت د ټول بدن لپاره مهم دی؟</p><h3>علمي تشریح</h3><p>زړه یو <strong>غړی (Organ)</strong> دی.</p><p>زړه له بېلابېلو نسجونو څخه جوړ شوی او د عضلاتي نسج د انقباض له لارې وینه پمپ کوي.</p><p>وینه د دوراني سیستم له لارې د بدن حجرو ته اکسیجن او نور ضروري مواد رسوي.</p><h3>د قابلې لپاره اهمیت</h3><p>قابله باید پوه شي چې د زړه فعالیت یوازې د زړه یوه موضوع نه ده؛ دا د ټول بدن د اکسیجن او موادو له انتقال سره تړاو لري.</p><h3>د سناریو اصلي درس</h3><p><strong>غړی د سیستم برخه ده، او سیستم د ټول بدن د فعالیت لپاره له نورو سیستمونو سره ګډ کار کوي.</strong></p><hr><h1>۲۹. سناریو ۲: د ولادت پر مهال د رحم انقباض</h1><h3>سناریو</h3><p>یوه ښځه د ولادت په حالت کې ده. رحم په منظم ډول انقباض کوي.</p><h3>پوښتنه</h3><p>دا فعالیت په کومه کچه پیل کېږي؟</p><h3>علمي تشریح</h3><p>د رحم عضلاتي حجرې (Muscle Cells) انقباض کوي.</p><p>دغه حجرې عضلاتي نسج جوړوي.</p><p>عضلاتي نسج د رحم په غړي کې برخه لري.</p><p>رحم د تولیدي سیستم برخه ده.</p><p>نو موږ کولای شو سلسله داسې وګورو:</p><p><strong>حجره → نسج → رحم → تولیدي سیستم → ولادت</strong></p><h3>د قابلې لپاره اهمیت</h3><p>د رحم د عضلاتي فعالیت درک د ولادت د فزیولوژي د زده کړې لپاره بنسټیز دی.</p><h3>اصلي درس</h3><p>د غړي فعالیت د هغې له حجرو او نسجونو څخه جلا نه دی.</p><hr><h1>۳۰. سناریو ۳: د اکسیجن کمښت</h1><h3>سناریو</h3><p>یوه ناروغه ښځه داسې نښې لري چې ښيي بدن یې کافي اکسیجن نه ترلاسه کوي.</p><h3>پوښتنه</h3><p>ولې د اکسیجن کمښت یوازې د سږو ستونزه نه ده؟</p><h3>علمي تشریح</h3><p>تنفسي سیستم اکسیجن اخلي، خو یوازې سږي کافي نه دي.</p><p>اکسیجن باید:</p><p><strong>سږي → وینه → زړه → د وینې رګونه → حجرې</strong></p><p>ته انتقال شي.</p><p>حجرې بیا اکسیجن د خپل میتابولیزم (Metabolism) لپاره کاروي.</p><h3>د قابلې لپاره اهمیت</h3><p>د مور او جنین لپاره د اکسیجن مناسب انتقال حیاتي اهمیت لري.</p><h3>اصلي درس</h3><p>د بدن سیستمونه یو له بل سره تړلي دي.</p><hr><h1>۳۱. سناریو ۴: کم‌اوبۍ</h1><h3>سناریو</h3><p>یوه امیندواره ښځه د کانګې او نس ناستې له امله د بدن ډېر مایعات له لاسه ورکوي.</p><h3>پوښتنه</h3><p>ولې د اوبو کمښت د بدن په څو کچو اغېز کولی شي؟</p><h3>علمي تشریح</h3><p>اوبه د بدن په کیمیاوي کچه کې مهمه برخه ده.</p><p>حجرې د مناسب فعالیت لپاره اوبو ته اړتیا لري.</p><p>که حجرې مناسب مایع چاپېریال ونه لري، د نسجونو او غړو فعالیت اغېزمنېدای شي.</p><p>په پایله کې د بدن د سیستمونو نورمال فعالیت هم ګډوډېدای شي.</p><h3>د قابلې لپاره اهمیت</h3><p>قابله باید پوه شي چې د مایعاتو حالت د بدن له عمومي فزیولوژي سره تړاو لري.</p><h3>اصلي درس</h3><p>د بدن د یوې کچې بدلون د نورو کچو پر فعالیت اغېز کولی شي.</p><hr><h1>۳۲. سناریو ۵: د ماشوم لومړنی ژوند</h1><h3>سناریو</h3><p>یو نوی زېږېدلی ماشوم له زیږون وروسته خپل لومړني تنفسي حرکات پیلوي.</p><h3>پوښتنه</h3><p>ایا یوازې سږي د دې پروسې مسؤل دي؟</p><h3>علمي تشریح</h3><p>نه.</p><p>تنفس د:</p><ul><li><p>عصبي سیستم</p></li><li><p>تنفسي سیستم</p></li><li><p>دوراني سیستم</p></li><li><p>عضلاتي سیستم</p></li><li><p>او حجروي فعالیت</p></li></ul><p>ترمنځ همغږۍ ته اړتیا لري.</p><h3>د قابلې لپاره اهمیت</h3><p>د نوي زېږېدلي ماشوم د لومړني حالت په ارزونه کې قابله باید د بدن د سیستمونو ګډ فعالیت درک کړي.</p><h3>اصلي درس</h3><p>ژوند د څو سیستمونو د همغږي فعالیت پایله ده.</p><hr><h1>۳۳. سناریو ۶: د مور او جنین اړیکه</h1><h3>سناریو</h3><p>یوه امیندواره ښځه د جنین د ودې لپاره د مناسبې روغتیايي پاملرنې اړتیا لري.</p><h3>پوښتنه</h3><p>ولې د مور عمومي روغتیا د جنین لپاره مهمه ده؟</p><h3>علمي تشریح</h3><p>د مور بدن د هغې د حجرو، نسجونو، غړو او سیستمونو د ګډ فعالیت له لارې خپل داخلي چاپېریال ساتي.</p><p>د مور د دوراني او تنفسي سیستمونو فعالیت د جنین لپاره هم مهم دی.</p><h3>د قابلې لپاره اهمیت</h3><p>قابله باید مور د یوه بشپړ ژوندی سیستم په توګه وګوري، نه یوازې د رحم د یوې برخې په توګه.</p><h3>اصلي درس</h3><p>د مور او جنین روغتیا د ګڼو فزیولوژیکي پروسو له تعامل سره تړلې ده.</p><hr><h1>۳۴. عامې تېروتنې او غلط فهمۍ</h1><h2>غلط تصور ۱</h2><p><strong>غلط تصور:</strong> حجره او نسج یو شی دي.</p><p><strong>سم حقیقت:</strong> حجره (Cell) یو اساسي ژوندی واحد دی، خو نسج (Tissue) د ورته یا اړوندو حجرو منظمه ډله ده.</p><p><strong>تشریح:</strong> څو حجرې چې په ګډه یوه ځانګړې دنده ترسره کوي، نسج جوړوي.</p><hr><h2>غلط تصور ۲</h2><p><strong>غلط تصور:</strong> هر غړی یوازې له یوه ډول نسج څخه جوړ شوی.</p><p><strong>سم حقیقت:</strong> غړي عموماً له څو ډوله نسجونو څخه جوړ شوي وي.</p><p><strong>تشریح:</strong> زړه، رحم او نور غړي د بېلابېلو نسجونو ګډ جوړښت لري.</p><hr><h2>غلط تصور ۳</h2><p><strong>غلط تصور:</strong> هر سیستم په بشپړه توګه مستقل کار کوي.</p><p><strong>سم حقیقت:</strong> د بدن سیستمونه له یو بل سره متقابل کار کوي.</p><p><strong>تشریح:</strong> د مثال په توګه تنفسي سیستم اکسیجن اخلي، خو دوراني سیستم یې حجرو ته رسوي.</p><hr><h2>غلط تصور ۴</h2><p><strong>غلط تصور:</strong> د بدن د تنظیم کچې یوازې د حفظ لپاره دي.</p><p><strong>سم حقیقت:</strong> دا کچې د بدن د جوړښت او فعالیت د درک لپاره یوه اساسي فکري نقشه ده.</p><p><strong>تشریح:</strong> که موږ پوه شو چې حجره څنګه نسج جوړوي او نسج څنګه د غړي برخه کېږي، د ناروغۍ او فزیولوژي مفهوم هم ښه درک کوو.</p><hr><h2>غلط تصور ۵</h2><p><strong>غلط تصور:</strong> د بدن ستونزه تل یوازې په یوه غړي کې وي.</p><p><strong>سم حقیقت:</strong> یوه ستونزه ممکن په څو کچو او څو سیستمونو اغېز وکړي.</p><hr><h1>۳۵. د بدن د تنظیم کچو اوسط پرتله</h1><table><thead><tr><th>کچه</th><th>اساسي جوړښت</th><th>اصلي مفهوم</th></tr></thead><tbody><tr><td>کیمیاوي</td><td>اټومونه او مالیکولونه</td><td>د ژوند کیمیاوي بنسټ</td></tr><tr><td>حجره</td><td>حجره</td><td>د ژوند اساسي واحد</td></tr><tr><td>نسج</td><td>د حجرو ډله</td><td>ګډه دنده</td></tr><tr><td>غړی</td><td>څو نسجونه</td><td>ځانګړی جوړښت او فعالیت</td></tr><tr><td>سیستم</td><td>څو غړي</td><td>ګډ فزیولوژیک فعالیت</td></tr><tr><td>ټول بدن</td><td>ټول سیستمونه</td><td>بشپړ ژوندی انسان</td></tr></tbody></table><hr><h1>۳۶. د استاد پوښتنې او د زده‌کوونکو فکر</h1><h3>استاد:</h3><p>که زه تاسو څخه وپوښتم:</p><blockquote><p>"زړه ولې یوازې یوه حجره نه ده؟"</p></blockquote><p>تاسو باید ووایاست:</p><p>ځکه چې زړه یو پیچلی غړی دی چې له څو ډوله نسجونو څخه جوړ شوی او د وینې د پمپ کولو ځانګړې دنده لري.</p><h3>استاد:</h3><p>که ووایم:</p><blockquote><p>"عضلاتي حجره څه جوړوي؟"</p></blockquote><p>تاسو باید د اړوند نسج مفهوم ته فکر وکړئ.</p><h3>استاد:</h3><p>که ووایم:</p><blockquote><p>"زړه له کومې لوړې کچې سره تړاو لري؟"</p></blockquote><p>ځواب:</p><p><strong>دوراني سیستم (Cardiovascular System)</strong></p><h3>استاد:</h3><p>که ووایم:</p><blockquote><p>"دوراني سیستم یوازې کار کوي؟"</p></blockquote><p>نه.</p><p>دا له تنفسي، عصبي، هورموني او نورو سیستمونو سره تعامل کوي.</p><hr><h1>۳۷. په کلینیکي ژوند کې عملي استعمال</h1><p>د قابلې لپاره د بدن د تنظیم کچو پوهه یوازې د امتحان لپاره نه ده.</p><p>کله چې قابله یوه ښځه معاینه کوي، باید له ځان سره دا پوښتنه ولري:</p><blockquote><p>"زه کومه نښه وینم، او د بدن په کومه کچه او کوم سیستم کې یې ممکنه اړیکه ده؟"</p></blockquote><p>مثلاً که ناروغه:</p><ul><li><p>ستړې وي،</p></li><li><p>د زړه درزا یې بدله شوې وي،</p></li><li><p>تنفس یې غیرنورمال وي،</p></li><li><p>تبه ولري،</p></li><li><p>یا د بدن عمومي حالت یې بدل شوی وي،</p></li></ul><p>قابله باید د بدن فعالیت په یوه پراخه فزیولوژیک چوکاټ کې درک کړي.</p><p>د دې موضوع پوهه د راتلونکو درسونو لپاره هم اساس جوړوي، لکه:</p><ul><li><p>د وینې فزیولوژي</p></li><li><p>د تنفس فزیولوژي</p></li><li><p>د زړه فزیولوژي</p></li><li><p>د تولیدي سیستم فزیولوژي</p></li><li><p>امیندوارۍ</p></li><li><p>ولادت</p></li><li><p>د نوي زېږېدلي ماشوم فزیولوژي</p></li></ul><hr><h1>۳۸. د قابلې لپاره د دې موضوع اهمیت</h1><p>ګرانو زده‌کوونکو، د قابلې لپاره دا موضوع ځکه مهمه ده چې قابله د انسان له بدن سره مستقیم کار کوي.</p><h3>په امیندوارۍ کې</h3><p>قابله باید پوه شي چې د مور بدن څنګه له امیندوارۍ سره عیارېږي.</p><h3>د مور په روغتیا کې</h3><p>قابله باید د بدن د عادي فعالیت بنسټونه وپېژني، څو غیرعادي بدلونونه په ښه توګه درک کړي.</p><h3>د جنین په روغتیا کې</h3><p>د مور د بدن فزیولوژیک حالت د جنین له حالت سره مهمې اړیکې لري.</p><h3>د ولادت پر مهال</h3><p>د رحم، عضلاتو، عصبي سیستم او هورموني تنظیم ګډ فعالیت مهم دی.</p><h3>له ولادت وروسته</h3><p>د مور بدن د امیندوارۍ له حالت څخه وروسته نوي فزیولوژیک حالت ته ځي.</p><h3>د شیدو ورکولو پر مهال</h3><p>د تیونو غړي، نسجونه، حجرې، هورمونونه او عصبي میکانیزمونه په ګډه کار کوي.</p><h3>د نوي زېږېدلي ماشوم په پاملرنه کې</h3><p>قابله باید د نوي ماشوم تنفس، دوراني فعالیت، تودوخه او نور مهم فعالیتونه د بدن د سیستمونو د ګډ کار په توګه درک کړي.</p><hr><h1>۳۹. د موضوع د زده کړې یوه اسانه ذهني نقشه</h1><p>کله چې تاسو د انسان بدن په اړه هر نوی موضوع زده کوئ، دا پوښتنې له ځانه وکړئ:</p><p><strong>۱. دا څه شی دی؟</strong></p><p><strong>۲. له کومو حجرو څخه جوړ شوی؟</strong></p><p><strong>۳. کوم نسجونه پکې شامل دي؟</strong></p><p><strong>۴. کوم غړی دی؟</strong></p><p><strong>۵. د کوم سیستم برخه ده؟</strong></p><p><strong>۶. له کومو نورو سیستمونو سره کار کوي؟</strong></p><p><strong>۷. د ټول بدن لپاره یې اهمیت څه دی؟</strong></p><p>دا طریقه تاسو له ساده حفظ څخه د <strong>کلینیکي فکر کولو (Clinical Thinking)</strong> پر لور بیایي.</p><hr><h1>۴۰. آنلاین انفرادي زده‌کړنیز فعالیت</h1><p>ځکه چې دا درس د آنلاین <strong>LMS (Learning Management System)</strong> لپاره دی، فعالیت باید د هر زده‌کوونکي لپاره په انفرادي ډول ترسره شي.</p><h2>د فعالیت نوم</h2><p><strong>"د بدن د تنظیم کچې جوړې کړه"</strong></p><h3>موخه</h3><p>زده‌کوونکی باید وکولای شي د بدن د تنظیم کچې له کوچنۍ څخه تر لویې پورې په سمه توګه تنظیم او د هرې کچې مثال ورکړي.</p><h3>اړین مواد</h3><ul><li><p>آنلاین LMS</p></li><li><p>د درس محتوا</p></li><li><p>Drag-and-Drop یا ترتیب کولو پوښتنه</p></li><li><p>د بدن د تنظیم کچو مثالونه</p></li></ul><h3>کړنلاره</h3><p>زده‌کوونکي ته لاندې اصطلاحات په ګډه او ګډوډ ترتیب وړاندې کېږي:</p><ul><li><p>Heart</p></li><li><p>Cell</p></li><li><p>Tissue</p></li><li><p>Organ System</p></li><li><p>Molecule</p></li><li><p>Organism</p></li></ul><p>زده‌کوونکی باید دا له کوچنۍ څخه تر لویې کچې پورې منظم کړي.</p><p>صحیح ترتیب:</p><p><strong>Molecule → Cell → Tissue → Organ → Organ System → Organism</strong></p><h3>دوهمه برخه</h3><p>زده‌کوونکي ته لاندې مثالونه وړاندې کېږي:</p><ul><li><p>Heart</p></li><li><p>Cardiac muscle tissue</p></li><li><p>Cardiac cell</p></li><li><p>Cardiovascular system</p></li></ul><p>هغه باید د هر یوه کچه وټاکي.</p><h3>د بحث پوښتنې</h3><ol><li><p>ولې زړه یو غړی دی؟</p></li><li><p>ولې عضلاتي حجرې نسج جوړوي؟</p></li><li><p>ولې د زړه فعالیت د دوراني سیستم سره تړلی دی؟</p></li><li><p>که حجرې سم فعالیت ونه کړي، په لوړو کچو څه اغېز راتللی شي؟</p></li></ol><h3>تمه کېدونکې زده‌کړیزه پایله</h3><p>د فعالیت تر بشپړېدو وروسته زده‌کوونکی باید وکولای شي:</p><ul><li><p>د بدن شپږ اساسي تنظیمي کچې تشریح کړي.</p></li><li><p>د هرې کچې مثال ورکړي.</p></li><li><p>د حجرې، نسج، غړي او سیستم ترمنځ اړیکه بیان کړي.</p></li><li><p>د بدن د سیستمونو د متقابل کار مفهوم درک کړي.</p></li></ul><hr><h1>۴۱. مهمې اصطلاحات</h1><table><thead><tr><th>پښتو اصطلاح</th><th>English Term</th><th>ساده تشریح</th></tr></thead><tbody><tr><td>اناتومي</td><td>Anatomy</td><td>د بدن د جوړښت علم</td></tr><tr><td>فزیولوژي</td><td>Physiology</td><td>د بدن د فعالیت علم</td></tr><tr><td>کیمیاوي کچه</td><td>Chemical Level</td><td>د اټومونو او مالیکولونو کچه</td></tr><tr><td>اټوم</td><td>Atom</td><td>د عنصر اساسي کوچنی واحد</td></tr><tr><td>مالیکول</td><td>Molecule</td><td>د دوو یا ډېرو اټومونو کیمیاوي جوړښت</td></tr><tr><td>حجره</td><td>Cell</td><td>د ژوند اساسي واحد</td></tr><tr><td>د حجرې غشا</td><td>Cell Membrane</td><td>د حجرې بهرنی تنظیموونکی پوښ</td></tr><tr><td>هسته</td><td>Nucleus</td><td>د ډېرو حجرو مهم کنټرولي مرکز</td></tr><tr><td>DNA</td><td>DNA</td><td>جنیټیک معلومات ساتي</td></tr><tr><td>مایتوکونډریا</td><td>Mitochondria</td><td>د حجرې د انرژۍ په تولید کې مهمه برخه</td></tr><tr><td>سایتوپلازم</td><td>Cytoplasm</td><td>د حجرې دننۍ برخه</td></tr><tr><td>نسج</td><td>Tissue</td><td>د ورته یا اړوندو حجرو منظمه ډله</td></tr><tr><td>اپیټیلیال نسج</td><td>Epithelial Tissue</td><td>پوښښ او نورو فعالیتونو کې برخه اخلي</td></tr><tr><td>ارتباطي نسج</td><td>Connective Tissue</td><td>ملاتړ، نښلولو او انتقال کې رول لري</td></tr><tr><td>عضلاتي نسج</td><td>Muscle Tissue</td><td>د انقباض او حرکت لپاره</td></tr><tr><td>عصبي نسج</td><td>Nervous Tissue</td><td>د عصبي پیغامونو انتقال او تنظیم</td></tr><tr><td>غړی</td><td>Organ</td><td>له څو نسجونو جوړ ځانګړی جوړښت</td></tr><tr><td>د غړو سیستم</td><td>Organ System</td><td>څو اړوند غړي چې ګډ فعالیت کوي</td></tr><tr><td>ټول بدن</td><td>Organism</td><td>بشپړ ژوندی انسان</td></tr><tr><td>دوراني سیستم</td><td>Cardiovascular System</td><td>د وینې انتقال</td></tr><tr><td>تنفسي سیستم</td><td>Respiratory System</td><td>د ګازونو تبادله</td></tr><tr><td>تولیدي سیستم</td><td>Reproductive System</td><td>د تولید مثل اړوند فعالیتونه</td></tr><tr><td>رحم</td><td>Uterus</td><td>د ښځینه تولیدي سیستم مهم غړی</td></tr><tr><td>امیندوارۍ</td><td>Pregnancy</td><td>په رحم کې د جنین د ودې دوره</td></tr><tr><td>ولادت</td><td>Labour</td><td>د ماشوم د زیږون فزیولوژیک بهیر</td></tr><tr><td>هومیوستازس</td><td>Homeostasis</td><td>د داخلي چاپېریال نسبي ثبات ساتل</td></tr><tr><td>میتابولیزم</td><td>Metabolism</td><td>په بدن کې د کیمیاوي تعاملاتو مجموعه</td></tr><tr><td>ATP</td><td>Adenosine Triphosphate</td><td>د حجرو مهمه انرژي وړونکې ماده</td></tr><tr><td>حجراتي کچه</td><td>Cellular Level</td><td>د حجرې د تنظیم کچه</td></tr><tr><td>د جوړښت او دندې اړیکه</td><td>Complementarity of Structure and Function</td><td>جوړښت د خپلې دندې سره تړاو لري</td></tr></tbody></table><hr><h1>۴۲. د درس لنډیز</h1><p>ګرانو زده‌کوونکو، د نن ورځې تر ټولو مهم ټکي دا دي:</p><ul><li><p>د انسان بدن یو منظم او پیچلی ژوندی سیستم دی.</p></li><li><p>د بدن جوړښت له کوچنۍ کچې څخه تر لویې کچې پورې تنظیم شوی.</p></li><li><p>لومړۍ کچه <strong>کیمیاوي کچه (Chemical Level)</strong> ده.</p></li><li><p>دوهمه کچه <strong>حجراتي کچه (Cellular Level)</strong> ده.</p></li><li><p>درېیمه کچه <strong>د نسج کچه (Tissue Level)</strong> ده.</p></li><li><p>څلورمه کچه <strong>د غړي کچه (Organ Level)</strong> ده.</p></li><li><p>پنځمه کچه <strong>د غړو د سیستم کچه (Organ System Level)</strong> ده.</p></li><li><p>شپږمه کچه <strong>د ټول بدن کچه (Organism Level)</strong> ده.</p></li><li><p>حجره د ژوند اساسي واحد دی.</p></li><li><p>نسج د حجرو منظمه ډله ده چې ګډه دنده ترسره کوي.</p></li><li><p>غړي عموماً له څو ډوله نسجونو جوړ دي.</p></li><li><p>څو اړوند غړي په ګډه د غړو سیستم جوړوي.</p></li><li><p>د بدن سیستمونه له یو بل څخه مستقل نه دي.</p></li><li><p>د بدن فعالیت د ټولو کچو د منظم تعامل پایله ده.</p></li><li><p>هومیوستازس د بدن د داخلي چاپېریال د نسبي ثبات ساتلو لپاره مهم دی.</p></li><li><p>د قابلې لپاره د دې موضوع پوهه د مور، جنین او نوي زېږېدلي ماشوم د فزیولوژۍ د درک بنسټ جوړوي.</p></li><li><p>د بدن د کچو د پوهېدو تر ټولو مهم هدف <strong>درک کول دي، نه یوازې حفظ کول.</strong></p></li></ul><hr><h1>۴۳. د پوهې ارزونه</h1><h2>برخه اول: پنځه Multiple Choice Questions</h2><h3>پوښتنه ۱</h3><p>د انسان د بدن تر ټولو کوچنی اساسي ژوندی واحد کوم دی؟</p><p><strong>A. نسج (Tissue)</strong><br><strong>B. حجره (Cell)</strong><br><strong>C. غړی (Organ)</strong><br><strong>D. سیستم (Organ System)</strong></p><p><strong>سم ځواب: B. حجره (Cell)</strong></p><h3>ولې؟</h3><p>حجره د ژوند اساسي واحد دی. نسج له حجرو جوړېږي، غړی له نسجونو جوړېږي او سیستم له اړوندو غړو څخه جوړېږي.</p><hr><h3>پوښتنه ۲</h3><p>کوم ترتیب د بدن د تنظیم کچې له کوچنۍ څخه تر لویې پورې په سمه توګه ښيي؟</p><p><strong>A. حجره → مالیکول → نسج → غړی → سیستم</strong></p><p><strong>B. مالیکول → حجره → نسج → غړی → سیستم → ټول بدن</strong></p><p><strong>C. نسج → حجره → غړی → مالیکول → سیستم</strong></p><p><strong>D. غړی → نسج → حجره → سیستم → مالیکول</strong></p><p><strong>سم ځواب: B</strong></p><h3>ولې؟</h3><p>کیمیاوي جوړښتونه حجرې جوړوي، حجرې نسجونه جوړوي، نسجونه غړي جوړوي، غړي سیستمونه جوړوي او سیستمونه د ټول بدن په فعالیت کې برخه اخلي.</p><hr><h3>پوښتنه ۳</h3><p>رحم (Uterus) په کومه کچه کې راځي؟</p><p><strong>A. کیمیاوي کچه</strong></p><p><strong>B. حجراتي کچه</strong></p><p><strong>C. د غړي کچه</strong></p><p><strong>D. د مالیکول کچه</strong></p><p><strong>سم ځواب: C. د غړي کچه</strong></p><h3>ولې؟</h3><p>رحم یو غړی دی چې له څو ډول نسجونو څخه جوړ شوی او ځانګړي فعالیتونه ترسره کوي.</p><hr><h3>پوښتنه ۴</h3><p>ولې د زړه فعالیت د تنفسي سیستم سره اړیکه لري؟</p><p><strong>A. ځکه زړه هوا تولیدوي.</strong></p><p><strong>B. ځکه تنفسي سیستم اکسیجن اخلي او دوراني سیستم یې د وینې له لارې انتقالوي.</strong></p><p><strong>C. ځکه زړه د سږو برخه ده.</strong></p><p><strong>D. ځکه سږي وینه تولیدوي.</strong></p><p><strong>سم ځواب: B</strong></p><h3>ولې؟</h3><p>سږي اکسیجن وینې ته داخلوي، او زړه او د وینې رګونه د دې وینې په انتقال کې مرسته کوي. له همدې امله دواړه سیستمونه یو له بل سره نږدې اړیکه لري.</p><hr><h3>پوښتنه ۵</h3><p>که د زړه د عضلاتو حجرې په سمه توګه کار ونه کړي، تر ټولو منطقي پایله کومه ده؟</p><p><strong>A. یوازې حجره اغېزمنېږي او نور هېڅ شی نه بدلېږي.</strong></p><p><strong>B. د حجرې بدلون ممکن د نسج، زړه، دوراني سیستم او په پای کې د ټول بدن پر فعالیت اغېز وکړي.</strong></p><p><strong>C. یوازې پوستکی اغېزمنېږي.</strong></p><p><strong>D. یوازې هډوکي اغېزمنېږي.</strong></p><p><strong>سم ځواب: B</strong></p><h3>ولې؟</h3><p>د بدن تنظیمي کچې یو له بل سره تړلې دي. د یوې مهمې حجرې یا نسج ستونزه د اړوند غړي او سیستم پر فعالیت اغېز کولی شي.</p><hr><h1>۴۴. True / False</h1><h3>پوښتنه ۶</h3><p><strong>نسج د ورته یا اړوندو حجرو له یوې منظمې ډلې څخه جوړېږي.</strong></p><p><strong>ځواب: True — صحیح</strong></p><p><strong>تشریح:</strong> نسجونه د حجرو داسې منظمې ډلې دي چې په ګډه ځانګړی فعالیت ترسره کوي.</p><hr><h3>پوښتنه ۷</h3><p><strong>هر غړی یوازې له یوه ډول نسج څخه جوړ شوی وي.</strong></p><p><strong>ځواب: False — غلط</strong></p><p><strong>تشریح:</strong> غړي عموماً له څو ډوله نسجونو څخه جوړ وي چې په ګډه د غړي فعالیت ترسره کوي.</p><hr><h3>پوښتنه ۸</h3><p><strong>د انسان د بدن ټول سیستمونه له یو بل څخه په بشپړه توګه مستقل دي.</strong></p><p><strong>ځواب: False — غلط</strong></p><p><strong>تشریح:</strong> د بدن سیستمونه په دوامداره توګه یو له بل سره تعامل کوي. د مثال په توګه، تنفسي او دوراني سیستمونه د اکسیجن د انتقال لپاره ګډ کار کوي.</p><hr><h1>۴۵. لنډ ځوابي پوښتنې</h1><h3>پوښتنه ۹</h3><p><strong>حجره، نسج او غړي ترمنځ اړیکه په خپل عبارت کې تشریح کړئ.</strong></p><h3>نمونه ځواب</h3><p>حجره د ژوند اساسي واحد دی. د ورته یا اړوندو حجرو منظمې ډلې نسج جوړوي، او څو ډوله نسجونه په ګډه یو غړی جوړوي چې ځانګړی فعالیت ترسره کوي.</p><hr><h3>پوښتنه ۱۰</h3><p><strong>ولې د بدن د تنظیم کچو پوهه د یوې قابلې لپاره مهمه ده؟</strong></p><h3>نمونه ځواب</h3><p>ځکه قابله باید پوه شي چې د انسان بدن د حجرو، نسجونو، غړو او سیستمونو یو منظم مجموعه ده. دا پوهه له قابلې سره مرسته کوي چې د امیندوارۍ، ولادت، د مور روغتیا، د نوي زېږېدلي ماشوم او د بدن د نورمال او غیرنورمال فعالیتونو ترمنځ اړیکې په ښه توګه درک کړي.</p><hr><h1>۴۶. د کلینیکي سناریو مثال</h1><p>یوه ۲۶ کلنه امیندواره ښځه روغتیايي مرکز ته مراجعه کوي. هغه وایي چې د امیندوارۍ په وروستیو میاشتو کې د فعالیت پر مهال ژر ستړې کېږي. قابله د هغې عمومي حالت ارزوي او د زړه درزا او تنفس ته پام کوي.</p><p>قابله پوهېږي چې د بدن فعالیت یوازې د یوه غړي په وسیله نه ترسره کېږي.</p><p>د زړه حجرې د زړه د عضلاتي نسج برخه جوړوي. د زړه نسج د زړه د غړي په فعالیت کې مرسته کوي. زړه د دوراني سیستم برخه ده. دوراني سیستم له تنفسي سیستم سره کار کوي، څو اکسیجن د بدن حجرو ته ورسېږي.</p><p>په امیندوارۍ کې د مور بدن له فزیولوژیکي بدلونونو سره عیارېږي، نو قابله باید د بدن عمومي فعالیت د یوه بشپړ سیستم په توګه درک کړي.</p><h3>پوښتنې</h3><p><strong>۱. د زړه حجرې په کومه کچه کې راځي؟</strong></p><p><strong>۲. د زړه عضلاتي نسج څه ډول کچه ده؟</strong></p><p><strong>۳. زړه د بدن په کومه کچه کې شامل دی؟</strong></p><p><strong>۴. د زړه او تنفسي سیستم ترمنځ ولې اړیکه ضروري ده؟</strong></p><p><strong>۵. ولې قابله باید د یوه نښې په ارزونه کې د بدن ټول سیستمونه په پام کې ونیسي؟</strong></p><hr><h1>۴۷. د استاد تفصیلي تشریح</h1><h3>د لومړۍ پوښتنې ځواب</h3><p>د زړه حجرې د <strong>حجراتي کچې (Cellular Level)</strong> برخه دي.</p><p>حجرې د بدن د ژوند اساسي واحدونه دي.</p><hr><h3>د دوهمې پوښتنې ځواب</h3><p>د زړه عضلاتي نسج د <strong>نسجي کچې (Tissue Level)</strong> مثال دی.</p><p>د زړه ګڼې عضلاتي حجرې په ګډه عضلاتي نسج جوړوي.</p><hr><h3>د درېیمې پوښتنې ځواب</h3><p>زړه د <strong>غړي کچې (Organ Level)</strong> مثال دی.</p><p>زړه له څو ډوله نسجونو جوړ شوی او ځانګړې دنده، یعنې د وینې پمپ کول، ترسره کوي.</p><hr><h3>د څلورمې پوښتنې ځواب</h3><p>تنفسي سیستم اکسیجن بدن ته داخلوي او دوراني سیستم د وینې له لارې اکسیجن حجرو ته رسوي.</p><p>نو:</p><p><strong>سږي → اکسیجن → وینه → زړه/رګونه → حجرې</strong></p><p>دا د بدن د سیستمونو د متقابل کار یوه مهمه بېلګه ده.</p><hr><h3>د پنځمې پوښتنې ځواب</h3><p>ځکه چې د بدن سیستمونه یو له بل سره تړلي دي.</p><p>که یوه نښه لکه ستړیا موجوده وي، قابله باید د هغې د فزیولوژیکي مفهوم په اړه فکر وکړي او د ناروغ حالت په عمومي ډول وارزوي.</p><p>دا د <strong>کلینیکي فکر (Clinical Thinking)</strong> یوه مهمه برخه ده.</p><hr><h1>۴۸. وروستی استاد پیغام</h1><p>ګرانو زده‌کوونکو!</p><p>زه غواړم چې د نن ورځې موضوع یوازې حفظ نه کړئ.</p><p>که تاسو یوازې دا جمله حفظ کړئ:</p><p><strong>حجره → نسج → غړی → سیستم → ټول بدن</strong></p><p>ممکن سبا یې هیره کړئ.</p><p>خو که تاسو پوه شئ چې <strong>ولې حجرې سره یوځای کېږي، ولې نسج جوړېږي، ولې څو نسجونه غړی جوړوي، ولې غړي سیستم جوړوي او ولې ټول سیستمونه یو له بل سره کار کوي</strong>، نو بیا به Anatomy &amp; Physiology ستاسو لپاره ډېر اسانه شي.</p><p>هر کله چې د بدن یوه برخه مطالعه کوئ، له ځانه وپوښتئ:</p><blockquote><p><strong>دا څه شی دی؟ له څه څخه جوړ شوی؟ څه دنده لري؟ له کومو نورو برخو سره کار کوي؟ او د انسان د ژوند لپاره ولې مهم دی؟</strong></p></blockquote><p>تاسو چې د قابلې په توګه د انسان له بدن سره کار کوئ، ستاسو اصلي ځواک یوازې په معلوماتو کې نه دی؛ <strong>اصلي ځواک مو په دې کې دی چې د بدن فعالیت درک کړئ.</strong></p><p><strong>اناتومي حفظ نه کړئ؛ اناتومي درک کړئ.<br>فزیولوژي یوازې مه تکراروئ؛ د بدن د کار کولو منطق یې زده کړئ.</strong></p><p>همدا درک به تاسو له یوې عادي زده‌کوونکې څخه یوې مسلکي او باوري قابلې ته نږدې کړي.</p>', 'rtl', 'url', 'https://www.youtube.com/watch?v=8Z1C7B98KEY', NULL, 26, 'intro', 4, TRUE, 2, TRUE, '2026-09-13 04:39:29'),
(330, 33, 'اناتومیک دریځ، مستوي او د لوري اصطلاحات', '<p dir="rtl" style="text-align:right">د بدن د برخو د دقیق بیان لپاره یوه ګډه ژبه پکاریږي — دا ژبه له اناتومیک دریځ څخه پیل کیږي.</p>', '<h1>اناتومیک دریځ، مستوي او د لوري اصطلاحات</h1><h3>Anatomical Position, Planes and Directional Terms</h3><h2>د درس پیل</h2><h3 dir="rtl"></h3><p>په تېر درس کې مو زده کړل چې د انسان بدن په بېلابېلو تنظیمي کچو جوړ شوی او حجرې، نسجونه، غړي او د غړو سیستمونه له یو بل سره تړلي دي.</p><p>اوس یوه ډېره مهمه پوښتنه مطرح کېږي:</p><p><strong>که یوه قابله وغواړي د ناروغ د بدن د یوې برخې دقیق ځای بلې قابلې، ډاکټر یا روغتیايي کارکوونکي ته تشریح کړي، څنګه به یې تشریح کوي؟</strong></p><p>د مثال په توګه، که قابله ووایي:</p><blockquote><p>«د ناروغې په لاس کې درد دی.»</p></blockquote><p>دا معلومات ډېر عمومي دي.</p><p>خو که ووایي:</p><blockquote><p>«د ناروغې د ښي لاس په مخکینۍ برخه کې د څنګل څخه لاندې درد موجود دی.»</p></blockquote><p>نو معلومات ډېر دقیق شول.</p><p>په روغتیايي علومو کې د بدن د برخو د موقعیت، جهت او اړیکې د دقیقې تشریح لپاره ځانګړې اصطلاحات کارېږي. د دې اصطلاحاتو د سم استعمال لپاره موږ لومړی باید <strong>اناتومیک دریځ (Anatomical Position)</strong>، بیا <strong>اناتومیک مستوي (Anatomical Planes)</strong> او وروسته <strong>د لوري اصطلاحات (Directional Terms)</strong> زده کړو.</p><p>دا اصطلاحات یوازې د حفظ لپاره نه دي؛ بلکې د یوې قابلې لپاره د ناروغ د ارزونې، د معاینې د ثبت، د راپور لیکلو او د روغتیايي ټیم ترمنځ د دقیقې اړیکې لپاره ډېر مهم دي.</p><hr><h1>۱. اناتومیک دریځ</h1><h2>Anatomical Position</h2><h3 dir="rtl"></h3><p>راځئ لومړی د بدن لپاره یو ثابت او معیاري دریځ وټاکو.</p><p><strong>اناتومیک دریځ (Anatomical Position)</strong> هغه معیاري دریځ دی چې د انسان د بدن د برخو موقعیت او جهتونه پرې تشریح کېږي.</p><p>په دې دریځ کې انسان:</p><ul><li><p>نېغ ولاړ وي.</p></li><li><p>سر او سترګې مخامخ وي.</p></li><li><p>مخ د مخامخ لوري پر طرف وي.</p></li><li><p>لاسونه د بدن دواړو خواوو ته ځوړند وي.</p></li><li><p>د لاسونو ورغوي مخامخ لوري ته وي.</p></li><li><p>ګوتې ښکته وي.</p></li><li><p>پښې یو بل ته نږدې یا تقریباً موازي وي.</p></li><li><p>د پښو ګوتې مخامخ لوري ته وي.</p></li></ul><h3>ډېر مهم ټکی</h3><h3 dir="rtl"></h3><p>کله چې موږ وایو:</p><p><strong>Right / ښی</strong></p><p>او</p><p><strong>Left / کیڼ</strong></p><p>نو مقصد د <strong>ناروغ ښی او کیڼ</strong> دی، نه د روغتیايي کارکوونکي ښی او کیڼ.</p><p>دا موضوع د نوي زده‌کوونکو لپاره ډېره مهمه ده.</p><hr><h2>ولې اناتومیک دریځ مهم دی؟</h2><h3 dir="rtl"></h3><p>تصور وکړئ چې دوه روغتیايي کارکوونکي د یوې ناروغې د بدن په اړه خبرې کوي.</p><p>که یو کس وایي:</p><blockquote><p>«د زړه ترڅنګ چپ لوري ته درد لري.»</p></blockquote><p>او بل کس یې له خپل دریځه تشریح کوي، ممکن ګډوډي رامنځته شي.</p><p>خو کله چې ټول روغتیايي کارکوونکي د <strong>اناتومیک دریځ</strong> پر بنسټ خبرې کوي، د بدن د هرې برخې موقعیت په یو شان ډول تشریح کېږي.</p><h3>د قابلې لپاره اهمیت</h3><h3 dir="rtl"></h3><p>په قابله‌ګۍ کې دا اصطلاحات د لاندې مواردو لپاره مهم دي:</p><ul><li><p>د امیندواره ښځې د فزیکي معاینې ثبتول</p></li><li><p>د درد ځای مشخصول</p></li><li><p>د زخم موقعیت ثبتول</p></li><li><p>د پړسوب یا وینې بهېدنې موقعیت بیانول</p></li><li><p>د جنین د موقعیت په اړه د زده کړې لپاره</p></li><li><p>د طبي راپور لیکل</p></li><li><p>د ډاکټر او قابلې ترمنځ اړیکه</p></li><li><p>د ناروغ د بدن د برخو دقیق تشریح</p></li></ul><hr><h1>۲. اناتومیک مستوي</h1><h2>Anatomical Planes</h2><h3 dir="rtl"></h3><p>اوس فرض کړئ چې موږ د انسان بدن په ذهن کې د یوې درې‌بعدي نقشې په توګه ګورو.</p><p>د بدن د داخلي جوړښتونو د ښه تشریح لپاره موږ تصور کوو چې بدن د ځانګړو فرضي کرښو یا سطحو په وسیله پرې شوی دی.</p><p>دې فرضي سطحو ته:</p><p><strong>اناتومیک مستوي (Anatomical Planes)</strong> ویل کېږي.</p><p>دا واقعي چاقو یا حقیقي پرېکون نه دی؛ بلکې د بدن د جوړښتونو د تشریح او مطالعې لپاره ذهني او علمي تصور دی.</p><p>د بدن درې مهم مستوي دي:</p><ol><li><p><strong>ساجیټل مستوي (Sagittal Plane)</strong></p></li><li><p><strong>فرونټل/کورونل مستوي (Frontal/Coronal Plane)</strong></p></li><li><p><strong>ټرانسورس/افقي مستوي (Transverse/Horizontal Plane)</strong></p></li></ol><hr><h1>۳. ساجیټل مستوي</h1><h2>Sagittal Plane</h2><h3 dir="rtl"></h3><p>ساجیټل مستوي بدن په:</p><p><strong>ښي او کیڼ برخو</strong></p><p>وېشي.</p><p>یعنې که موږ د بدن له سر څخه تر پښو پورې داسې فرضي سطح تصور کړو چې بدن ښي او کیڼ لوري ته جلا کړي، دا ساجیټل مستوي دی.</p><h3>ساده تصور</h3><h3 dir="rtl"></h3><p>د انسان بدن تصور کړئ.</p><p>یوه فرضي کرښه د بدن له منځ څخه د سر، غاړې، سینې او نس له لارې ښکته روانه ده.</p><p>دا بدن په دوو اړخونو وېشي:</p><p><strong>ښی ← | → کیڼ</strong></p><h3>Mid-sagittal / Median Plane</h3><h3 dir="rtl"></h3><p>که ساجیټل مستوي بدن په تقریباً مساوي ښي او کیڼ برخو ووېشي، ورته:</p><p><strong>منځنی ساجیټل مستوي (Midsagittal/Median Plane)</strong></p><p>ویل کېږي.</p><hr><h1>۴. فرونټل یا کورونل مستوي</h1><h2>Frontal / Coronal Plane</h2><h3 dir="rtl"></h3><p>دا مستوي بدن په:</p><p><strong>مخکینۍ او شاتنۍ برخو</strong></p><p>وېشي.</p><p>یعنې:</p><p><strong>مخکینۍ برخه (Anterior)</strong></p><p>او</p><p><strong>شاتنۍ برخه (Posterior)</strong></p><p>ترې جوړېږي.</p><h3>ساده مثال</h3><h3 dir="rtl"></h3><p>د انسان مخې ته یوه فرضي عمودي سطح تصور کړئ چې بدن په مخکینۍ او شاتنۍ برخه ووېشي.</p><p>نو:</p><p><strong>مخ ← | → شا</strong></p><p>دا <strong>Frontal/Coronal Plane</strong> دی.</p><h3>د قابلې لپاره مثال</h3><h3 dir="rtl"></h3><p>کله چې د امیندواره ښځې د نس د مخکینۍ برخې او شاتنۍ برخې موقعیتونه تشریح کوو، د دې مفکورې درک مرسته کوي چې بدن په کوم جهت تشریح کېږي.</p><hr><h1>۵. ټرانسورس یا افقي مستوي</h1><h2>Transverse / Horizontal Plane</h2><h3 dir="rtl"></h3><p>ټرانسورس مستوي بدن په:</p><p><strong>پورته او ښکته برخو</strong></p><p>وېشي.</p><p>یعنې:</p><p><strong>پورته برخه (Superior)</strong></p><p>او</p><p><strong>ښکته برخه (Inferior)</strong></p><p>تصور کېږي.</p><h3>ساده مثال</h3><h3 dir="rtl"></h3><p>تصور وکړئ چې د انسان د نس په یوه ټاکلي لوړوالي کې یوه افقي فرضي سطح تېره شوې ده.</p><p>د هغې پورته برخه او ښکته برخه جلا کېږي.</p><p>نو:</p><p><strong>پورته ↑</strong></p><hr><p><strong>ښکته ↓</strong></p><p>دا <strong>Transverse Plane</strong> دی.</p><hr><h1>۶. د درې مستویو اساسي توپیر</h1><h3 dir="rtl"></h3><table><thead><tr><th>مستوي</th><th>English</th><th>بدن په څه وېشي؟</th></tr></thead><tbody><tr><td>ساجیټل</td><td>Sagittal</td><td>ښی او کیڼ</td></tr><tr><td>فرونټل/کورونل</td><td>Frontal/Coronal</td><td>مخکینۍ او شاتنۍ</td></tr><tr><td>ټرانسورس/افقي</td><td>Transverse/Horizontal</td><td>پورته او ښکته</td></tr></tbody></table><h3>د حفظ لپاره ساده طریقه</h3><h3 dir="rtl"></h3><p><strong>Sagittal → Right &amp; Left</strong></p><p><strong>Frontal → Front &amp; Back</strong></p><p><strong>Transverse → Upper &amp; Lower</strong></p><hr><h1>۷. اوس د لوري اصطلاحاتو ته راځو</h1><h2>Directional Terms</h2><h3 dir="rtl"></h3><p>اوس موږ د دې درس تر ټولو مهمې برخې ته رسېږو.</p><p>کله چې یوه قابله د بدن یوه برخه تشریح کوي، باید وکولای شي ووایي چې هغه برخه د بلې برخې په نسبت چېرته ده.</p><p>د دې لپاره د <strong>Directional Terms</strong> څخه استفاده کېږي.</p><p>راځئ هره اصطلاح په ساده ډول زده کړو.</p><hr><h1>۸. Superior او Inferior</h1><h2>Superior – پورته / فوقاني</h2><h3 dir="rtl"></h3><p><strong>Superior</strong> معنا لري:</p><p>یوه برخه د بلې برخې په نسبت <strong>پورته</strong> ده.</p><h3>مثال:</h3><h3 dir="rtl"></h3><p>سر د غاړې په نسبت <strong>Superior</strong> دی.</p><p>یعنې:</p><p><strong>سر د غاړې څخه پورته دی.</strong></p><h3>قابله‌ګۍ مثال</h3><h3 dir="rtl"></h3><p>رحم (Uterus) د امیندوارۍ په جریان کې د حوض څخه پورته لوري ته پراخېږي.</p><hr><h2>Inferior – ښکته / تحتاني</h2><h3 dir="rtl"></h3><p><strong>Inferior</strong> معنا لري:</p><p>یوه برخه د بلې برخې په نسبت <strong>ښکته</strong> ده.</p><h3>مثال:</h3><h3 dir="rtl"></h3><p>پښې د نس په نسبت <strong>Inferior</strong> دي.</p><p>یعنې:</p><p><strong>پښې د نس څخه ښکته دي.</strong></p><h3>د یادولو آسانه لار</h3><h3 dir="rtl"></h3><p><strong>Superior = پورته</strong></p><p><strong>Inferior = ښکته</strong></p><hr><h1>۹. Anterior او Posterior</h1><h2>Anterior – مخکینی</h2><h3 dir="rtl"></h3><p><strong>Anterior</strong> هغه برخه ده چې د بدن د مخ لوري ته نږدې وي.</p><h3>مثال:</h3><h3 dir="rtl"></h3><p>سینه د ملا په نسبت <strong>Anterior</strong> ده.</p><p>یعنې:</p><p>سینه د ملا څخه مخ ته ده.</p><hr><h2>Posterior – شاتنی</h2><h3 dir="rtl"></h3><p><strong>Posterior</strong> هغه برخه ده چې د بدن شاتني لوري ته نږدې وي.</p><h3>مثال:</h3><h3 dir="rtl"></h3><p>ملا د سینې په نسبت <strong>Posterior</strong> ده.</p><h3>د یادولو لپاره:</h3><h3 dir="rtl"></h3><p><strong>Anterior → Front</strong></p><p><strong>Posterior → Back</strong></p><hr><h1>۱۰. Medial او Lateral</h1><h3 dir="rtl"></h3><p>دا دوه اصطلاحات د قابلې لپاره ډېر مهم دي.</p><h2>Medial – منځنۍ خوا ته</h2><h3 dir="rtl"></h3><p><strong>Medial</strong> معنا لري:</p><p>یوه برخه د بدن د منځنۍ کرښې <strong>(Midline)</strong> ته نږدې ده.</p><h3>مثال:</h3><h3 dir="rtl"></h3><p>پوزه د سترګو په نسبت <strong>Medial</strong> ده.</p><p>ولې؟</p><p>ځکه پوزه د بدن د منځنۍ کرښې ته د سترګو په پرتله نږدې ده.</p><hr><h2>Lateral – اړخیز / له منځنۍ کرښې څخه لرې</h2><h3 dir="rtl"></h3><p><strong>Lateral</strong> معنا لري:</p><p>یوه برخه د بدن له منځنۍ کرښې څخه لیرې ده.</p><h3>مثال:</h3><h3 dir="rtl"></h3><p>غوږونه د پوزې په نسبت <strong>Lateral</strong> دي.</p><p>ولې؟</p><p>ځکه غوږونه د بدن د منځنۍ کرښې څخه د پوزې په پرتله لرې دي.</p><h3>ساده یادونه:</h3><h3 dir="rtl"></h3><p><strong>Medial = Middle ته نږدې</strong></p><p><strong>Lateral = Side ته نږدې</strong></p><hr><h1>۱۱. Proximal او Distal</h1><h3 dir="rtl"></h3><p>دا اصطلاحات په ځانګړي ډول د لاسونو او پښو لپاره ډېر کارېږي.</p><h2>Proximal – نږدې</h2><h3 dir="rtl"></h3><p><strong>Proximal</strong> معنا لري:</p><p>د بدن د یوې برخې یا د اندام د اتصال ځای ته نږدې.</p><h3>مثال:</h3><h3 dir="rtl"></h3><p>څنګل د لاس د ګوتو په نسبت <strong>Proximal</strong> دی.</p><p>ځکه څنګل د لاس د بدن سره د اتصال ځای ته نږدې دی.</p><hr><h2>Distal – لرې</h2><h3 dir="rtl"></h3><p><strong>Distal</strong> معنا لري:</p><p>د بدن د یوې برخې یا د اندام د اتصال ځای څخه لرې.</p><h3>مثال:</h3><h3 dir="rtl"></h3><p>ګوتې د څنګل په نسبت <strong>Distal</strong> دي.</p><h3>ساده یادونه:</h3><h3 dir="rtl"></h3><p><strong>Proximal = نږدې</strong></p><p><strong>Distal = لرې</strong></p><hr><h1>۱۲. Superficial او Deep</h1><h2>Superficial – سطحي</h2><h3 dir="rtl"></h3><p><strong>Superficial</strong> معنا لري:</p><p>د بدن سطحې ته نږدې.</p><h3>مثال:</h3><h3 dir="rtl"></h3><p>پوستکی د عضلاتو په نسبت <strong>Superficial</strong> دی.</p><hr><h2>Deep – ژور</h2><h3 dir="rtl"></h3><p><strong>Deep</strong> معنا لري:</p><p>د بدن د سطحې څخه دننه یا ژور.</p><h3>مثال:</h3><h3 dir="rtl"></h3><p>عضلات د پوستکي په نسبت <strong>Deep</strong> دي.</p><h3>د قابلې لپاره اهمیت</h3><h3 dir="rtl"></h3><p>کله چې د پوستکي، زخم، نسج یا کومې بلې برخې موقعیت ثبتوو، دا اصطلاحات کولی شي د هغې د ژورتیا په تشریح کې مرسته وکړي.</p><hr><h1>۱۳. Ipsilateral او Contralateral</h1><h3 dir="rtl"></h3><p>دا اصطلاحات ممکن په لومړي سر کې لږ ستونزمن ښکاره شي، خو راځئ ساده یې کړو.</p><h2>Ipsilateral – په یوه اړخ کې</h2><h3 dir="rtl"></h3><p>که دوه جوړښتونه یا حالتونه د بدن په <strong>یوه خوا</strong> کې وي، ورته Ipsilateral ویل کېږي.</p><h3>مثال:</h3><h3 dir="rtl"></h3><p>د ښي لاس او ښي پښې موقعیت د یو بل په نسبت <strong>Ipsilateral</strong> دی.</p><p>ځکه دواړه په ښي اړخ کې دي.</p><hr><h2>Contralateral – په مخالف اړخ کې</h2><h3 dir="rtl"></h3><p>که دوه جوړښتونه د بدن په <strong>مخالفو خواوو</strong> کې وي، Contralateral ورته ویل کېږي.</p><h3>مثال:</h3><h3 dir="rtl"></h3><p>ښی لاس او کیڼه پښه <strong>Contralateral</strong> دي.</p><p>ځکه یو په ښي او بل په کیڼ اړخ کې دي.</p><hr><h1>۱۴. Bilateral او Unilateral</h1><h2>Bilateral – دواړه خواوې</h2><h3 dir="rtl"></h3><p><strong>Bilateral</strong> معنا لري چې یو حالت یا جوړښت د بدن په دواړو خواوو کې موجود وي.</p><h3>مثال:</h3><h3 dir="rtl"></h3><p>دواړه لاسونه.</p><hr><h2>Unilateral – یوه خوا</h2><h3 dir="rtl"></h3><p><strong>Unilateral</strong> معنا لري چې حالت یوازې په یوه اړخ کې وي.</p><h3>مثال:</h3><h3 dir="rtl"></h3><p>یوازې د ښي لاس پړسوب.</p><hr><h1>۱۵. د اصطلاحاتو د پوهېدو مهم اصل</h1><h3 dir="rtl"></h3><p>دلته یو ډېر مهم ټکی شته:</p><p><strong>Directional Terms مطلقې خبرې نه دي؛ اکثره د دوو جوړښتونو ترمنځ اړیکه ښيي.</strong></p><p>مثلاً:</p><p>پوزه د خولې په نسبت <strong>Superior</strong> ده.</p><p>خو دا معنا نه لري چې پوزه په مطلق ډول یوازې "پورته" ده.</p><p>موږ د پوزې موقعیت د خولې سره مقایسه کوو.</p><p>همدارنګه:</p><p>سترګه د غوږ په نسبت <strong>Medial</strong> ده.</p><p>او غوږ د سترګې په نسبت <strong>Lateral</strong> دی.</p><p>نو یوه اصطلاح باید د <strong>مقایسې</strong> په مفهوم درک شي.</p><hr><h1>۱۶. څو مهمې مقایسې</h1><h3>مثال ۱</h3><h3 dir="rtl"></h3><p>سر د غاړې په نسبت څه دی؟</p><p><strong>Superior</strong></p><p>ځکه سر پورته دی.</p><h3>مثال ۲</h3><h3 dir="rtl"></h3><p>غاړه د سر په نسبت څه ده؟</p><p><strong>Inferior</strong></p><p>ځکه غاړه د سر لاندې ده.</p><h3>مثال ۳</h3><h3 dir="rtl"></h3><p>سینه د ملا په نسبت څه ده؟</p><p><strong>Anterior</strong></p><p>ځکه سینه مخ ته ده.</p><h3>مثال ۴</h3><h3 dir="rtl"></h3><p>ملا د سینې په نسبت څه ده؟</p><p><strong>Posterior</strong></p><p>ځکه ملا شاته ده.</p><h3>مثال ۵</h3><h3 dir="rtl"></h3><p>پوزه د غوږ په نسبت څه ده؟</p><p><strong>Medial</strong></p><p>ځکه پوزه د منځنۍ کرښې ته نږدې ده.</p><h3>مثال ۶</h3><h3 dir="rtl"></h3><p>غوږ د پوزې په نسبت څه دی؟</p><p><strong>Lateral</strong></p><p>ځکه غوږ د منځنۍ کرښې څخه لرې دی.</p><h3>مثال ۷</h3><h3 dir="rtl"></h3><p>څنګل د ګوتو په نسبت څه دی؟</p><p><strong>Proximal</strong></p><p>ځکه څنګل د لاس د اتصال ځای ته نږدې دی.</p><h3>مثال ۸</h3><h3 dir="rtl"></h3><p>ګوتې د څنګل په نسبت څه دي؟</p><p><strong>Distal</strong></p><p>ځکه ګوتې د اتصال ځای څخه لرې دي.</p><hr><h1>۱۷. د قابلې لپاره مهم کلینیکي سناریو</h1><h3 dir="rtl"></h3><p>راځئ اوس یوه واقعي روغتیايي صحنه تصور کړو.</p><p>یوه امیندواره ښځه روغتیايي مرکز ته مراجعه کوي.</p><p>هغې وایي:</p><blockquote><p>«زما د ښي لاس په برخه کې درد لرم.»</p></blockquote><p>قابله باید یوازې په دې جمله بسنه ونه کړي.</p><p>قابله کولای شي د بدن د موقعیت د اصطلاحاتو په مرسته د درد ځای دقیق مشخص کړي.</p><p>د مثال په ډول:</p><p><strong>«د ښي لاس په Distal برخه کې درد دی، د لاس د مړوند او ګوتو خواته.»</strong></p><p>اوس د درد موقعیت ډېر واضح شو.</p><h3>علمي اهمیت</h3><h3 dir="rtl"></h3><p>دقیقې اصطلاحات د دې سبب کېږي چې روغتیايي کارکوونکي د ناروغ د ستونزې په اړه یو شان تصور ولري.</p><h3>د قابلې لپاره مهم درس</h3><h3 dir="rtl"></h3><p><strong>ښه طبي راپور باید دقیق، واضح او د معیاري اصطلاحاتو پر بنسټ وي.</strong></p><hr><h1>۱۸. کلینیکي سناریو ۲: د زخم موقعیت</h1><h3 dir="rtl"></h3><p>فرض کړئ یوه ښځه د عملیاتو وروسته د نس په یوه برخه کې د پوستکي زخم لري.</p><p>که قابله یوازې ولیکي:</p><blockquote><p>«د نس زخم.»</p></blockquote><p>دا معلومات محدود دي.</p><p>خو که د موقعیت په اړه دقیق معلومات ولیکل شي، د روغتیايي ټیم لپاره ډېر ګټور کېږي.</p><p>قابله باید د بدن د موقعیت، اړخ او نورو اړوندو معلوماتو په مرسته ځای واضح کړي.</p><h3>مهمه خبره</h3><h3 dir="rtl"></h3><p>Directional Terms د ناروغ د حالت تشخیص نه کوي؛ دوی یوازې د <strong>موقعیت او اړیکې د دقیق بیان</strong> لپاره کارېږي.</p><hr><h1>۱۹. کلینیکي سناریو ۳: د ښي او کیڼ توپیر</h1><h3 dir="rtl"></h3><p>فرض کړئ یوه ناروغه د خپل ښي پښې درد بیانوي.</p><p>قابله باید په راپور کې واضح ولیکي:</p><p><strong>Right / ښی</strong></p><p>نه دا چې یوازې "پښه".</p><p>ولې؟</p><p>ځکه په طبي محیط کې د ښي او کیڼ اړخ ګډول جدي ستونزه رامنځته کولی شي.</p><p>له همدې امله:</p><p><strong>Right = د ناروغ ښی اړخ</strong></p><p><strong>Left = د ناروغ کیڼ اړخ</strong></p><hr><h1>۲۰. کلینیکي سناریو ۴: Proximal او Distal</h1><h3 dir="rtl"></h3><p>یو زده‌کوونکی وایي:</p><blockquote><p>«د لاس درد د څنګل څخه ښکته دی.»</p></blockquote><p>دا د ورځني ژوند لپاره مناسب بیان دی.</p><p>خو په طبي اصطلاحاتو کې موږ کولی شو موقعیت لا دقیق کړو.</p><p>که درد د لاس د مړوند او ګوتو خواته وي، دا د څنګل په نسبت <strong>Distal</strong> دی.</p><p>که درد د اوږې خواته وي، د څنګل په نسبت <strong>Proximal</strong> دی.</p><h3>مهم مفهوم</h3><h3 dir="rtl"></h3><p>Proximal او Distal یوازې د "پورته او ښکته" معنا نه لري.</p><p>دوی د <strong>اتصال یا د بدن مرکز ته د نږدېوالي او لرېوالي</strong> مفهوم بیانوي.</p><hr><h1>۲۱. کلینیکي سناریو ۵: Medial او Lateral</h1><h3 dir="rtl"></h3><p>یوه ښځه وایي:</p><blockquote><p>«زما د زنګون درد د پښې په دننۍ برخه کې دی.»</p></blockquote><p>دلته قابله باید د "دننه" او "بهر" پر ځای د اړوندو اناتومیک اصطلاحاتو د مفهوم له مخې موقعیت تشریح کړي.</p><p>د بدن د منځنۍ کرښې ته نږدې برخه:</p><p><strong>Medial</strong></p><p>او له منځنۍ کرښې څخه لرې برخه:</p><p><strong>Lateral</strong></p><p>نو د دې اصطلاحاتو زده کړه د ناروغ د شکایتونو په دقیق ثبت کې مرسته کوي.</p><hr><h1>۲۲. یو ډېر مهم مفهوم: د بدن منځنۍ کرښه</h1><h2>Midline</h2><h3 dir="rtl"></h3><p><strong>Midline</strong> د بدن هغه فرضي عمودي کرښه ده چې بدن په ښي او کیڼ اړخ وېشي.</p><p>دا کرښه د <strong>Medial</strong> او <strong>Lateral</strong> د پوهېدو لپاره ډېره مهمه ده.</p><h3>مثال</h3><h3 dir="rtl"></h3><p>پوزه د بدن د منځنۍ کرښې ته نږدې ده.</p><p>نو:</p><p><strong>Nose → Medial</strong></p><p>غوږ د منځنۍ کرښې څخه لرې دی.</p><p>نو:</p><p><strong>Ear → Lateral</strong></p><hr><h1>۲۳. د لوري اصطلاحاتو لنډ جدول</h1><h3 dir="rtl"></h3><table><thead><tr><th>اصطلاح</th><th>English</th><th>ساده معنا</th></tr></thead><tbody><tr><td>فوقاني</td><td>Superior</td><td>پورته</td></tr><tr><td>تحتاني</td><td>Inferior</td><td>ښکته</td></tr><tr><td>مخکینی</td><td>Anterior</td><td>مخ ته</td></tr><tr><td>شاتنی</td><td>Posterior</td><td>شا ته</td></tr><tr><td>منځنۍ</td><td>Medial</td><td>منځنۍ کرښې ته نږدې</td></tr><tr><td>اړخیز</td><td>Lateral</td><td>له منځنۍ کرښې لرې</td></tr><tr><td>نږدې</td><td>Proximal</td><td>د اتصال ځای ته نږدې</td></tr><tr><td>لرې</td><td>Distal</td><td>د اتصال ځای څخه لرې</td></tr><tr><td>سطحي</td><td>Superficial</td><td>د بدن سطحې ته نږدې</td></tr><tr><td>ژور</td><td>Deep</td><td>د سطحې څخه دننه</td></tr><tr><td>هم‌اړخ</td><td>Ipsilateral</td><td>په یوه اړخ کې</td></tr><tr><td>مخالف اړخ</td><td>Contralateral</td><td>په مخالف اړخ کې</td></tr><tr><td>دواړه اړخونه</td><td>Bilateral</td><td>په دواړو خواوو کې</td></tr><tr><td>یو اړخ</td><td>Unilateral</td><td>یوازې په یوه خوا کې</td></tr></tbody></table><hr><h1>۲۴. د زده‌کوونکو عامې تېروتنې</h1><h2>تېروتنه ۱: Right او Left د ځان له مخې ټاکل</h2><h3 dir="rtl"></h3><p>دا ناسمه ده.</p><p>د ناروغ Right او Left باید د <strong>ناروغ له بدن</strong> سره تړاو ولري.</p><hr><h2>تېروتنه ۲: Superior او Inferior یوازې د "پورته او ښکته" په توګه حفظول</h2><h3 dir="rtl"></h3><p>اصلي مفهوم د دوو جوړښتونو ترمنځ مقایسه ده.</p><hr><h2>تېروتنه ۳: Medial او Lateral ګډول</h2><h3 dir="rtl"></h3><p>یاد وساتئ:</p><p><strong>Medial → Midline ته نږدې</strong></p><p><strong>Lateral → Midline څخه لرې</strong></p><hr><h2>تېروتنه ۴: Proximal د Superior سره یو شان ګڼل</h2><h3 dir="rtl"></h3><p>دواړه یو شی نه دي.</p><p><strong>Superior/Inferior</strong> د پورته او ښکته اړیکه بیانوي.</p><p><strong>Proximal/Distal</strong> د اتصال یا بدن د مرکز په نسبت نږدېوالی او لرېوالی بیانوي.</p><hr><h2>تېروتنه ۵: Anterior او Posterior یوازې د انسان د ولاړې حالت په توګه تصورول</h2><h3 dir="rtl"></h3><p>دا اصطلاحات د بدن د مخکیني او شاتني لوري ترمنځ اړیکه بیانوي.</p><hr><h1>۲۵. د بدن د لوري اصطلاحات څنګه په ذهن کې وساتو؟</h1><h3 dir="rtl"></h3><p>راځئ یوه ساده ذهني نقشه جوړه کړو.</p><h3>عمودي جهت:</h3><h3 dir="rtl"></h3><p><strong>Superior ↑</strong></p><p><strong>Inferior ↓</strong></p><h3>مخ او شا:</h3><h3 dir="rtl"></h3><p><strong>Anterior → مخ</strong></p><p><strong>Posterior → شا</strong></p><h3>منځ او اړخ:</h3><h3 dir="rtl"></h3><p><strong>Medial → منځ</strong></p><p><strong>Lateral → اړخ</strong></p><h3>د اندام اوږدوالی:</h3><h3 dir="rtl"></h3><p><strong>Proximal → نږدې</strong></p><p><strong>Distal → لرې</strong></p><h3>ژورتیا:</h3><h3 dir="rtl"></h3><p><strong>Superficial → سطحې ته نږدې</strong></p><p><strong>Deep → ژور</strong></p><hr><h1>۲۶. د قابله‌ګۍ په عملي کار کې استعمال</h1><h3 dir="rtl"></h3><p>یوه قابله هره ورځ د بدن د موقعیتونو په اړه معلومات اخلي او ثبتوي.</p><p>د مثال په ډول:</p><ul><li><p>د درد موقعیت</p></li><li><p>د زخم موقعیت</p></li><li><p>پړسوب</p></li><li><p>د پوستکي بدلون</p></li><li><p>د اندامونو موقعیت</p></li><li><p>د معاینې موندنې</p></li><li><p>د ناروغ د شکایت دقیق ځای</p></li></ul><p>که قابله د بدن د لوري اصطلاحات په سمه توګه استعمال کړي، د هغې راپور:</p><p><strong>واضح + معیاري + دقیق + مسلکي</strong></p><p>کېږي.</p><hr><h1>۲۷. د اناتومیک مستویو او لوري اصطلاحاتو اړیکه</h1><h3 dir="rtl"></h3><p>دلته یو مهم مفهومي ارتباط شته.</p><p>موږ مستوي د بدن د جوړښت د تصور لپاره کاروو، او directional terms د جوړښتونو ترمنځ موقعیت تشریح کوي.</p><p>مثلاً:</p><p><strong>Sagittal Plane</strong></p><p>بدن ښي او کیڼ برخو ته وېشي.</p><p>وروسته موږ کولای شو د هرې برخې موقعیت د <strong>Medial</strong> او <strong>Lateral</strong> په اصطلاحاتو بیان کړو.</p><p>همدارنګه:</p><p><strong>Frontal Plane</strong></p><p>مخکینۍ او شاتنۍ برخې جلا کوي.</p><p>نو موږ د <strong>Anterior</strong> او <strong>Posterior</strong> اصطلاحات کاروو.</p><p><strong>Transverse Plane</strong></p><p>پورته او ښکته برخې جلا کوي.</p><p>نو موږ د <strong>Superior</strong> او <strong>Inferior</strong> اصطلاحات کاروو.</p><p>دا اړیکه د موضوع په ژوره پوهېدو کې ډېره مرسته کوي.</p><hr><h1>۲۸. د یادولو لپاره یوه ساده نقشه</h1><h3 dir="rtl"></h3><table><thead><tr><th>مستوي</th><th>د بدن وېش</th><th>اړوند جهتونه</th></tr></thead><tbody><tr><td>Sagittal</td><td>ښی / کیڼ</td><td>Medial / Lateral</td></tr><tr><td>Frontal</td><td>مخ / شا</td><td>Anterior / Posterior</td></tr><tr><td>Transverse</td><td>پورته / ښکته</td><td>Superior / Inferior</td></tr></tbody></table><p>البته Directional Terms یوازې په همدې مستویو پورې محدود نه دي؛ دا جدول یوازې د زده کړې لپاره یو ساده ارتباط ښيي.</p><hr><h1>۲۹. انفرادي آنلاین فعالیت</h1><h2>Individual LMS Activity</h2><h3 dir="rtl"></h3><p>ځکه چې دا کورس آنلاین دی، زده‌کوونکې کولای شي فعالیت په انفرادي ډول ترسره کړي.</p><h3>فعالیت: «سم لوری وټاکئ»</h3><h3 dir="rtl"></h3><p>سیستم به د بدن دوه برخې یا یوه موقعیت وړاندې کړي او زده‌کوونکې باید مناسبه اصطلاح انتخاب کړي.</p><h3>مثالونه:</h3><h3 dir="rtl"></h3><p><strong>۱. سر د غاړې په نسبت؟</strong></p><p>A. Inferior<br>B. Superior<br>C. Lateral<br>D. Distal</p><p>صحیح ځواب:</p><p><strong>B. Superior</strong></p><hr><p><strong>۲. غوږ د پوزې په نسبت؟</strong></p><p>A. Medial<br>B. Superior<br>C. Lateral<br>D. Proximal</p><p>صحیح ځواب:</p><p><strong>C. Lateral</strong></p><hr><p><strong>۳. ګوتې د څنګل په نسبت؟</strong></p><p>A. Proximal<br>B. Distal<br>C. Medial<br>D. Posterior</p><p>صحیح ځواب:</p><p><strong>B. Distal</strong></p><hr><h3>د Drag-and-Drop فعالیت</h3><h3 dir="rtl"></h3><p>زده‌کوونکې ته دې لاندې اصطلاحات ورکړل شي:</p><ul><li><p>Superior</p></li><li><p>Inferior</p></li><li><p>Anterior</p></li><li><p>Posterior</p></li><li><p>Medial</p></li><li><p>Lateral</p></li><li><p>Proximal</p></li><li><p>Distal</p></li></ul><p>او د هرې اصطلاح لپاره دې د بدن مناسب مثال یا تشریح ورکړل شي.</p><p>زده‌کوونکې باید هره اصطلاح له سم مثال سره وصل کړي.</p><h3>د فعالیت هدف</h3><h3 dir="rtl"></h3><p>د دې فعالیت هدف یوازې حفظ نه دی.</p><p>هدف دا دی چې زده‌کوونکې وکولای شي:</p><p><strong>اصطلاح → معنا → د بدن موقعیت → واقعي مثال</strong></p><p>سره وصل کړي.</p><hr><h1>۳۰. مهم طبي لغاتونه</h1><h3 dir="rtl"></h3><table><thead><tr><th>پښتو اصطلاح</th><th>English Term</th><th>ساده تشریح</th></tr></thead><tbody><tr><td>اناتومیک دریځ</td><td>Anatomical Position</td><td>د بدن معیاري دریځ</td></tr><tr><td>مستوي</td><td>Plane</td><td>فرضي سطح چې بدن د مطالعې لپاره وېشي</td></tr><tr><td>ساجیټل مستوي</td><td>Sagittal Plane</td><td>ښی او کیڼ وېشي</td></tr><tr><td>منځنی ساجیټل</td><td>Midsagittal Plane</td><td>تقریباً مساوي ښی او کیڼ برخې</td></tr><tr><td>فرونټل مستوي</td><td>Frontal Plane</td><td>مخ او شا وېشي</td></tr><tr><td>کورونل مستوي</td><td>Coronal Plane</td><td>د Frontal بل نوم</td></tr><tr><td>ټرانسورس مستوي</td><td>Transverse Plane</td><td>پورته او ښکته وېشي</td></tr><tr><td>منځنۍ کرښه</td><td>Midline</td><td>د بدن فرضي منځنۍ کرښه</td></tr><tr><td>فوقاني</td><td>Superior</td><td>پورته</td></tr><tr><td>تحتاني</td><td>Inferior</td><td>ښکته</td></tr><tr><td>مخکینی</td><td>Anterior</td><td>مخ ته</td></tr><tr><td>شاتنی</td><td>Posterior</td><td>شا ته</td></tr><tr><td>منځنۍ</td><td>Medial</td><td>منځنۍ کرښې ته نږدې</td></tr><tr><td>اړخیز</td><td>Lateral</td><td>له منځنۍ کرښې لرې</td></tr><tr><td>نږدې</td><td>Proximal</td><td>د اتصال ځای ته نږدې</td></tr><tr><td>لرې</td><td>Distal</td><td>د اتصال ځای څخه لرې</td></tr><tr><td>سطحي</td><td>Superficial</td><td>سطحې ته نږدې</td></tr><tr><td>ژور</td><td>Deep</td><td>دننه ژور</td></tr><tr><td>هم‌اړخ</td><td>Ipsilateral</td><td>په یوه اړخ کې</td></tr><tr><td>مخالف اړخ</td><td>Contralateral</td><td>په مخالف اړخ کې</td></tr><tr><td>دواړه اړخونه</td><td>Bilateral</td><td>دواړه خواوې</td></tr><tr><td>یو اړخ</td><td>Unilateral</td><td>یوه خوا</td></tr></tbody></table><hr><h1>۳۱. د درس لنډیز</h1><h3 dir="rtl"></h3><p>نن مو درې لوی موضوعات زده کړل:</p><h2>لومړی: Anatomical Position</h2><h3 dir="rtl"></h3><p>موږ زده کړل چې د بدن د موقعیت د تشریح لپاره یو معیاري دریځ کارېږي.</p><h2>دوهم: Anatomical Planes</h2><h3 dir="rtl"></h3><p>درې مهم مستوي:</p><p><strong>Sagittal → ښی او کیڼ</strong></p><p><strong>Frontal → مخ او شا</strong></p><p><strong>Transverse → پورته او ښکته</strong></p><h2>درېیم: Directional Terms</h2><h3 dir="rtl"></h3><p>موږ زده کړل:</p><p><strong>Superior ↔ Inferior</strong></p><p><strong>Anterior ↔ Posterior</strong></p><p><strong>Medial ↔ Lateral</strong></p><p><strong>Proximal ↔ Distal</strong></p><p><strong>Superficial ↔ Deep</strong></p><p>او:</p><p><strong>Ipsilateral / Contralateral</strong></p><p><strong>Bilateral / Unilateral</strong></p><p>د دې درس اصلي هدف دا دی چې زده‌کوونکې د بدن د برخو موقعیت په <strong>دقیقو او معیاري اصطلاحاتو</strong> بیان کړای شي.</p><hr><h1>۳۲. د ارزونې پوښتنې</h1><h2>لومړۍ برخه: Multiple Choice – Single Answer</h2><h3>پوښتنه ۱</h3><h3 dir="rtl"></h3><p>په Anatomical Position کې د لاسونو ورغوي کوم لوري ته وي؟</p><p>A. شا ته<br>B. مخ ته<br>C. ښکته<br>D. یو بل ته</p><p><strong>صحیح ځواب: B. مخ ته</strong></p><p><strong>تشریح:</strong> په Anatomical Position کې انسان نېغ ولاړ وي او د لاسونو ورغوي مخامخ لوري ته وي. دا د بدن د جهتونو د معیاري تشریح لپاره بنسټیز دریځ دی.</p><hr><h3>پوښتنه ۲</h3><h3 dir="rtl"></h3><p>Sagittal Plane بدن په کومو برخو وېشي؟</p><p>A. مخ او شا<br>B. پورته او ښکته<br>C. ښی او کیڼ<br>D. سطحي او ژور</p><p><strong>صحیح ځواب: C. ښی او کیڼ</strong></p><p><strong>تشریح:</strong> Sagittal Plane د بدن اوږدو کې تېرېږي او ښی او کیڼ اړخونه جلا کوي.</p><hr><h3>پوښتنه ۳</h3><h3 dir="rtl"></h3><p>غوږ د پوزې په نسبت کوم موقعیت لري؟</p><p>A. Medial<br>B. Lateral<br>C. Superior<br>D. Proximal</p><p><strong>صحیح ځواب: B. Lateral</strong></p><p><strong>تشریح:</strong> غوږ د بدن له منځنۍ کرښې څخه د پوزې په پرتله لرې دی، نو Lateral دی.</p><hr><h3>پوښتنه ۴</h3><h3 dir="rtl"></h3><p>ګوتې د څنګل په نسبت کومه اصطلاح لري؟</p><p>A. Proximal<br>B. Distal<br>C. Superior<br>D. Medial</p><p><strong>صحیح ځواب: B. Distal</strong></p><p><strong>تشریح:</strong> ګوتې د لاس د اتصال ځای او د څنګل په نسبت لرې دي، نو Distal بلل کېږي.</p><hr><h3>پوښتنه ۵</h3><h3 dir="rtl"></h3><p>پوستکی د عضلاتو په نسبت کوم دی؟</p><p>A. Deep<br>B. Posterior<br>C. Superficial<br>D. Inferior</p><p><strong>صحیح ځواب: C. Superficial</strong></p><p><strong>تشریح:</strong> پوستکی د بدن سطحې ته نږدې دی، په داسې حال کې چې عضلات د پوستکي لاندې ژور موقعیت لري.</p><hr><h1>دوهمه برخه: True / False</h1><h3>پوښتنه ۶</h3><h3 dir="rtl"></h3><p>Frontal Plane بدن په مخکینۍ او شاتنۍ برخو وېشي.</p><p><strong>صحیح ځواب: True</strong></p><p><strong>تشریح:</strong> Frontal یا Coronal Plane د بدن Anterior او Posterior برخې جلا کوي.</p><hr><h3>پوښتنه ۷</h3><h3 dir="rtl"></h3><p>Medial معنا لري چې یوه برخه د بدن له منځنۍ کرښې څخه لرې ده.</p><p><strong>صحیح ځواب: False</strong></p><p><strong>تشریح:</strong> Medial معنا لري چې یوه برخه د بدن منځنۍ کرښې ته نږدې ده. له منځنۍ کرښې څخه لرې ته Lateral ویل کېږي.</p><hr><h3>پوښتنه ۸</h3><h3 dir="rtl"></h3><p>Right او Left باید د ناروغ د بدن له مخې وټاکل شي.</p><p><strong>صحیح ځواب: True</strong></p><p><strong>تشریح:</strong> په طبي اصطلاحاتو کې د ناروغ ښی او کیڼ اړخ د ناروغ له خپل بدن سره تړاو لري.</p><hr><h1>درېیمه برخه: Short Answer</h1><h3>پوښتنه ۹</h3><h3 dir="rtl"></h3><p>د Proximal او Distal ترمنځ توپیر تشریح کړئ.</p><p><strong>نمونوي ځواب:</strong></p><p>Proximal هغه موقعیت دی چې د اندام د اتصال ځای یا د بدن د مرکز ته نسبتاً نږدې وي، په داسې حال کې چې Distal له هغه ځای څخه لرې وي. د مثال په توګه، څنګل د ګوتو په نسبت Proximal دی، او ګوتې د څنګل په نسبت Distal دي.</p><hr><h3>پوښتنه ۱۰</h3><h3 dir="rtl"></h3><p>د درې مهمو Anatomical Planes نومونه ولیکئ او تشریح یې کړئ.</p><p><strong>نمونوي ځواب:</strong></p><ol><li><p><strong>Sagittal Plane:</strong> بدن په ښي او کیڼ برخو وېشي.</p></li><li><p><strong>Frontal/Coronal Plane:</strong> بدن په مخکینۍ او شاتنۍ برخو وېشي.</p></li><li><p><strong>Transverse Plane:</strong> بدن په پورته او ښکته برخو وېشي.</p></li></ol><hr><h1>۳۳. وروستی جامع کلینیکي سناریو</h1><h3 dir="rtl"></h3><p>یوه امیندواره ښځه د روغتیايي مرکز د معاینې لپاره راغلې ده.</p><p>د هغې د ښي لاس په Distal برخه کې درد شته. قابله غواړي د ناروغې د شکایت موقعیت په دقیق ډول ثبت کړي.</p><p>قابله باید د بدن د لوري اصطلاحات په سمه توګه استعمال کړي.</p><h3>پوښتنه ۱</h3><h3 dir="rtl"></h3><p>که درد د څنګل څخه د ګوتو خواته وي، دا د څنګل په نسبت Proximal دی که Distal؟</p><p><strong>ځواب: Distal</strong></p><h3>د ښوونکي تشریح</h3><h3 dir="rtl"></h3><p>ځکه درد د څنګل څخه لرې، د لاس د پای برخې ته نږدې دی.</p><hr><h3>پوښتنه ۲</h3><h3 dir="rtl"></h3><p>که درد د اوږې خواته د څنګل څخه نږدې وي، کومه اصطلاح مناسبه ده؟</p><p><strong>ځواب: Proximal</strong></p><h3>تشریح</h3><h3 dir="rtl"></h3><p>ځکه اوږه د لاس د بدن سره د اتصال ځای ته نږدې ده.</p><hr><h3>پوښتنه ۳</h3><h3 dir="rtl"></h3><p>که ناروغې ووایي چې درد د ښي لاس په اړخ کې دی، Right او Left به د چا له مخې ټاکل کېږي؟</p><p><strong>ځواب: د ناروغې د بدن له مخې.</strong></p><h3>تشریح</h3><h3 dir="rtl"></h3><p>روغتیايي کارکوونکی باید د خپل بدن له ښي او کیڼ اړخ سره دا موضوع ګډه نه کړي.</p><hr><h3>پوښتنه ۴</h3><h3 dir="rtl"></h3><p>که یوه برخه د بدن د منځنۍ کرښې ته نږدې وي، Medial ده که Lateral؟</p><p><strong>ځواب: Medial</strong></p><h3>تشریح</h3><h3 dir="rtl"></h3><p>Medial د Midline سره نږدې موقعیت ښيي.</p><hr><h3>پوښتنه ۵</h3><h3 dir="rtl"></h3><p>که قابله وغواړي د بدن داخلي جوړښتونه په درې‌بعدي ډول د یوې فرضي سطحې له لارې تشریح کړي، کوم مفهوم کاروي؟</p><p><strong>ځواب: Anatomical Plane</strong></p><h3>تشریح</h3><h3 dir="rtl"></h3><p>Anatomical Planes فرضي سطحي دي چې د بدن د جوړښتونو د مطالعې او تشریح لپاره کارېږي.</p><hr><h1>۳۴. د ښوونکي وروستی پیغام</h1><h3 dir="rtl"></h3><p>ګرانو زده‌کوونکو!</p><p>د دې درس هدف دا نه و چې یوازې څو انګلیسي کلمې حفظ کړئ.</p><p>هدف دا و چې تاسو د بدن د موقعیت د تشریح لپاره یوه <strong>مسلکي ژبه</strong> زده کړئ.</p><p>کله چې تاسو په راتلونکو درسونو کې د ناروغ معاینه کوئ، د درد ځای ثبتوئ، د ناروغ شکایت اورئ، یا د روغتیايي ټیم له نورو غړو سره خبرې کوئ، هڅه وکړئ چې خپل بیان واضح او دقیق کړئ.</p><p>یوازې دا مه وایئ:</p><p><strong>«دلته درد لري.»</strong></p><p>بلکې زده کړئ چې ووایاست:</p><p><strong>«د بدن په کوم اړخ، کوم جهت، کومه برخه او د کوم جوړښت په نسبت؟»</strong></p><p>همدا دقیق فکر کول تاسو له یوه عادي زده‌کوونکي څخه یوه <strong>مسلکي قابلې</strong> ته نږدې کوي.</p><p><strong>اصطلاحات مه حفظوئ؛ مفهوم یې درک کړئ. کله چې مفهوم درسره وي، اصطلاحات به پخپله اسانه شي.</strong></p>', 'rtl', 'url', 'https://www.youtube.com/watch?v=gfC4t6iyFVc', NULL, 34, 'intro', 6, TRUE, 3, TRUE, '2026-09-13 04:39:29'),
(331, 33, 'د بدن سیمې او کهفونه', '<p dir="rtl" style="text-align:right">بدن په سیمو ویشل کیږي او دننه یې کهفونه (cavities) شته چې غړي پکې ساتل شوي دي.</p>', '<h1>د بدن سیمې او کهفونه</h1><h2>Body Regions and Body Cavities</h2><h3>د درس پیل</h3><h3 dir="rtl"></h3><p>په تېر درس کې مو زده کړل چې د بدن د برخو موقعیت د <strong>اناتومیک دریځ (Anatomical Position)</strong>، <strong>مستویو (Planes)</strong> او <strong>د لوري اصطلاحاتو (Directional Terms)</strong> په وسیله په دقیق ډول تشریح کېدای شي.</p><p>اوس راځئ یو بل مهم ګام واخلو.</p><p>کله چې یوه قابله د ناروغې بدن ارزوي، یوازې دا نه وایي چې:</p><blockquote><p>«دا د بدن یوه برخه ده.»</p></blockquote><p>بلکې باید وکولای شي د بدن <strong>سیمه (Region)</strong> او د بدن دننه د مهمو غړو <strong>ځای (Location)</strong> په واضح ډول مشخص کړي.</p><p>د دې لپاره موږ د بدن لویې سیمې او هغه داخلي تش ځایونه زده کوو چې مهم غړي پکې موقعیت لري.</p><p>د نن درس دوه اساسي برخې لري:</p><ol><li><p><strong>د بدن سیمې (Body Regions)</strong></p></li><li><p><strong>د بدن کهفونه (Body Cavities)</strong></p></li></ol><hr><h1>لومړۍ برخه: د بدن سیمې</h1><h2>Body Regions</h2><h3 dir="rtl"></h3><p>د انسان بدن په لویو او کوچنیو سیمو وېشل کېږي.</p><p>د بدن د سیمو نومونه موږ سره مرسته کوي چې د بدن یوه ځانګړې برخه په دقیق ډول وپیژنو.</p><p>په عمومي ډول بدن په دوو لویو برخو وېشل کېږي:</p><h3>۱. محوري برخه</h3><h3 dir="rtl"></h3><p><strong>Axial Region</strong></p><h3>۲. اندامي برخه</h3><h3 dir="rtl"></h3><p><strong>Appendicular Region</strong></p><p>راځئ دواړه په ساده ډول زده کړو.</p><hr><h1>۱. محوري برخه</h1><h2>Axial Region</h2><h3 dir="rtl"></h3><p><strong>Axial Region</strong> د بدن مرکزي برخه ده.</p><p>په دې کې شامل دي:</p><ul><li><p>سر</p></li><li><p>غاړه</p></li><li><p>تنه</p></li></ul><p>یعنې هغه برخې چې د بدن اصلي مرکزي محور جوړوي.</p><h3>د ساده تصور لپاره</h3><h3 dir="rtl"></h3><p>که یو انسان ته له مخامخ څخه وګورو، د بدن منځنۍ برخه د بدن اصلي محور جوړوي.</p><p><strong>سر → غاړه → تنه</strong></p><p>دا ټول د Axial Region مهمې برخې دي.</p><hr><h1>۲. اندامي برخه</h1><h2>Appendicular Region</h2><h3 dir="rtl"></h3><p><strong>Appendicular Region</strong> د بدن هغه برخې دي چې د مرکزي بدن سره تړلي اندامونه جوړوي.</p><p>په دې کې شامل دي:</p><ul><li><p>پورتني اندامونه</p></li><li><p>ښی لاس</p></li><li><p>کیڼ لاس</p></li><li><p>ښی پښه</p></li><li><p>کیڼه پښه</p></li><li><p>د اوږې کمربند</p></li><li><p>د حوض کمربند</p></li></ul><p>په ساده ډول:</p><p><strong>Axial = مرکزي بدن</strong></p><p><strong>Appendicular = تړلي اندامونه</strong></p><hr><h1>۳. د بدن مهمې سیمې</h1><h3 dir="rtl"></h3><p>اوس راځئ د بدن د مهمو سیمو نومونه له سر څخه تر پښو پورې زده کړو.</p><hr><h2>A. د سر سیمه</h2><h3>Head Region</h3><h3 dir="rtl"></h3><p>د سر سیمه د بدن تر ټولو پورته لویه سیمه ده.</p><p>په دې کې مهمې کوچنۍ سیمې شاملې دي، لکه:</p><ul><li><p><strong>Cephalic Region</strong> – د سر سیمه</p></li><li><p><strong>Facial Region</strong> – د مخ سیمه</p></li></ul><h3>Facial Region</h3><h3 dir="rtl"></h3><p>د مخ په سیمه کې شامل دي:</p><ul><li><p>سترګې</p></li><li><p>پوزه</p></li><li><p>خوله</p></li><li><p>غاړه نه، بلکې مخ</p></li></ul><hr><h1>۴. د غاړې سیمه</h1><h2>Cervical Region</h2><h3 dir="rtl"></h3><p><strong>Cervical Region</strong> د غاړې سیمه ده.</p><p>غاړه د سر او تنه ترمنځ موقعیت لري.</p><h3>مهمه اړیکه</h3><h3 dir="rtl"></h3><p><strong>Head → Cervical → Trunk</strong></p><p>یعنې:</p><p><strong>سر → غاړه → تنه</strong></p><p>د قابلې لپاره د Cervical اصطلاح پېژندل مهم دي، ځکه په طبي راپورونو او معایناتو کې ډېر کارېږي.</p><hr><h1>۵. د تنه سیمه</h1><h2>Trunk Region</h2><h3 dir="rtl"></h3><p><strong>Trunk</strong> د بدن مرکزي لویه برخه ده چې د سر او اندامونو ترمنځ موقعیت لري.</p><p>تنه په څو مهمو سیمو وېشل کېږي:</p><ul><li><p><strong>Thoracic Region</strong> – د سینې سیمه</p></li><li><p><strong>Abdominal Region</strong> – د نس/شکم سیمه</p></li><li><p><strong>Pelvic Region</strong> – د حوض سیمه</p></li><li><p><strong>Dorsal Region</strong> – شاتنۍ برخه</p></li></ul><p>راځئ هره یوه جلا وګورو.</p><hr><h1>۶. د سینې سیمه</h1><h2>Thoracic Region</h2><h3 dir="rtl"></h3><p><strong>Thoracic Region</strong> د سینې سیمه ده.</p><p>په دې سیمه کې د بدن مهم جوړښتونه او غړي موجود دي، لکه:</p><ul><li><p>زړه</p></li><li><p>سږي</p></li><li><p>د تنفسي سیستم مهمې برخې</p></li><li><p>د وینې د دوران ځینې مهم جوړښتونه</p></li></ul><p>د سینې دننه مهمه برخه:</p><p><strong>Thoracic Cavity</strong></p><p>ده، چې وروسته به یې په تفصیل سره زده کړو.</p><hr><h1>۷. د نس یا شکم سیمه</h1><h2>Abdominal Region</h2><h3 dir="rtl"></h3><p><strong>Abdominal Region</strong> د تنه هغه سیمه ده چې د سینې لاندې او د حوض له سیمې پورته موقعیت لري.</p><p>په دې سیمه کې ګڼ مهم غړي موقعیت لري، لکه:</p><ul><li><p>معده</p></li><li><p>کوچنۍ کولمه</p></li><li><p>لویه کولمه</p></li><li><p>ځیګر</p></li><li><p>تلی</p></li><li><p>پانقراس</p></li><li><p>پښتورګي د نس په شاتنۍ برخه کې</p></li></ul><h3>د قابلې لپاره اهمیت</h3><h3 dir="rtl"></h3><p>کله چې ناروغه وایي:</p><blockquote><p>«د نس په برخه کې درد لرم.»</p></blockquote><p>دا معلومات لا ډېر عمومي دي.</p><p>قابله باید د درد ځای په لا دقیق ډول مشخص کړي.</p><p>مثلاً:</p><ul><li><p>د نس ښی اړخ؟</p></li><li><p>کیڼ اړخ؟</p></li><li><p>پورته؟</p></li><li><p>ښکته؟</p></li><li><p>منځنۍ برخه؟</p></li></ul><p>له همدې امله د بدن د سیمو پوهه د ناروغ د شکایت د دقیق ثبت لپاره مهمه ده.</p><hr><h1>۸. د حوض سیمه</h1><h2>Pelvic Region</h2><h3 dir="rtl"></h3><p><strong>Pelvic Region</strong> د تنه ټیټه سیمه ده چې د حوض له جوړښت سره تړاو لري.</p><p>دا سیمه په قابله‌ګۍ کې ځانګړی اهمیت لري.</p><p>ولې؟</p><p>ځکه د ښځینه تناسلي سیستم مهم جوړښتونه له دې سیمې سره تړاو لري.</p><p>د ښځینه تولیدي سیستم مهم غړي، لکه:</p><ul><li><p>رحم (Uterus)</p></li><li><p>د رحم غاړه (Cervix)</p></li><li><p>مهبل (Vagina)</p></li><li><p>تخمدانونه (Ovaries)</p></li></ul><p>د حوض له سیمې سره مهم اناتومیک ارتباط لري.</p><hr><h1>۹. د شا سیمه</h1><h2>Dorsal Region</h2><h3 dir="rtl"></h3><p><strong>Dorsal Region</strong> د بدن شاتنۍ برخه ده.</p><p>په عمومي ډول د شا سیمې په تشریح کې کارېږي.</p><p>په دې سیمه کې د ملا د ستون فقرات جوړښت مهم رول لري.</p><h3>مهمه اصطلاح</h3><h3 dir="rtl"></h3><p><strong>Vertebral Region</strong></p><p>د ملا د تېر یا ستون فقرات اړوند سیمه ده.</p><hr><h1>۱۰. د پورتني اندام سیمې</h1><h2>Upper Limb Regions</h2><h3 dir="rtl"></h3><p>پورتنی اندام یوازې "لاس" نه دی.</p><p>دا څو مهمې سیمې لري.</p><h3>Shoulder Region</h3><h3 dir="rtl"></h3><p><strong>د اوږې سیمه</strong></p><h3>Arm / Brachial Region</h3><h3 dir="rtl"></h3><p><strong>د بازو سیمه</strong></p><h3>Antecubital Region</h3><h3 dir="rtl"></h3><p><strong>د څنګل مخکینۍ سیمه</strong></p><h3>Forearm / Antebrachial Region</h3><h3 dir="rtl"></h3><p><strong>د مټ یا ساعد سیمه</strong></p><h3>Carpal Region</h3><h3 dir="rtl"></h3><p><strong>د مړوند سیمه</strong></p><h3>Hand Region</h3><h3 dir="rtl"></h3><p><strong>د لاس سیمه</strong></p><h3>Digital Region</h3><h3 dir="rtl"></h3><p><strong>د ګوتو سیمه</strong></p><hr><h1>۱۱. د پورتني اندام د سیمو ترتیب</h1><h3 dir="rtl"></h3><p>راځئ له بدن څخه تر ګوتو پورې یې وګورو:</p><p><strong>Shoulder → Arm → Elbow → Forearm → Wrist → Hand → Fingers</strong></p><p>یعنې:</p><p><strong>اوږه → بازو → څنګل → ساعد → مړوند → لاس → ګوتې</strong></p><p>دا ترتیب باید په مفهوم زده شي.</p><hr><h1>۱۲. د ښکته اندام سیمې</h1><h2>Lower Limb Regions</h2><h3 dir="rtl"></h3><p>ښکته اندام هم په څو سیمو وېشل کېږي.</p><h3>Hip Region</h3><h3 dir="rtl"></h3><p><strong>د ورون/حوض اړخ سیمه</strong></p><h3>Femoral Region</h3><h3 dir="rtl"></h3><p><strong>د ورانه سیمه</strong></p><h3>Patellar Region</h3><h3 dir="rtl"></h3><p><strong>د زنګون مخکینۍ سیمه</strong></p><h3>Popliteal Region</h3><h3 dir="rtl"></h3><p><strong>د زنګون شاتنۍ سیمه</strong></p><h3>Crural Region</h3><h3 dir="rtl"></h3><p><strong>د پنډۍ مخکینۍ برخه</strong></p><h3>Tarsal Region</h3><h3 dir="rtl"></h3><p><strong>د پښې مړوند/ټخنې سیمه</strong></p><h3>Foot Region</h3><h3 dir="rtl"></h3><p><strong>د پښې سیمه</strong></p><h3>Digital Region</h3><h3 dir="rtl"></h3><p><strong>د پښو د ګوتو سیمه</strong></p><hr><h1>۱۳. د ښکته اندام د سیمو ترتیب</h1><h3 dir="rtl"></h3><p>له بدن څخه د پښې تر ګوتو پورې:</p><p><strong>Hip → Thigh → Knee → Leg → Ankle → Foot → Toes</strong></p><p>یعنې:</p><p><strong>حوض اړخ → ورون → زنګون → پنډۍ → ټخنه → پښه → د پښې ګوتې</strong></p><hr><h1>۱۴. د بدن سیمه او د بدن کهف توپیر لري</h1><h3 dir="rtl"></h3><p>دا ډېر مهم مفهوم دی.</p><p><strong>Body Region</strong> د بدن یوه <strong>بهرنۍ یا موقعیتي سیمه</strong> ده.</p><p>خو:</p><p><strong>Body Cavity</strong> د بدن دننه یوه <strong>تش ځای/فضا</strong> ده چې مهم داخلي غړي پکې موقعیت لري.</p><h3>ساده مثال</h3><h3 dir="rtl"></h3><p><strong>Abdominal Region</strong></p><p>یوه سیمه ده.</p><p>خو:</p><p><strong>Abdominal Cavity</strong></p><p>یوه داخلي کهف دی.</p><p>نو:</p><p><strong>Region ≠ Cavity</strong></p><p>دواړه یو شی نه دي.</p><hr><h1>دوهمه برخه: د بدن کهفونه</h1><h2>Body Cavities</h2><h3 dir="rtl"></h3><p>اوس راځئ د بدن دننه تشو فضاوو ته لاړ شو.</p><p>د انسان بدن دننه ځینې ځانګړې فضاوې شته چې مهم غړي پکې موقعیت لري.</p><p>دې فضاوو ته:</p><p><strong>Body Cavities</strong></p><p>ویل کېږي.</p><p>د بدن مهم کهفونه په عمومي ډول په دوو لویو برخو وېشل کېږي:</p><ol><li><p><strong>Dorsal Body Cavity</strong></p></li><li><p><strong>Ventral Body Cavity</strong></p></li></ol><hr><h1>۱۵. Dorsal Body Cavity</h1><h3 dir="rtl"></h3><p><strong>Dorsal Body Cavity</strong> د بدن شاتنۍ کهفي برخه ده.</p><p>د دې دوه مهمې برخې دي:</p><h3>Cranial Cavity</h3><h3 dir="rtl"></h3><p><strong>د کوپړۍ کهف</strong></p><h3>Vertebral Cavity</h3><h3 dir="rtl"></h3><p><strong>د ملا د تېر/ستون فقرات کهف</strong></p><hr><h1>۱۶. Cranial Cavity</h1><h3 dir="rtl"></h3><p><strong>Cranial Cavity</strong> هغه داخلي فضا ده چې د کوپړۍ په دننه کې موقعیت لري.</p><p>د دې اصلي مهم غړی:</p><p><strong>Brain – مغز</strong></p><p>دی.</p><h3>ولې دا مهم دی؟</h3><h3 dir="rtl"></h3><p>کوپړۍ د مغز لپاره محافظتي جوړښت جوړوي.</p><p>نو:</p><p><strong>Cranial Cavity → Brain</strong></p><p>دا اړیکه باید زده‌کوونکې په واضح ډول درک کړي.</p><hr><h1>۱۷. Vertebral Cavity</h1><h3 dir="rtl"></h3><p><strong>Vertebral Cavity</strong> د ستون فقرات په دننه کې موقعیت لري.</p><p>په دې کې مهم جوړښت:</p><p><strong>Spinal Cord – شوکي نخاع</strong></p><p>موقعیت لري.</p><p>نو:</p><p><strong>Cranial Cavity → Brain</strong></p><p><strong>Vertebral Cavity → Spinal Cord</strong></p><p>دا دواړه د عصبي سیستم له مهمو جوړښتونو سره تړاو لري.</p><hr><h1>۱۸. Ventral Body Cavity</h1><h3 dir="rtl"></h3><p>اوس د بدن مخکینۍ لویې کهفي برخې ته راځو.</p><p><strong>Ventral Body Cavity</strong> د بدن په مخکینۍ برخه کې لوی داخلي کهفي سیستم دی.</p><p>دا په دوو مهمو برخو وېشل کېږي:</p><h3>Thoracic Cavity</h3><h3 dir="rtl"></h3><p><strong>د سینې کهف</strong></p><h3>Abdominopelvic Cavity</h3><h3 dir="rtl"></h3><p><strong>د نس او حوض کهف</strong></p><hr><h1>۱۹. Thoracic Cavity</h1><h3 dir="rtl"></h3><p><strong>Thoracic Cavity</strong> د سینې دننه لوی کهف دی.</p><p>په دې کې مهم غړي موقعیت لري:</p><ul><li><p>زړه</p></li><li><p>سږي</p></li></ul><p>د زړه شاوخوا ځانګړی کهف:</p><p><strong>Pericardial Cavity</strong></p><p>او د هر سږي شاوخوا:</p><p><strong>Pleural Cavity</strong></p><p>شتون لري.</p><p>د لومړي سمستر لپاره مهمه خبره دا ده چې پوه شو:</p><p><strong>Thoracic Cavity → Heart + Lungs</strong></p><hr><h1>۲۰. Abdominopelvic Cavity</h1><h3 dir="rtl"></h3><p>د سینې لاندې لوی داخلي کهف ته:</p><p><strong>Abdominopelvic Cavity</strong></p><p>ویل کېږي.</p><p>دا په دوو برخو وېشل کېږي:</p><h3>Abdominal Cavity</h3><h3 dir="rtl"></h3><p><strong>د نس کهف</strong></p><h3>Pelvic Cavity</h3><h3 dir="rtl"></h3><p><strong>د حوض کهف</strong></p><hr><h1>۲۱. Abdominal Cavity</h1><h3 dir="rtl"></h3><p>په Abdominal Cavity کې ګڼ مهم غړي موقعیت لري.</p><p>د مثال په توګه:</p><ul><li><p>معده</p></li><li><p>ځیګر</p></li><li><p>کوچنۍ کولمې</p></li><li><p>لویې کولمې</p></li><li><p>پانقراس</p></li><li><p>تلی</p></li></ul><p>او پښتورګي د دې سیمې په شاتنۍ برخه کې موقعیت لري.</p><h3>مهم ټکی</h3><h3 dir="rtl"></h3><p>ټول غړي په یوه کوچنۍ نقطه کې نه دي.</p><p>هر غړی خپل ځانګړی موقعیت او اړیکې لري.</p><hr><h1>۲۲. Pelvic Cavity</h1><h3 dir="rtl"></h3><p><strong>Pelvic Cavity</strong> د حوض په داخلي برخه کې موقعیت لري.</p><p>په دې کې مهم جوړښتونه شامل دي، لکه:</p><ul><li><p>مثانه</p></li><li><p>د هاضمې د سیستم ځینې وروستۍ برخې</p></li><li><p>د ښځینه تولیدي سیستم ځینې مهم غړي</p></li></ul><p>د قابلې لپاره دا برخه ځانګړی اهمیت لري، ځکه د ښځینه تولیدي سیستم له مهمو جوړښتونو سره تړاو لري.</p><hr><h1>۲۳. د ښځینه تولیدي سیستم او Pelvic Cavity</h1><h3 dir="rtl"></h3><p>راځئ یو مهم کلینیکي تصور وکړو.</p><p>کله چې یوه ښځه امیندواره کېږي، رحم د حوض له سیمې سره تړاو لري او د امیندوارۍ په پرمختګ سره د رحم اندازه ډېره بدلېږي.</p><p>له همدې امله د:</p><p><strong>Pelvic Region</strong></p><p>او</p><p><strong>Pelvic Cavity</strong></p><p>مفهوم د قابله‌ګۍ زده‌کوونکو لپاره ډېر مهم دی.</p><p>په دې مرحله کې زموږ هدف د امیندوارۍ ټول بدلونونه نه دي؛ یوازې باید پوه شو چې د ښځینه تولیدي سیستم مهم جوړښتونه د حوض له سیمې او داخلي فضا سره نږدې اړیکه لري.</p><hr><h1>۲۴. د بدن کهفونه له بهر څخه دننه ته</h1><h3 dir="rtl"></h3><p>راځئ یو ساده ذهني نقشه جوړه کړو.</p><h3>Dorsal</h3><h3 dir="rtl"></h3><p><strong>Cranial Cavity → Brain</strong></p><p><strong>Vertebral Cavity → Spinal Cord</strong></p><h3>Ventral</h3><h3 dir="rtl"></h3><p><strong>Thoracic Cavity → Heart + Lungs</strong></p><p><strong>Abdominal Cavity → Digestive organs and others</strong></p><p><strong>Pelvic Cavity → Bladder + reproductive structures + others</strong></p><hr><h1>۲۵. د بدن کهفونو لویه نقشه</h1><h3 dir="rtl"></h3><table><thead><tr><th>لوی کهف</th><th>کوچنی کهف</th><th>مهم محتویات</th></tr></thead><tbody><tr><td>Dorsal Cavity</td><td>Cranial Cavity</td><td>Brain</td></tr><tr><td>Dorsal Cavity</td><td>Vertebral Cavity</td><td>Spinal Cord</td></tr><tr><td>Ventral Cavity</td><td>Thoracic Cavity</td><td>Heart, Lungs</td></tr><tr><td>Ventral Cavity</td><td>Abdominal Cavity</td><td>Stomach, Intestines, Liver او نور</td></tr><tr><td>Ventral Cavity</td><td>Pelvic Cavity</td><td>Bladder, reproductive structures او نور</td></tr></tbody></table><hr><h1>۲۶. کلینیکي سناریو ۱: د سینې درد</h1><h3 dir="rtl"></h3><p>یوه ناروغه روغتیايي مرکز ته راځي او وایي:</p><blockquote><p>«زما په سینه کې درد دی.»</p></blockquote><p>قابله باید پوه شي چې <strong>Thoracic Region</strong> د سینې سیمه ده او <strong>Thoracic Cavity</strong> د سینې داخلي کهف دی.</p><h3>پوښتنه</h3><h3 dir="rtl"></h3><p>ایا Region او Cavity یو شی دي؟</p><p><strong>نه.</strong></p><h3>ولې؟</h3><h3 dir="rtl"></h3><p>Thoracic Region د بدن د سینې سیمه بیانوي.</p><p>Thoracic Cavity د سینې دننه هغه فضا بیانوي چې مهم غړي پکې موقعیت لري.</p><h3>د قابلې لپاره درس</h3><h3 dir="rtl"></h3><p>د بدن د بهرنۍ سیمې او داخلي کهف توپیر باید واضح وي.</p><hr><h1>۲۷. کلینیکي سناریو ۲: د نس درد</h1><h3 dir="rtl"></h3><p>یوه ښځه وایي:</p><blockquote><p>«زما د نس درد دی.»</p></blockquote><p>دلته د "نس" کلمه عمومي معلومات ورکوي.</p><p>قابله باید هڅه وکړي چې موقعیت دقیق کړي.</p><p>مثلاً:</p><ul><li><p>د نس پورته برخه؟</p></li><li><p>ښکته برخه؟</p></li><li><p>ښی اړخ؟</p></li><li><p>کیڼ اړخ؟</p></li><li><p>منځنۍ برخه؟</p></li></ul><h3>علمي مفهوم</h3><h3 dir="rtl"></h3><p>Abdominal Region د بدن سیمه ده.</p><p>Abdominal Cavity د نس داخلي کهف دی.</p><h3>مهم درس</h3><h3 dir="rtl"></h3><p><strong>د درد د ځای دقیق بیان د ناروغ د ارزونې مهمه برخه ده.</strong></p><hr><h1>۲۸. کلینیکي سناریو ۳: د سر او مغز توپیر</h1><h3 dir="rtl"></h3><p>یو زده‌کوونکی وایي:</p><blockquote><p>«Brain د Head Region دی.»</p></blockquote><p>دا بیان نیمګړی دی.</p><p>Head Region یوه <strong>بهرنۍ/سیمه‌ییزه اصطلاح</strong> ده.</p><p>Brain یو <strong>داخلي غړی</strong> دی چې په <strong>Cranial Cavity</strong> کې موقعیت لري.</p><h3>نو:</h3><h3 dir="rtl"></h3><p><strong>Head Region → بهرنی موقعیت</strong></p><p><strong>Cranial Cavity → داخلي فضا</strong></p><p><strong>Brain → په دې فضا کې مهم غړی</strong></p><p>دا توپیر ډېر مهم دی.</p><hr><h1>۲۹. کلینیکي سناریو ۴: د قابله‌ګۍ اړیکه</h1><h3 dir="rtl"></h3><p>یوه امیندواره ښځه د حوض په برخه کې د فشار احساس بیانوي.</p><p>قابله باید پوه شي چې:</p><p><strong>Pelvic Region</strong></p><p>د بدن د حوض سیمه ده، او:</p><p><strong>Pelvic Cavity</strong></p><p>د حوض دننه فضا ده.</p><h3>مهم درس</h3><h3 dir="rtl"></h3><p>کله چې روغتیايي کارکوونکی د "سیمې" او "کهف" اصطلاحات په سمه توګه وکاروي، د بدن د موقعیت تشریح ډېره دقیقه کېږي.</p><hr><h1>۳۰. کلینیکي سناریو ۵: له کوچني څخه لوی مفهوم</h1><h3 dir="rtl"></h3><p>راځئ فرض کړو چې یوه ستونزه د بدن په یوه ځانګړې سیمه کې رامنځته کېږي.</p><p>قابله باید د بدن موقعیت په تدریجي ډول مشخص کړي:</p><p><strong>Body → Region → Specific location → Cavity → Organ</strong></p><p>مثلاً:</p><p><strong>بدن → تنه → Thoracic Region → Thoracic Cavity → Heart</strong></p><p>دا ډول فکر کول د طبي معلوماتو د تنظیم لپاره ډېر ګټور دي.</p><hr><h1>۳۱. د بدن سیمو د یادولو ساده نقشه</h1><h3>له سر څخه تر تنه:</h3><h3 dir="rtl"></h3><p><strong>Head</strong></p><p>↓</p><p><strong>Neck / Cervical</strong></p><p>↓</p><p><strong>Thoracic</strong></p><p>↓</p><p><strong>Abdominal</strong></p><p>↓</p><p><strong>Pelvic</strong></p><h3>پورتنی اندام:</h3><h3 dir="rtl"></h3><p><strong>Shoulder</strong></p><p>↓</p><p><strong>Arm</strong></p><p>↓</p><p><strong>Forearm</strong></p><p>↓</p><p><strong>Wrist</strong></p><p>↓</p><p><strong>Hand</strong></p><p>↓</p><p><strong>Fingers</strong></p><h3>ښکته اندام:</h3><h3 dir="rtl"></h3><p><strong>Hip</strong></p><p>↓</p><p><strong>Thigh</strong></p><p>↓</p><p><strong>Knee</strong></p><p>↓</p><p><strong>Leg</strong></p><p>↓</p><p><strong>Ankle</strong></p><p>↓</p><p><strong>Foot</strong></p><p>↓</p><p><strong>Toes</strong></p><hr><h1>۳۲. د زده‌کوونکو عامې تېروتنې</h1><h2>تېروتنه ۱: Region او Cavity یو شی ګڼل</h2><h3 dir="rtl"></h3><p>دا دواړه مختلف مفاهیم دي.</p><p><strong>Region = د بدن سیمه</strong></p><p><strong>Cavity = د بدن داخلي فضا</strong></p><hr><h2>تېروتنه ۲: Thoracic Region او Thoracic Cavity ګډول</h2><h3 dir="rtl"></h3><p>Region د سینې بهرنی/موقعیتي مفهوم دی.</p><p>Cavity د سینې دننه فضا ده.</p><hr><h2>تېروتنه ۳: Brain د Cranial Cavity په نوم یادول</h2><h3 dir="rtl"></h3><p>Brain یو <strong>غړی</strong> دی.</p><p>Cranial Cavity هغه <strong>کهف</strong> دی چې Brain پکې موقعیت لري.</p><hr><h2>تېروتنه ۴: د بدن ټول داخلي غړي په یوه کهف کې ګڼل</h2><h3 dir="rtl"></h3><p>هر غړی د بدن په یوه ځانګړي موقعیت کې وي او ټول غړي په یوه واحد کهف کې نه دي.</p><hr><h2>تېروتنه ۵: Pelvic Region او Pelvic Cavity ګډول</h2><h3 dir="rtl"></h3><p>Pelvic Region د بدن سیمه ده.</p><p>Pelvic Cavity د همدې سیمې دننه داخلي فضا ده.</p><hr><h1>۳۳. د قابلې لپاره د دې موضوع اهمیت</h1><h3 dir="rtl"></h3><p>د بدن سیمې او کهفونه د قابلې لپاره ځکه مهم دي چې:</p><ul><li><p>د ناروغ د شکایت ځای په دقیق ډول تشریح کړي.</p></li><li><p>د معاینې موندنې منظمې ثبت کړي.</p></li><li><p>د روغتیايي ټیم له نورو غړو سره واضح اړیکه ولري.</p></li><li><p>د بدن د داخلي غړو موقعیت درک کړي.</p></li><li><p>د راتلونکو درسونو لپاره بنسټ جوړ کړي.</p></li><li><p>د ښځینه تولیدي سیستم موقعیت ښه درک کړي.</p></li><li><p>د امیندوارۍ پر مهال د بدن د بدلونونو د موقعیت په پوهېدو کې مرسته وکړي.</p></li></ul><hr><h1>۳۴. انفرادي آنلاین LMS فعالیت</h1><h2>فعالیت: «سیمه، کهف او غړی سره وصل کړه»</h2><h3 dir="rtl"></h3><p>په آنلاین سیستم کې زده‌کوونکې ته درې کالمونه ورکړل شي:</p><h3>لومړی کالم: Region</h3><h3 dir="rtl"><ul><li><p>Head</p></li><li><p>Thoracic</p></li><li><p>Abdominal</p></li><li><p>Pelvic</p></li></ul></h3><h3>دوهم کالم: Cavity</h3><h3 dir="rtl"><ul><li><p>Cranial Cavity</p></li><li><p>Thoracic Cavity</p></li><li><p>Abdominal Cavity</p></li><li><p>Pelvic Cavity</p></li></ul></h3><h3>درېیم کالم: Organ</h3><h3 dir="rtl"><ul><li><p>Brain</p></li><li><p>Heart</p></li><li><p>Stomach</p></li><li><p>Urinary Bladder</p></li></ul></h3><p>زده‌کوونکې باید مناسب ارتباط جوړ کړي.</p><h3>مثال:</h3><h3 dir="rtl"></h3><p><strong>Head → Cranial Cavity → Brain</strong></p><p><strong>Thoracic → Thoracic Cavity → Heart</strong></p><p><strong>Abdominal → Abdominal Cavity → Stomach</strong></p><p><strong>Pelvic → Pelvic Cavity → Urinary Bladder</strong></p><h3>د فعالیت هدف</h3><h3 dir="rtl"></h3><p>زده‌کوونکې باید وکولای شي:</p><p><strong>Region → Cavity → Organ</strong></p><p>ترمنځ اړیکه په سمه توګه درک کړي.</p><hr><h1>۳۵. د درس مهم لغاتونه</h1><h3 dir="rtl"></h3><table><thead><tr><th>پښتو اصطلاح</th><th>English Term</th><th>ساده تشریح</th></tr></thead><tbody><tr><td>د بدن سیمه</td><td>Body Region</td><td>د بدن ځانګړی موقعیت</td></tr><tr><td>کهف/تش فضا</td><td>Body Cavity</td><td>د بدن داخلي فضا</td></tr><tr><td>محوري برخه</td><td>Axial Region</td><td>د بدن مرکزي برخه</td></tr><tr><td>اندامي برخه</td><td>Appendicular Region</td><td>د بدن تړلي اندامونه</td></tr><tr><td>د سر سیمه</td><td>Head Region</td><td>د سر برخه</td></tr><tr><td>د مخ سیمه</td><td>Facial Region</td><td>د مخ برخه</td></tr><tr><td>د غاړې سیمه</td><td>Cervical Region</td><td>د غاړې برخه</td></tr><tr><td>د سینې سیمه</td><td>Thoracic Region</td><td>د سینې برخه</td></tr><tr><td>د نس سیمه</td><td>Abdominal Region</td><td>د نس/شکم برخه</td></tr><tr><td>د حوض سیمه</td><td>Pelvic Region</td><td>د حوض برخه</td></tr><tr><td>د کوپړۍ کهف</td><td>Cranial Cavity</td><td>د مغز دننه فضا</td></tr><tr><td>د ملا کهف</td><td>Vertebral Cavity</td><td>د شوکي نخاع فضا</td></tr><tr><td>د سینې کهف</td><td>Thoracic Cavity</td><td>د زړه او سږو اړوند لوی کهف</td></tr><tr><td>د نس کهف</td><td>Abdominal Cavity</td><td>د نس د غړو داخلي فضا</td></tr><tr><td>د حوض کهف</td><td>Pelvic Cavity</td><td>د حوض دننه فضا</td></tr><tr><td>مغز</td><td>Brain</td><td>په Cranial Cavity کې موقعیت لري</td></tr><tr><td>شوکي نخاع</td><td>Spinal Cord</td><td>په Vertebral Cavity کې موقعیت لري</td></tr><tr><td>زړه</td><td>Heart</td><td>په Thoracic Cavity کې موقعیت لري</td></tr><tr><td>سږي</td><td>Lungs</td><td>په Thoracic Cavity کې موقعیت لري</td></tr></tbody></table><hr><h1>۳۶. د درس لنډیز</h1><h3 dir="rtl"></h3><p>نن مو دوه مهم مفاهیم زده کړل:</p><h2>Body Regions</h2><h3 dir="rtl"></h3><p>د بدن مهمې سیمې:</p><p><strong>Head</strong></p><p><strong>Cervical</strong></p><p><strong>Thoracic</strong></p><p><strong>Abdominal</strong></p><p><strong>Pelvic</strong></p><p>او د لاسونو او پښو ځانګړې سیمې.</p><h2>Body Cavities</h2><h3 dir="rtl"></h3><p>مهم کهفونه:</p><p><strong>Cranial Cavity → Brain</strong></p><p><strong>Vertebral Cavity → Spinal Cord</strong></p><p><strong>Thoracic Cavity → Heart and Lungs</strong></p><p><strong>Abdominal Cavity → Abdominal organs</strong></p><p><strong>Pelvic Cavity → Pelvic organs</strong></p><p>تر ټولو مهم مفهوم:</p><blockquote><p><strong>Region د بدن یوه سیمه ده، خو Cavity د بدن دننه یوه فضا ده.</strong></p></blockquote><hr><h1>۳۷. ارزونې پوښتنې</h1><h2>لومړۍ برخه: Multiple Choice – Single Answer</h2><h3>پوښتنه ۱</h3><h3 dir="rtl"></h3><p>Thoracic Region د بدن کومه برخه ده؟</p><p>A. سر<br>B. غاړه<br>C. سینه<br>D. پښه</p><p><strong>صحیح ځواب: C. سینه</strong></p><p><strong>تشریح:</strong> Thoracic Region د بدن د سینې سیمه ده.</p><hr><h3>پوښتنه ۲</h3><h3 dir="rtl"></h3><p>Brain په کوم کهف کې موقعیت لري؟</p><p>A. Pelvic Cavity<br>B. Cranial Cavity<br>C. Abdominal Cavity<br>D. Thoracic Cavity</p><p><strong>صحیح ځواب: B. Cranial Cavity</strong></p><p><strong>تشریح:</strong> Cranial Cavity د کوپړۍ دننه فضا ده او Brain پکې موقعیت لري.</p><hr><h3>پوښتنه ۳</h3><h3 dir="rtl"></h3><p>کوم کهف د زړه او سږو سره تړاو لري؟</p><p>A. Cranial Cavity<br>B. Vertebral Cavity<br>C. Thoracic Cavity<br>D. Pelvic Cavity</p><p><strong>صحیح ځواب: C. Thoracic Cavity</strong></p><p><strong>تشریح:</strong> Thoracic Cavity د سینې دننه لوی کهف دی چې زړه او سږي پکې موقعیت لري.</p><hr><h3>پوښتنه ۴</h3><h3 dir="rtl"></h3><p>Pelvic Region او Pelvic Cavity ترمنځ اساسي توپیر څه دی؟</p><p>A. دواړه یو شی دي<br>B. Region داخلي غړی دی<br>C. Region سیمه ده او Cavity داخلي فضا ده<br>D. Cavity یوازې د سر لپاره کارېږي</p><p><strong>صحیح ځواب: C</strong></p><p><strong>تشریح:</strong> Region د بدن موقعیتي سیمه ده، خو Cavity د بدن دننه تشه/فضا ده.</p><hr><h3>پوښتنه ۵</h3><h3 dir="rtl"></h3><p>Vertebral Cavity کې کوم مهم جوړښت موقعیت لري؟</p><p>A. Brain<br>B. Spinal Cord<br>C. Heart<br>D. Stomach</p><p><strong>صحیح ځواب: B. Spinal Cord</strong></p><p><strong>تشریح:</strong> Vertebral Cavity د ستون فقرات دننه موقعیت لري او Spinal Cord پکې خوندي دی.</p><hr><h1>دوهمه برخه: True / False</h1><h3>پوښتنه ۶</h3><h3 dir="rtl"></h3><p>Abdominal Region او Abdominal Cavity دقیقاً یو شی دي.</p><p><strong>صحیح ځواب: False</strong></p><p><strong>تشریح:</strong> Abdominal Region د بدن یوه سیمه ده، خو Abdominal Cavity د بدن دننه فضا ده.</p><hr><h3>پوښتنه ۷</h3><h3 dir="rtl"></h3><p>Cranial Cavity د Brain سره تړاو لري.</p><p><strong>صحیح ځواب: True</strong></p><p><strong>تشریح:</strong> Brain د Cranial Cavity دننه موقعیت لري.</p><hr><h3>پوښتنه ۸</h3><h3 dir="rtl"></h3><p>Thoracic Cavity د بدن د سینې په داخلي برخه کې موقعیت لري.</p><p><strong>صحیح ځواب: True</strong></p><p><strong>تشریح:</strong> Thoracic Cavity د Thoracic Region په داخلي برخه کې لوی کهف دی او مهم غړي لکه زړه او سږي پکې موقعیت لري.</p><hr><h1>درېیمه برخه: Short Answer</h1><h3>پوښتنه ۹</h3><h3 dir="rtl"></h3><p>Body Region او Body Cavity په خپلو الفاظو تشریح کړئ.</p><p><strong>نمونوي ځواب:</strong></p><p>Body Region د بدن یوه ځانګړې سیمه یا موقعیت دی، لکه Thoracic Region. Body Cavity بیا د بدن دننه یوه تشه یا فضا ده چې مهم غړي پکې موقعیت لري، لکه Thoracic Cavity چې زړه او سږي پکې موقعیت لري.</p><hr><h3>پوښتنه ۱۰</h3><h3 dir="rtl"></h3><p>د پنځو مهمو Body Cavities نومونه او د هر یوه مهم غړی ولیکئ.</p><p><strong>نمونوي ځواب:</strong></p><ul><li><p>Cranial Cavity → Brain</p></li><li><p>Vertebral Cavity → Spinal Cord</p></li><li><p>Thoracic Cavity → Heart/Lungs</p></li><li><p>Abdominal Cavity → Stomach/Intestines</p></li><li><p>Pelvic Cavity → Urinary Bladder او د حوض اړوند جوړښتونه</p></li></ul><hr><h1>۳۸. وروستی جامع کلینیکي سناریو</h1><h3 dir="rtl"></h3><p>یوه ښځه د روغتیايي مرکز لپاره مراجعه کوي او وایي چې د نس په ښکته برخه کې د ناراحتۍ احساس لري.</p><p>قابله غواړي د بدن د موقعیت په اړه معلومات په مسلکي ډول تنظیم کړي.</p><h3>پوښتنه ۱</h3><h3 dir="rtl"></h3><p>د بدن د کومې عمومي سیمې سره دا شکایت تړاو لري؟</p><p><strong>ځواب: Abdominal یا Pelvic Region</strong>، د دقیق موقعیت له مخې.</p><h3>د ښوونکي تشریح</h3><h3 dir="rtl"></h3><p>د "ښکته نس" اصطلاح ممکن د Abdominal Region ټیټې برخې یا Pelvic Region سره تړاو ولري؛ نو قابله باید د موقعیت نور جزئیات معلوم کړي.</p><hr><h3>پوښتنه ۲</h3><h3 dir="rtl"></h3><p>که شکایت د حوض له داخلي جوړښتونو سره تړاو ولري، کوم Body Cavity باید په پام کې ونیول شي؟</p><p><strong>ځواب: Pelvic Cavity</strong></p><h3>تشریح</h3><h3 dir="rtl"></h3><p>Pelvic Cavity د حوض دننه فضا ده چې د حوض اړوند مهم جوړښتونه پکې موقعیت لري.</p><hr><h3>پوښتنه ۳</h3><h3 dir="rtl"></h3><p>که ناروغې د سینې د درد شکایت وکړي، کوم Region او Cavity باید په ذهن کې وي؟</p><p><strong>ځواب:</strong></p><p><strong>Thoracic Region → Thoracic Cavity</strong></p><h3>تشریح</h3><h3 dir="rtl"></h3><p>Thoracic Region د سینې سیمه ده، او Thoracic Cavity د سینې دننه لوی کهف دی.</p><hr><h3>پوښتنه ۴</h3><h3 dir="rtl"></h3><p>Brain او Cranial Cavity څه توپیر لري؟</p><p><strong>ځواب:</strong></p><p>Brain یو غړی دی.</p><p>Cranial Cavity هغه داخلي فضا ده چې Brain پکې موقعیت لري.</p><hr><h3>پوښتنه ۵</h3><h3 dir="rtl"></h3><p>ولې د Body Regions او Body Cavities توپیر د یوې قابلې لپاره مهم دی؟</p><p><strong>ځواب:</strong></p><p>ځکه قابله باید وکولای شي د ناروغ د شکایت یا معاینې ځای په دقیق او مسلکي ډول بیان کړي او د بدن د داخلي غړو موقعیت په سمه توګه درک کړي.</p><hr><h1>۳۹. د ښوونکي وروستی پیغام</h1><h3 dir="rtl"></h3><p>ګرانو زده‌کوونکو!</p><p>نن مو یوازې د بدن د سیمو نومونه حفظ نه کړل.</p><p>موږ زده کړل چې د بدن په اړه باید <strong>له عمومي څخه مشخص</strong> فکر وکړو.</p><p>کله چې ناروغه وایي:</p><p><strong>«زما نس درد کوي.»</strong></p><p>تاسو باید ذهن کې دا پوښتنه ولرئ:</p><p><strong>کومه سیمه؟</strong></p><p>بیا:</p><p><strong>کوم ځای؟</strong></p><p>بیا:</p><p><strong>کوم داخلي کهف؟</strong></p><p>او په پای کې:</p><p><strong>کوم جوړښت یا غړی؟</strong></p><p>همدا ډول منظم فکر کول د یوې مسلکي قابلې لپاره ډېر مهم دي.</p><p>تل هڅه وکړئ چې د بدن نومونه یوازې حفظ نه کړئ؛ بلکې د هرې سیمې، کهف او غړي ترمنځ <strong>موقعیتي اړیکه</strong> درک کړئ.</p><p>کله چې دا اړیکې مو ذهن کې جوړې شوې، راتلونکي درسونه به درته ډېر اسانه شي.</p>', 'rtl', 'url', 'https://www.youtube.com/watch?v=1ugYf9ezKv4', NULL, 28, 'intro', 9, TRUE, 4, TRUE, '2026-09-13 04:39:29'),
(332, 33, 'هومیوستاز — د بدن انډول', '<p dir="rtl" style="text-align:right">هومیوستاز هغه پروسه ده چې بدن پرې خپل دننه چاپیریال ثابت ساتي.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>هومیوستاز تعریف کړئ.</li><li>د منفي فیډبک لوپ بیان کړئ.</li><li>د مثبت فیډبک یوه بیلګه ورکړئ.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">هومیوستاز هغه پروسه ده چې بدن پرې خپل دننه چاپیریال ثابت ساتي.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>هومیوستاز یعنې د حرارت، pH، ګلوکوز او مایعاتو ثابت ساتل.</li><li>منفي فیډبک تر ټولو عام میکانیزم دی — بدلون بیرته نورمال ته ګرځوي.</li><li>مثبت فیډبک بدلون زیاتوي، لکه د زیږون پر مهال د اوکسیتوسین دوره.</li><li>ریسپټر، کنټرول مرکز او افیکټر د هر لوپ درې برخې دي.</li><li>د هومیوستاز ماتیدل ناروغي رامنځته کوي.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>هومیوستاز</td><td dir="ltr" style="text-align:left">Homeostasis</td></tr><tr><td>منفي فیډبک</td><td dir="ltr" style="text-align:left">Negative feedback</td></tr><tr><td>مثبت فیډبک</td><td dir="ltr" style="text-align:left">Positive feedback</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>د زیږون پر مهال د فرګسون رفلکس یو مثبت فیډبک دی: د رحم غاړې فشار اوکسیتوسین زیاتوي، اوکسیتوسین انقباض زیاتوي.</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'url', 'https://www.youtube.com/watch?v=z9S98gPtVZ8', NULL, 30, 'intro', 11, TRUE, 5, TRUE, '2026-09-13 04:39:29'),
(333, 33, 'د حجرې جوړښت', '<p dir="rtl" style="text-align:right">حجره د ژوند بنسټیز واحد دی؛ د هغې جوړښت پیژندل د ټولې فزیولوژۍ لپاره اړین دي.</p>', '<h1>درس: د حجرې جوړښت</h1><h2>Cell Structure</h2><h3>د درس عمومي هدف</h3><h3 dir="rtl">


</h3><p>د دې درس تر پای پورې به زده‌کوونکې وکولای شي:</p>
<ol>
<li>
حجره (Cell) په ساده او علمي ډول تشریح کړي.
</li>
<li>
د حجرې عمومي جوړښت وپېژني.
</li>
<li>
د <strong>Cell Membrane, Cytoplasm, Nucleus</strong> دندې تشریح کړي.
</li>
<li>
مهم Cell Organelles وپېژني.
</li>
<li>
د هر Organelle جوړښت او دنده سره وتړي.
</li>
<li>
د Mitochondria، Ribosome، ER، Golgi Apparatus او Lysosome دندې توپیر کړي.
</li>
<li>
د حجرې د غشا اهمیت درک کړي.
</li>
<li>
د Nucleus او DNA اړیکه تشریح کړي.
</li>
<li>
د حجرې جوړښت د انسان د بدن له نسجونو او غړو سره وصل کړي.
</li>
<li>
د قابلګۍ په عملي کار کې د Cell Structure اهمیت درک کړي.
</li>
</ol>
<hr>
<h1>۱. له تېر درس څخه نوي درس ته</h1><h3 dir="rtl">
</h3><p>په تېرو درسونو کې مو د بدن لویه نقشه زده کړه:</p>
<p><strong>Body Regions → Body Cavities → Organs</strong></p>
<p>موږ زده کړل چې:</p>
<ul>
<li>
Heart په Thoracic Cavity کې دی.
</li>
<li>
Lungs په Thoracic Cavity کې دي.
</li>
<li>
Stomach په Abdominal Cavity کې دی.
</li>
<li>
Uterus د Pelvic Region/Cavity سره تړاو لري.
</li>
<li>
Brain په Cranial Cavity کې دی.
</li>
</ul>
<p>اوس یوه ډېره مهمه پوښتنه پیدا کېږي:</p>
<blockquote>
<p><strong>دا غړي له څه شي جوړ شوي دي؟</strong></p>
</blockquote>
<p>مثلاً:</p>
<p>Heart له څه څخه جوړ شوی؟</p>
<p>Uterus له څه څخه جوړ شوی؟</p>
<p>Skin له څه څخه جوړه شوې؟</p>
<p>Muscles له څه څخه جوړ شوي؟</p>
<p>د دې پوښتنې ځواب:</p>
<blockquote>
<p><strong>Cells — حجرې</strong></p>
</blockquote>
<p>د انسان د بدن غړي د نسجونو (Tissues) څخه جوړېږي، نسجونه له حجرو څخه جوړېږي، او حجره د ژوند د اساسي جوړښتي او فعالي واحد په توګه پېژندل کېږي.</p>
<p>نو د بدن د جوړښت لړۍ داسې ده:</p>
<p><strong>Cell → Tissue → Organ → Organ System → Human Body</strong></p>
<hr>
<h1>۲. حجره څه ده؟</h1><h2>Cell — حجره</h2><h3 dir="rtl">

</h3><p>حجره د ژوند یو بنسټیز جوړښتي او وظیفوي واحد دی.</p>
<p>په ساده ژبه:</p>
<blockquote>
<p>حجره د بدن هغه کوچنی ژوندی واحد دی چې د ژوند مهمې دندې ترسره کوي.</p>
</blockquote>
<p>زموږ بدن یوازې له یوې حجرې نه دی جوړ.</p>
<p>د انسان بدن له <strong>ډېرو بېلابېلو حجرو</strong> څخه جوړ شوی چې هره یوه ځانګړې دنده لري.</p>
<p>مثلاً:</p>
<ul>
<li>
Nerve Cell → عصبي پیغامونه انتقالوي.
</li>
<li>
Muscle Cell → د عضلاتو د حرکت لپاره کار کوي.
</li>
<li>
Red Blood Cell → اکسیجن انتقالوي.
</li>
<li>
Epithelial Cell → د بدن سطحې او ځینې داخلي جوړښتونه پوښي.
</li>
<li>
Reproductive Cells → د تولید مثل په پروسو کې برخه اخلي.
</li>
</ul>
<p>نو:</p>
<blockquote>
<p>ټولې حجرې یو شان نه دي.</p>
</blockquote>
<hr>
<h1>۳. د حجرې د زده‌کړې تر ټولو مهمه مفکوره</h1><h3 dir="rtl">
</h3><p>کله چې موږ یوه حجره مطالعه کوو، درې اساسي برخې باید لومړی وپېژنو:</p>
<h3>1. Cell Membrane</h3><h3 dir="rtl">
</h3><p>د حجرې غشا</p>
<h3>2. Cytoplasm</h3><h3 dir="rtl">
</h3><p>سایتوپلازم</p>
<h3>3. Nucleus</h3><h3 dir="rtl">
</h3><p>هسته</p>
<p>په ډېرو انساني حجرو کې دا درې برخې د حجرې د عمومي جوړښت د پوهېدو لپاره بنسټیزې دي.</p>
<p>خو Cytoplasm خپله یوازې یوه ساده ماده نه ده؛ په دې کې ګڼ مهم <strong>Organelles</strong> موجود وي.</p>
<hr>
<h1>۴. د حجرې عمومي نقشه</h1><h3 dir="rtl">
</h3><p>د یوې عادي انساني حجرې تصور داسې وکړئ:</p>
<p><strong>Cell Membrane</strong></p>
<p>↓</p>
<p>د حجرې بهرنۍ پوله</p>
<hr>
<p>دننه:</p>
<p><strong>Cytoplasm</strong></p>
<p>↓</p>
<p><strong>Organelles</strong></p>
<p>او په ډېرو حجرو کې:</p>
<p><strong>Nucleus</strong></p>
<p>↓</p>
<p><strong>DNA</strong></p>
<p>دا جوړښتونه یو له بل سره کار کوي ترڅو حجره ژوندۍ پاتې شي.</p>
<hr>
<h1>۵. Cell Membrane — د حجرې غشا</h1><h3 dir="rtl">
</h3><p><strong>Cell Membrane</strong> د حجرې بهرنۍ نرۍ غشا ده چې حجره له خپل چاپېریال څخه جلا کوي.</p>
<p>خو یوازې "پوښ" نه دی.</p>
<p>دا یو <strong>Selective Barrier</strong> دی.</p>
<p>یعنې:</p>
<blockquote>
<p>هر شی په ازاد ډول حجرې ته نه شي داخلېدای او هر شی په ازاد ډول له حجرې څخه نه شي وتلای.</p>
</blockquote>
<hr>
<h1>۶. Cell Membrane ولې مهمه ده؟</h1><h3 dir="rtl">
</h3><p>حجره باید خپل داخلي چاپېریال تر یوې اندازې منظم وساتي.</p>
<p>د مثال په توګه:</p>
<p>حجره اړتیا لري چې:</p>
<ul>
<li>
غذايي مواد ترلاسه کړي.
</li>
<li>
اکسیجن ترلاسه کړي.
</li>
<li>
ځینې مواد خارج کړي.
</li>
<li>
د اوبو اندازه تنظیم کړي.
</li>
<li>
د کیمیاوي پیغامونو ځواب ورکړي.
</li>
</ul>
<p>Cell Membrane په دې پروسو کې مهم رول لري.</p>
<hr>
<h1>۷. د Cell Membrane ساده مثال</h1><h3 dir="rtl">
</h3><p>د حجرې غشا د یوه <strong>هوښیار امنیتي دروازې</strong> په څېر تصور کړئ.</p>
<p>د یوه کور دروازه هر څوک نه پرېږدي چې داخل شي.</p>
<p>همدارنګه Cell Membrane هم د موادو تګ راتګ تنظیموي.</p>
<p>خو باید پام وشي:</p>
<blockquote>
<p>Cell Membrane یوازې "دروازه" نه ده؛ دا یوه پیچلې بیولوژیکه غشا ده چې د حجروي ارتباط، انتقال او ثبات په تنظیم کې هم رول لري.</p>
</blockquote>
<hr>
<h1>۸. د Cell Membrane جوړښت</h1><h3 dir="rtl">
</h3><p>Cell Membrane عمدتاً د <strong>Phospholipid Bilayer</strong> څخه جوړه شوې ده.</p>
<h3>Phospholipid</h3><h3 dir="rtl">
</h3><p>Phospholipid دوه مهمې برخې لري:</p>
<ul>
<li>
Hydrophilic Head
</li>
<li>
Hydrophobic Tails
</li>
</ul>
<h3>Hydrophilic Head</h3><h3 dir="rtl">
</h3><p>د اوبو سره میلان لري.</p>
<h3>Hydrophobic Tails</h3><h3 dir="rtl">
</h3><p>له اوبو څخه د ځان ساتلو تمایل لري.</p>
<p>د دې ځانګړتیا له امله phospholipids په دوه طبقو کې تنظیمېږي.</p>
<p>دې ته:</p>
<p><strong>Phospholipid Bilayer</strong></p>
<p>ویل کېږي.</p>
<hr>
<h1>۹. Membrane Proteins</h1><h3 dir="rtl">
</h3><p>په Cell Membrane کې مختلف <strong>Proteins</strong> هم موجود وي.</p>
<p>دوی بېلابېلې دندې ترسره کوي، لکه:</p>
<ul>
<li>
Transport
</li>
<li>
Receptors
</li>
<li>
Cell communication
</li>
<li>
Enzyme activity
</li>
<li>
Cell recognition
</li>
</ul>
<p>نو د Cell Membrane ساده جوړښت داسې تصور کړئ:</p>
<p><strong>Phospholipid Bilayer + Proteins + Other Components</strong></p>
<hr>
<h1>۱۰. Cytoplasm — سایتوپلازم</h1><h3 dir="rtl">
</h3><p><strong>Cytoplasm</strong> د حجرې هغه داخلي برخه ده چې د Cell Membrane دننه موجوده ده او د Nucleus شاوخوا/بهر Cytosol او Organelles پکې شامل دي.</p>
<p>په ساده ډول:</p>
<blockquote>
<p>Cytoplasm هغه داخلي چاپېریال دی چې د حجرې ډېری Organelles پکې موقعیت لري.</p>
</blockquote>
<p>په Cytoplasm کې:</p>
<ul>
<li>
Cytosol
</li>
<li>
Organelles
</li>
<li>
مختلف کیمیاوي مواد
</li>
</ul>
<p>موجود وي.</p>
<hr>
<h1>۱۱. Cytosol او Cytoplasm یو شی نه دي</h1><h3 dir="rtl">
</h3><p>دا یو مهم امتحاني ټکی دی.</p>
<h3>Cytosol</h3><h3 dir="rtl">
</h3><p>د حجرې داخلي مایع برخه ده.</p>
<h3>Cytoplasm</h3><h3 dir="rtl">
</h3><p>په عمومي ډول د حجرې هغه برخه ده چې د Cell Membrane دننه او د Nucleus بهر ده، چې Cytosol او Organelles پکې شامل دي.</p>
<p>نو:</p>
<p><strong>Cytosol ≠ Cytoplasm</strong></p>
<hr>
<h1>۱۲. Nucleus — هسته</h1><h3 dir="rtl">
</h3><p><strong>Nucleus (هسته)</strong> د ډېرو انساني حجرو یو مهم کنټرولي جوړښت دی.</p>
<p>دا د حجرې جنیټیک معلومات لري.</p>
<p>په Nucleus کې:</p>
<p><strong>DNA</strong></p>
<p>موجود دی.</p>
<p>DNA د حجرې د جوړښت، فعالیت او د پروټینونو د جوړېدو اړوند مهم جنیټیک معلومات ساتي.</p>
<hr>
<h1>۱۳. DNA څه شی دی؟</h1><h3 dir="rtl">
</h3><p><strong>DNA — Deoxyribonucleic Acid</strong></p>
<p>DNA هغه مالیکول دی چې د ژوند جنیټیک معلومات پکې ذخیره کېږي.</p>
<p>په ساده مثال:</p>
<p>که یوه حجره یو کوچنی "فابریکه" وګڼو، DNA د هغې د جوړښت او فعالیت لپاره د مهمو لارښوونو د ذخیرې په څېر تصور کېدای شي.</p>
<p>خو DNA یوازې د یوې ساده "کتاب" په څېر نه دی؛ دا د حجرې د جنیټیک معلوماتو یوه پیچلې مالیکولي ذخیره ده.</p>
<hr>
<h1>۱۴. Chromosomes — کروموزومونه</h1><h3 dir="rtl">
</h3><p>DNA په Nucleus کې په منظم ډول له پروټینونو سره تنظیم شوی وي او <strong>Chromosomes</strong> جوړوي.</p>
<p>د انسان په عادي Somatic Cells کې:</p>
<p><strong>46 Chromosomes</strong></p>
<p>په 23 جوړو کې موجود وي.</p>
<p>خو ټولې حجرې یو شان نه دي؛ د مثال په توګه Mature Red Blood Cells هسته نه لري.</p>
<hr>
<h1>۱۵. Nucleolus — هستک</h1><h3 dir="rtl">
</h3><p>په Nucleus کې یو مهم جوړښت:</p>
<p><strong>Nucleolus</strong></p>
<p>دی.</p>
<p>Nucleolus په ځانګړې توګه د <strong>Ribosomal RNA</strong> او د Ribosome د برخو په جوړولو کې مهم رول لري.</p>
<p>نو:</p>
<p><strong>Nucleus → Nucleolus → Ribosome production-related activity</strong></p>
<hr>
<h1>۱۶. Mitochondria — میتوکونډریا</h1><h3 dir="rtl">
</h3><p>اوس د حجرې یوې ډېرې مشهورې برخې ته راځو:</p>
<p><strong>Mitochondria</strong></p>
<p>د دې مشهور نوم:</p>
<blockquote>
<p><strong>Powerhouse of the Cell</strong></p>
</blockquote>
<p>دی.</p>
<p>ولې؟</p>
<p>ځکه Mitochondria د حجروي انرژۍ د تولید په پروسو کې مهم رول لري.</p>
<p>په ځانګړې توګه د:</p>
<p><strong>ATP — Adenosine Triphosphate</strong></p>
<p>په تولید کې مهم دي.</p>
<hr>
<h1>۱۷. ATP څه شی دی؟</h1><h3 dir="rtl">
</h3><p>ATP د حجرې لپاره د انرژۍ د انتقال یو مهم مالیکول دی.</p>
<p>حجره د خپلو ډېرو دندو لپاره انرژۍ ته اړتیا لري.</p>
<p>لکه:</p>
<ul>
<li>
Active Transport
</li>
<li>
Muscle contraction
</li>
<li>
Protein synthesis
</li>
<li>
Cellular processes
</li>
</ul>
<p>نو:</p>
<p><strong>Food → Cellular metabolism → ATP → Cellular work</strong></p>
<hr>
<h1>۱۸. ولې Mitochondria د قابلګۍ لپاره مهم دي؟</h1><h3 dir="rtl">
</h3><p>د انسان بدن کې حجرې تل انرژۍ ته اړتیا لري.</p>
<p>مثلاً:</p>
<ul>
<li>
د زړه عضلات
</li>
<li>
د رحم عضلات
</li>
<li>
د عصبي سیستم حجرې
</li>
<li>
د بدن د نورو فعالو نسجونو حجرې
</li>
</ul>
<p>ټولې د حجروي انرژۍ اړتیا لري.</p>
<p>د حجرې د انرژۍ تولید مفهوم به وروسته د <strong>Cellular Respiration</strong> په درسونو کې لا ژور زده کړو.</p>
<hr>
<h1>۱۹. Ribosomes — رایبوزومونه</h1><h3 dir="rtl">
</h3><p><strong>Ribosome</strong> د پروټینونو په جوړولو کې مهم جوړښت دی.</p>
<p>پروټینونه د بدن لپاره ډېر مهم دي.</p>
<p>دوی په:</p>
<ul>
<li>
عضلاتو
</li>
<li>
انزایمونو
</li>
<li>
هورموني جوړښتونو
</li>
<li>
حجروي جوړښتونو
</li>
<li>
Receptors
</li>
</ul>
<p>کې مهم رول لري.</p>
<p>نو:</p>
<blockquote>
<p><strong>Ribosome = Protein synthesis</strong></p>
</blockquote>
<p>دا جمله حتماً زده کړئ.</p>
<hr>
<h1>۲۰. Endoplasmic Reticulum — ER</h1><h3 dir="rtl">
</h3><p><strong>Endoplasmic Reticulum (ER)</strong> د حجرې دننه د غشا لرونکو جوړښتونو یوه شبکه ده.</p>
<p>دوه مهم ډولونه لري:</p>
<h3>Rough ER</h3><h3 dir="rtl">
</h3><p>د سطحې پر سر Ribosomes لري.</p>
<p>اصلي دنده:</p>
<p><strong>Protein synthesis and processing</strong></p>
<p>په ځانګړې توګه د هغو پروټینونو لپاره چې د حجرې له لارې انتقال یا خارجېدلای شي.</p>
<h3>Smooth ER</h3><h3 dir="rtl">
</h3><p>Ribosomes نه لري.</p>
<p>مهمې دندې یې:</p>
<ul>
<li>
Lipid synthesis
</li>
<li>
Detoxification
</li>
<li>
Calcium storage په ځانګړو حجرو کې
</li>
</ul>
<hr>
<h1>۲۱. Rough ER څنګه کار کوي؟</h1><h3 dir="rtl">
</h3><p>یو ساده مسیر تصور کړئ:</p>
<p><strong>DNA</strong></p>
<p>↓</p>
<p><strong>mRNA</strong></p>
<p>↓</p>
<p><strong>Ribosome</strong></p>
<p>↓</p>
<p><strong>Protein</strong></p>
<p>که پروټین د Rough ER له لارې جوړېږي:</p>
<p><strong>Rough ER → Protein processing/transport → Golgi Apparatus</strong></p>
<p>دا د حجرې دننه د پروټینونو د جوړېدو او انتقال یوه مهمه لړۍ ده.</p>
<hr>
<h1>۲۲. Golgi Apparatus — ګولجي دستګاه</h1><h3 dir="rtl">
</h3><p><strong>Golgi Apparatus</strong> د حجرې د پروټینونو او نورو موادو په modification, sorting او packaging کې مهم رول لري.</p>
<p>د پوستې یا د بسته‌بندۍ مرکز مثال ورته کارولای شو.</p>
<p>یعنې:</p>
<p><strong>ER → Golgi → Sorting/Packaging → Destination</strong></p>
<p>مثلاً یو پروټین جوړ شو.</p>
<p>بیا:</p>
<ol>
<li>
ER ته لاړ.
</li>
<li>
Processing وشوه.
</li>
<li>
Golgi ته انتقال شو.
</li>
<li>
Golgi هغه Modify/Sort کړ.
</li>
<li>
مناسب ځای ته انتقال شو.
</li>
</ol>
<hr>
<h1>۲۳. Lysosomes — لایسوزومونه</h1><h3 dir="rtl">
</h3><p><strong>Lysosomes</strong> د حجرې د هضم او د ځینو زړو یا غیرضروري موادو د تجزیې په پروسو کې مهم رول لري.</p>
<p>پکې مختلف <strong>Digestive Enzymes</strong> موجود وي.</p>
<p>په ساده مثال:</p>
<blockquote>
<p>Lysosome د حجرې د "recycling and waste-processing system" یوه برخه ده.</p>
</blockquote>
<p>خو دا تشبیه یوازې د زده‌کړې لپاره ده؛ Lysosome له یوې عادي کثافاتو دانۍ څخه ډېر پیچلی جوړښت دی.</p>
<hr>
<h1>۲۴. Peroxisomes — پېروکسیزومونه</h1><h3 dir="rtl">
</h3><p><strong>Peroxisomes</strong> د ځینو fatty acids د تجزیې او د Reactive Oxygen Species د مدیریت په پروسو کې رول لري.</p>
<p>په دې کې مهم انزایمونه شامل وي.</p>
<p>د مثال په توګه:</p>
<p><strong>Catalase</strong></p>
<p>د Hydrogen Peroxide په تجزیه کې مهم رول لري.</p>
<hr>
<h1>۲۵. Cytoskeleton — سایټوسکېلېټن</h1><h3 dir="rtl">
</h3><p><strong>Cytoskeleton</strong> د حجرې داخلي پروټیني شبکه ده.</p>
<p>دا د حجرې لپاره:</p>
<ul>
<li>
Shape
</li>
<li>
Internal organization
</li>
<li>
Movement
</li>
<li>
Intracellular transport
</li>
</ul>
<p>کې مهم رول لري.</p>
<p>درې مهم ډولونه یې:</p>
<ul>
<li>
Microfilaments
</li>
<li>
Intermediate Filaments
</li>
<li>
Microtubules
</li>
</ul>
<hr>
<h1>۲۶. Centrioles / Centrosome</h1><h3 dir="rtl">
</h3><p><strong>Centrosome</strong> د حجروي تنظیم یوه مهمه سیمه ده چې د Microtubules په تنظیم کې مهم رول لري.</p>
<p>په Animal Cells کې د Cell Division پر مهال د Chromosomes د تنظیم او وېش په پروسو کې مهم رول لري.</p>
<p>د دې موضوع ژوره برخه به د <strong>Cell Division</strong> په درس کې زده کړو.</p>
<hr>
<h1>۲۷. د حجرې مهم Organelles په یوه جدول کې</h1><h3 dir="rtl">
<div><div><table><thead><tr><th>Organelle</th><th>اصلي دنده</th></tr></thead><tbody><tr><td>Nucleus</td><td>DNA او جنیټیک معلومات</td></tr><tr><td>Nucleolus</td><td>د Ribosome-related components جوړول</td></tr><tr><td>Mitochondria</td><td>د حجروي انرژۍ تولید</td></tr><tr><td>Ribosome</td><td>Protein synthesis</td></tr><tr><td>Rough ER</td><td>Protein synthesis/processing</td></tr><tr><td>Smooth ER</td><td>Lipid synthesis, detoxification او نور</td></tr><tr><td>Golgi Apparatus</td><td>Modification, sorting, packaging</td></tr><tr><td>Lysosome</td><td>د ځینو موادو تجزیه</td></tr><tr><td>Peroxisome</td><td>Fatty acid metabolism او oxidative processes</td></tr><tr><td>Cytoskeleton</td><td>Shape, support, movement, transport</td></tr><tr><td>Centrosome</td><td>Microtubule organization</td></tr></tbody></table></div></div>
<hr>
</h3><h1>۲۸. یوه مهمه اړیکه: Organelles یو ځای کار کوي</h1><h3 dir="rtl">
</h3><p>د حجرې برخې جلا جلا ماشینونه نه دي.</p>
<p>دوی یو له بل سره همکاري کوي.</p>
<p>مثلاً د یوه پروټین د جوړېدو لپاره:</p>
<p><strong>Nucleus</strong></p>
<p>↓</p>
<p>Genetic information</p>
<p>↓</p>
<p><strong>Ribosome</strong></p>
<p>↓</p>
<p>Protein synthesis</p>
<p>↓</p>
<p><strong>Rough ER</strong></p>
<p>↓</p>
<p>Processing/transport</p>
<p>↓</p>
<p><strong>Golgi Apparatus</strong></p>
<p>↓</p>
<p>Sorting/packaging</p>
<p>↓</p>
<p>Target destination</p>
<p>دا د حجرې د داخلي همغږۍ یوه مهمه بېلګه ده.</p>
<hr>
<h1>۲۹. کلینیکي سناریو ۱ — د عضلاتو حجره</h1><h3 dir="rtl">
</h3><p>فرض کړئ یوه ښځه د ولادت پر مهال د رحم د عضلاتو قوي contractions لري.</p>
<p>د عضلاتو حجرې د contraction لپاره انرژۍ ته اړتیا لري.</p>
<p>پوښتنه:</p>
<blockquote>
<p>کوم Organelle د ATP په تولید کې مهم رول لري؟</p>
</blockquote>
<p><strong>ځواب: Mitochondria</strong></p>
<h3>مهم درس</h3><h3 dir="rtl">
</h3><p>د عضلاتو فعالیت یوازې د عضلې په کچه نه دی؛ د عضلې دننه حجرې او د هغوی Organelles هم د دې فعالیت لپاره ضروري دي.</p>
<hr>
<h1>۳۰. کلینیکي سناریو ۲ — د پروټین جوړېدل</h1><h3 dir="rtl">
</h3><p>فرض کړئ یوه حجره باید یو ځانګړی پروټین جوړ کړي.</p>
<p>پوښتنه:</p>
<blockquote>
<p>د Protein synthesis لپاره کوم جوړښت مهم دی؟</p>
</blockquote>
<p><strong>Ribosome</strong></p>
<p>که پروټین د حجرې د secretion یا membrane system لپاره وي، Rough ER او Golgi Apparatus هم مهم رول لري.</p>
<h3>مهم درس</h3><h3 dir="rtl">
</h3><p><strong>Ribosome → Protein synthesis</strong></p>
<hr>
<h1>۳۱. کلینیکي سناریو ۳ — د جنیټیک معلوماتو ځای</h1><h3 dir="rtl">
</h3><p>که یوه زده‌کوونکې وپوښتي:</p>
<blockquote>
<p>د حجرې جنیټیک معلومات په کوم ځای کې ساتل کېږي؟</p>
</blockquote>
<p>د ډېرو انساني حجرو لپاره:</p>
<p><strong>Nucleus → DNA</strong></p>
<h3>مهم درس</h3><h3 dir="rtl">
</h3><p>Nucleus د حجرې د جنیټیک معلوماتو مهم مرکز دی.</p>
<hr>
<h1>۳۲. کلینیکي سناریو ۴ — د حجرې غشا</h1><h3 dir="rtl">
</h3><p>یوه حجره باید د خپل چاپېریال سره مواد تبادله کړي.</p>
<p>پوښتنه:</p>
<blockquote>
<p>کوم جوړښت د موادو د داخلېدو او وتلو په تنظیم کې مهم دی؟</p>
</blockquote>
<p><strong>Cell Membrane</strong></p>
<h3>مهم درس</h3><h3 dir="rtl">
</h3><p>Cell Membrane یو <strong>Selective Barrier</strong> دی.</p>
<hr>
<h1>۳۳. کلینیکي سناریو ۵ — د حجرو زړې برخې</h1><h3 dir="rtl">
</h3><p>فرض کړئ د حجرې ځینې زاړه یا غیرضروري مواد باید تجزیه شي.</p>
<p>کوم Organelle مهم رول لري؟</p>
<p><strong>Lysosome</strong></p>
<h3>مهم درس</h3><h3 dir="rtl">
</h3><p>Lysosomes د حجروي تجزیې او recycling په پروسو کې مهم دي.</p>
<hr>
<h1>۳۴. د حجرې او قابلګۍ اړیکه</h1><h3 dir="rtl">
</h3><p>کېدای شي په لومړي نظر داسې ښکاره شي چې Cell Biology د قابلګۍ سره مستقیمه اړیکه نه لري.</p>
<p>خو حقیقت برعکس دی.</p>
<p>قابله باید د لاندې موضوعاتو د پوهېدو لپاره د حجرې بنسټیزه پوهه ولري:</p>
<ul>
<li>
Pregnancy
</li>
<li>
Fetal development
</li>
<li>
Placenta
</li>
<li>
Maternal tissues
</li>
<li>
Hormonal responses
</li>
<li>
Blood cells
</li>
<li>
Muscle contraction
</li>
<li>
Wound healing
</li>
<li>
Infection
</li>
<li>
Genetics
</li>
<li>
Reproductive cells
</li>
</ul>
<p>مثلاً:</p>
<p><strong>Fertilization → Cell division → Embryonic development → Fetal development</strong></p>
<p>نو د جنین د ودې د پوهېدو لپاره د حجرې بنسټیزه پوهه ډېره مهمه ده.</p>
<hr>
<h1>۳۵. د جنین د ودې سره اړیکه</h1><h3 dir="rtl">
</h3><p>د نوي انسان ژوند د یوې حجرې له یوځای کېدو څخه د <strong>zygote</strong> په جوړېدو سره پیل کېږي.</p>
<p>وروسته:</p>
<p><strong>Zygote</strong></p>
<p>↓</p>
<p>Cell Division</p>
<p>↓</p>
<p>More Cells</p>
<p>↓</p>
<p>Differentiation</p>
<p>↓</p>
<p>Tissues</p>
<p>↓</p>
<p>Organs</p>
<p>↓</p>
<p>Organ Systems</p>
<p>↓</p>
<p>Developing Human</p>
<p>دا به په راتلونکو درسونو کې په ډېر تفصیل سره زده کړو.</p>
<hr>
<h1>۳۶. د حجرې د زده‌کړې طلایي فورمول</h1><h3 dir="rtl">
</h3><p>دا ترتیب زده کړئ:</p>
<blockquote>
<p><strong>Membrane → Cytoplasm → Organelles → Nucleus → DNA</strong></p>
</blockquote>
<p>او د مهمو Organelles لپاره:</p>
<blockquote>
<p><strong>Mitochondria → Energy</strong></p>
</blockquote>
<blockquote>
<p><strong>Ribosome → Protein</strong></p>
</blockquote>
<blockquote>
<p><strong>Golgi → Modify/Sort/Package</strong></p>
</blockquote>
<blockquote>
<p><strong>Lysosome → Breakdown</strong></p>
</blockquote>
<blockquote>
<p><strong>ER → Synthesis/Processing/Transport</strong></p>
</blockquote>
<blockquote>
<p><strong>Nucleus → DNA</strong></p>
</blockquote>
<hr>
<h1>۳۷. عامې غلط فهمۍ</h1><h3>غلط فهمي ۱</h3><h3 dir="rtl">

</h3><p>"ټولې حجرې Nucleus لري."</p>
<p>❌ ناسم.</p>
<p>د انسان Mature Red Blood Cells هسته نه لري.</p>
<hr>
<h3>غلط فهمي ۲</h3><h3 dir="rtl">
</h3><p>"Mitochondria یوازې د انرژۍ لپاره دي."</p>
<p>دا د زده‌کړې لپاره مهمه اصلي دنده ده، خو Mitochondria نورې مهمې حجروي او میتابولیکې دندې هم لري.</p>
<hr>
<h3>غلط فهمي ۳</h3><h3 dir="rtl">
</h3><p>"Ribosome یو membrane-bound organelle دی."</p>
<p>❌ Ribosomes د membrane-bound organelles په ډله کې نه راځي.</p>
<hr>
<h3>غلط فهمي ۴</h3><h3 dir="rtl">
</h3><p>"Cell Membrane یوازې یو پوښ دی."</p>
<p>❌ نه.</p>
<p>دا یو فعال او انتخابي barrier دی چې په انتقال، ارتباط او حجروي تنظیم کې رول لري.</p>
<hr>
<h1>۳۸. Individual Online Activity</h1><h3 dir="rtl">
</h3><p>ستاسو د Online Midwifery LMS لپاره د ټولګي د Group Activity پر ځای دا انفرادي فعالیت مناسب دی:</p>
<h2>Activity: Build the Cell</h2><h3 dir="rtl">
</h3><p>زده‌کوونکې به د Drag-and-Drop یا Matching له لارې لاندې اړیکې جوړوي:</p>
