(359, 33, 'لمفاوي او معافیتي سیسټم', '<p dir="rtl" style="text-align:right">لمفاوي سیسټم اضافي مایع راټولوي او د بدن دفاع کې برخه اخلي.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>د لمفاوي سیسټم برخې ونومئ.</li><li>د لمف غوټیو دنده بیان کړئ.</li><li>فطري او اکتسابي معافیت توپیر کړئ.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">لمفاوي سیسټم اضافي مایع راټولوي او د بدن دفاع کې برخه اخلي.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>لمفاوي رګونه، غوټۍ، طحال او تیموس اصلي برخې دي.</li><li>لمف غوټۍ مکروبونه فلټر کوي.</li><li>فطري معافیت زیږیدلی دی — پوستکی، مخاط، سپینې حجرې.</li><li>اکتسابي معافیت له انتان یا واکسین وروسته جوړیږي.</li><li>انټي باډي د B لمفوسایټونو له خوا جوړیږي.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>لمف</td><td dir="ltr" style="text-align:left">Lymph</td></tr><tr><td>انټي باډي</td><td dir="ltr" style="text-align:left">Antibody</td></tr><tr><td>لمفوسایټ</td><td dir="ltr" style="text-align:left">Lymphocyte</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>د مور انټي باډي د مشیمې له لارې ماشوم ته لیږدول کیږي او لومړیو میاشتو کې یې ساتي — همدا د تي روږدي کولو یو ګټه ده.</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'none', NULL, NULL, 30, 'core', 79, TRUE, 32, TRUE, '2026-09-13 04:39:29'),
(360, 33, 'تنفسي سیسټم', '<p dir="rtl" style="text-align:right">تنفسي سیسټم اکسیجن راوړي او کاربن ډای اکساید باسي.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>د تنفسي لارې برخې ونومئ.</li><li>د الویولي دنده بیان کړئ.</li><li>پورتنۍ او ښکتنۍ لار توپیر کړئ.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">تنفسي سیسټم اکسیجن راوړي او کاربن ډای اکساید باسي.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>پورتنۍ لار: پزه، فارنکس، لارنکس.</li><li>ښکتنۍ لار: ټراکیا، برونکس، برونکیول، الویولي.</li><li>الویولي هغه ځای دی چې ګاز تبادله پکې کیږي.</li><li>سږي په پلورل پردو کې تړل شوي دي.</li><li>د ښي سږي درې لوبونه او کیڼ دوه لري.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>الویولي</td><td dir="ltr" style="text-align:left">Alveoli</td></tr><tr><td>ټراکیا</td><td dir="ltr" style="text-align:left">Trachea</td></tr><tr><td>پلورا</td><td dir="ltr" style="text-align:left">Pleura</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>د نوي زیږیدلي ماشوم لومړی ساه اخیستل الویولي پرانیزي — همدا لامل دی چې «د طلایي دقیقې» مفهوم دومره مهم دی.</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'url', 'https://www.youtube.com/watch?v=0fVoz4V75_E', NULL, 34, 'advanced', 81, TRUE, 33, TRUE, '2026-09-13 04:39:29'),
(361, 33, 'د تنفس میخانیک او ګاز تبادله', '<p dir="rtl" style="text-align:right">ساه اخیستل او ایستل د فشار د توپیر له مخې ترسره کیږي.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>د دیافراګم رول بیان کړئ.</li><li>انسپیریشن او اکسپیریشن توپیر کړئ.</li><li>د ګاز تبادله تشریح کړئ.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">ساه اخیستل او ایستل د فشار د توپیر له مخې ترسره کیږي.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>کله چې دیافراګم ښکته شي، د سینې حجم زیاتیږي او هوا دننه راځي.</li><li>ساه ایستل معمولاً غیر فعال دي.</li><li>اکسیجن له الویولي څخه وینې ته او CO2 برعکس ځي.</li><li>د تنفس شمیر په بالغ کې ۱۲–۲۰ په دقیقه کې دی.</li><li>د نوي زیږیدلي تنفس ۳۰–۶۰ په دقیقه کې نورمال دی.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>دیافراګم</td><td dir="ltr" style="text-align:left">Diaphragm</td></tr><tr><td>انسپیریشن</td><td dir="ltr" style="text-align:left">Inspiration</td></tr><tr><td>ګاز تبادله</td><td dir="ltr" style="text-align:left">Gas exchange</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>د امیندوارۍ پر مهال رحم پر دیافراګم فشار راوړي او مور د ساه لنډوالی احساسوي — دا معمولاً نورمال دي.</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'url', 'https://www.youtube.com/watch?v=bHZsvBdUC2I', NULL, 32, 'advanced', 84, TRUE, 34, TRUE, '2026-09-13 04:39:29'),
(362, 33, 'هاضمي سیسټم', '<p dir="rtl" style="text-align:right">هاضمي سیسټم خواړه ماتوي او تغذیه جذبوي.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>د هاضمې لار برخې ونومئ.</li><li>د هضم پروسه بیان کړئ.</li><li>د جذب ځای وپیژنئ.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">هاضمي سیسټم خواړه ماتوي او تغذیه جذبوي.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>لار: خوله ← مري ← معده ← نری کولمه ← پنډه کولمه.</li><li>مرستندویه غړي: ځیګر، پانقراس، صفرا کڅوړه.</li><li>ډیره برخه جذب په نري کولمه کې کیږي.</li><li>پانقراس انزایمونه او انسولین جوړوي.</li><li>ځیګر صفرا جوړوي چې غوړي ماتوي.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>معده</td><td dir="ltr" style="text-align:left">Stomach</td></tr><tr><td>نری کولمه</td><td dir="ltr" style="text-align:left">Small intestine</td></tr><tr><td>ځیګر</td><td dir="ltr" style="text-align:left">Liver</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>د امیندوارۍ پر مهال د پروجسټرون له امله د کولمو حرکت ورو کیږي — نو قبضیت او د زړه سوځیدل عام دي.</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'url', 'https://www.youtube.com/watch?v=yIoTRGfcMqM', NULL, 32, 'advanced', 86, TRUE, 35, TRUE, '2026-09-13 04:39:29'),
(363, 33, 'ادراري سیسټم', '<p dir="rtl" style="text-align:right">ادراري سیسټم وینه پاکوي او د بدن مایعات تنظیموي.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>د ادراري سیسټم برخې ونومئ.</li><li>د نفرون دنده بیان کړئ.</li><li>د ادرار جوړیدل تشریح کړئ.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">ادراري سیسټم وینه پاکوي او د بدن مایعات تنظیموي.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>برخې: دوه پښتورګي، دوه یوریټر، مثانه، یوریترا.</li><li>نفرون د پښتورګي فعال واحد دی — هر پښتورګی ~۱ ملیون لري.</li><li>درې پړاوونه: فلتریشن، ریابزارپشن، سیکریشن.</li><li>پښتورګي د وینې فشار او د وینې حجرو جوړونه هم اغیزمنوي.</li><li>نورمال ادرار په ورځ کې ۱–۲ لیټره دی.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>پښتورګی</td><td dir="ltr" style="text-align:left">Kidney</td></tr><tr><td>نفرون</td><td dir="ltr" style="text-align:left">Nephron</td></tr><tr><td>مثانه</td><td dir="ltr" style="text-align:left">Bladder</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>د امیندوارۍ پر مهال د ادرار لارې انتان (UTI) ډیر عام دی او که درملنه نشي، مخکې له وخته زیږون رامنځته کولی شي.</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'url', 'https://www.youtube.com/watch?v=l128tW1H5a8', NULL, 32, 'advanced', 89, TRUE, 36, TRUE, '2026-09-13 04:39:29'),
(364, 33, 'عصبي سیسټم', '<p dir="rtl" style="text-align:right">عصبي سیسټم د بدن ټول فعالیتونه کنټرولوي او همغږي کوي.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>مرکزي او محیطي عصبي سیسټم توپیر کړئ.</li><li>د اتونومیک سیسټم دوه څانګې ونومئ.</li><li>د رفلکس قوس بیان کړئ.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">عصبي سیسټم د بدن ټول فعالیتونه کنټرولوي او همغږي کوي.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>مرکزي عصبي سیسټم: دماغ او نخاع.</li><li>محیطي عصبي سیسټم: عصبونه چې له مرکز څخه وځي.</li><li>اتونومیک سیسټم: سمپاتیک (جګړه/تیښته) او پاراسمپاتیک (ارام).</li><li>رفلکس یو چټک، غیر ارادي غبرګون دی.</li><li>د نخاع زیان کیدای شي د احساس او حرکت له لاسه ورکول رامنځته کړي.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>نخاع</td><td dir="ltr" style="text-align:left">Spinal cord</td></tr><tr><td>سمپاتیک</td><td dir="ltr" style="text-align:left">Sympathetic</td></tr><tr><td>رفلکس</td><td dir="ltr" style="text-align:left">Reflex</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>د اپیډورل بې حسۍ پر مهال درمل د نخاع شاوخوا فضا ته ورکول کیږي او د لګن احساس کموي.</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'none', NULL, NULL, 34, 'advanced', 91, TRUE, 37, TRUE, '2026-09-13 04:39:29'),
(365, 33, 'اندوکراین سیسټم او هورمونونه', '<p dir="rtl" style="text-align:right">هورمونونه کیمیاوي پیغام رسوونکي دي چې د وینې له لارې کار کوي.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>اصلي اندوکراین غدې ونومئ.</li><li>د هورمون د کار لاره بیان کړئ.</li><li>د تناسلي هورمونونو رول وواياست.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">هورمونونه کیمیاوي پیغام رسوونکي دي چې د وینې له لارې کار کوي.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>اصلي غدې: هایپوتالاموس، پیټیوټري، تایرویډ، ادرینل، پانقراس، تخمدان.</li><li>پیټیوټري «د غدو مشر» ګڼل کیږي.</li><li>FSH او LH د میاشتنۍ دورې کنټرول کوي.</li><li>اوکسیتوسین د رحم انقباض او د شیدو خوشې کول رامنځته کوي.</li><li>پرولاکتین د شیدو جوړول تحریکوي.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>پیټیوټري</td><td dir="ltr" style="text-align:left">Pituitary</td></tr><tr><td>اوکسیتوسین</td><td dir="ltr" style="text-align:left">Oxytocin</td></tr><tr><td>پرولاکتین</td><td dir="ltr" style="text-align:left">Prolactin</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>اوکسیتوسین هغه هورمون دی چې په مامایي کې تر ټولو ډیر کارول کیږي — د زیږون د تحریک او د وینې د بندولو لپاره.</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'url', 'https://www.youtube.com/watch?v=eWHH9je2zG4', NULL, 36, 'advanced', 94, TRUE, 38, TRUE, '2026-09-13 04:39:29'),
(366, 33, 'د ښځینه تناسلي سیسټم', '<p dir="rtl" style="text-align:right">د ښځینه تناسلي سیسټم پیژندل د مامایي د ټولې زده کړې زړه دی.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>بهرني او دننني تناسلي غړي ونومئ.</li><li>د رحم پرتونه بیان کړئ.</li><li>د تخمدان دنده وواياست.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">د ښځینه تناسلي سیسټم پیژندل د مامایي د ټولې زده کړې زړه دی.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>بهرني غړي (vulva): لابیا ماجورا، لابیا مینورا، کلایتوریس.</li><li>دننني غړي: مهبل، رحم، فالوپي نلۍ، تخمدانونه.</li><li>د رحم درې پرتونه: پیریمټریم، مایومټریم، اندومټریم.</li><li>رحم د امیندوارۍ پر مهال له ~۷ سم څخه تر ~۳۵ سم پورې لویږي.</li><li>تخمدانونه تخمې او هورمونونه (استروجن، پروجسټرون) جوړوي.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>رحم</td><td dir="ltr" style="text-align:left">Uterus</td></tr><tr><td>اندومټریم</td><td dir="ltr" style="text-align:left">Endometrium</td></tr><tr><td>فالوپي نلۍ</td><td dir="ltr" style="text-align:left">Fallopian tube</td></tr><tr><td>تخمدان</td><td dir="ltr" style="text-align:left">Ovary</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>د اندومټریم پرت هغه ځای دی چې القاح شوې تخمه پکې ځای نیسي — د امیندوارۍ لومړی ګام.</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'url', 'https://www.youtube.com/watch?v=2_owp8kNMus', NULL, 40, 'advanced', 96, TRUE, 39, TRUE, '2026-09-13 04:39:29'),
(367, 33, 'میاشتنۍ دوره', '<p dir="rtl" style="text-align:right">میاشتنۍ دوره هغه منظمه پروسه ده چې بدن یې د امیندوارۍ لپاره چمتو کوي.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>د دورې پړاوونه ونومئ.</li><li>د هورمونونو بدلونونه بیان کړئ.</li><li>د تخمک ایستلو وخت وټاکئ.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">میاشتنۍ دوره هغه منظمه پروسه ده چې بدن یې د امیندوارۍ لپاره چمتو کوي.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>اوسط دوره ۲۸ ورځې ده، خو ۲۱–۳۵ ورځې نورمال دي.</li><li>د تخمدان پړاوونه: فولیکولر، اوولیشن، لوټیل.</li><li>د رحم پړاوونه: میاشتنۍ، پرولیفراټیو، سیکریټري.</li><li>اوولیشن معمولاً د راتلونکې میاشتنۍ ۱۴ ورځې مخکې کیږي.</li><li>که القاح ونشي، د پروجسټرون کمښت میاشتنۍ راولي.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>اوولیشن</td><td dir="ltr" style="text-align:left">Ovulation</td></tr><tr><td>فولیکل</td><td dir="ltr" style="text-align:left">Follicle</td></tr><tr><td>کورپوس لوټیم</td><td dir="ltr" style="text-align:left">Corpus luteum</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>د وروستۍ میاشتنۍ لومړۍ ورځ (LMP) هغه معلومات دي چې د زیږون اټکل شوې نیټه (EDD) ترې محاسبه کیږي.</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'url', 'https://www.youtube.com/watch?v=CwgaFwHJM4g', NULL, 38, 'advanced', 99, TRUE, 40, TRUE, '2026-09-13 04:39:29'),
(368, 34, 'قابلګي څه ده؟ — تعریف او فلسفه', '<p><br></p>', '<h3 dir="rtl" style="text-align:right"></h3><p>درس: قابلګي څه ده؟</p><h2>تعریف، فلسفه او د قابلې مسلکي رول</h2><h3>Midwifery: Definition, Philosophy and Professional Role</h3><h3 dir="rtl"><hr></h3><h1>۱. د درس عمومي پېژندنه</h1><h3 dir="rtl"></h3><p>کله چې موږ د <strong>Midwifery (قابلګۍ)</strong> نوم اورو، ډېر خلک سمدستي فکر کوي:</p><blockquote><p>"قابله هغه څوک ده چې د ماشوم په زېږون کې مرسته کوي."</p></blockquote><p>دا خبره <strong>سمه ده، خو بشپړه نه ده.</strong></p><p>قابلګي یوازې د ماشوم د زېږولو مرسته نه ده.</p><p>قابلګي د ښځې د ژوند له مهمو پړاوونو سره تړلې یوه مسلکي روغتیايي رشته ده، چې د ښځې د:</p><ul><li><p>امیندوارۍ (Pregnancy)</p></li><li><p>زېږون (Childbirth/Labour)</p></li><li><p>له زېږون وروسته دوره (Postpartum/Postnatal Period)</p></li><li><p>د نوي زېږېدلي ماشوم (Newborn)</p></li><li><p>د مور او ماشوم روغتیا</p></li><li><p>د ښځینه تولیدي او جنسي روغتیا</p></li><li><p>روغتیايي زده‌کړې</p></li><li><p>مشورې او ملاتړ</p></li></ul><p>په برخه کې مهم رول لري.</p><p>نو د دې درس اساسي پوښتنه دا ده:</p><blockquote><p><strong>قابلګي په اصل کې څه ده؟</strong></p></blockquote><hr><h1>۲. Midwifery څه معنی لري؟</h1><h3 dir="rtl"></h3><p><strong>Midwifery</strong> د انګلیسي ژبې یوه مسلکي اصطلاح ده.</p><p>په پښتو کې ورته:</p><blockquote><p><strong>قابلګي</strong></p></blockquote><p>ویل کېږي.</p><p><strong>Midwife</strong>:</p><blockquote><p><strong>قابله</strong></p></blockquote><p>ده.</p><p>قابله هغه روزل شوې او مسلکي روغتیايي کارکوونکې ده چې د ښځو د تولیدي روغتیا، امیندوارۍ، زېږون، له زېږون وروسته پاملرنې او د نوي زېږېدلي ماشوم په برخه کې د خپل مسلکي صلاحیت په حدودو کې پاملرنه وړاندې کوي.</p><hr><h1>۳. د قابلګۍ ساده تعریف</h1><h3 dir="rtl"></h3><p>د زده‌کوونکې لپاره یې په ساده ډول داسې یادولای شو:</p><blockquote><p><strong>قابلګي د ښځو، میندو او نوي زېږېدلو ماشومانو لپاره د شواهدو پر بنسټ، درناوي وړ، مسلکي او دوامداره روغتیايي پاملرنه ده، چې د امیندوارۍ، زېږون، له زېږون وروسته دورې او د ښځې د تولیدي روغتیا په بېلابېلو پړاوونو کې وړاندې کېږي.</strong></p></blockquote><p>په دې تعریف کې څو مهمې کلمې دي:</p><ul><li><p>ښځه</p></li><li><p>مور</p></li><li><p>نوي زېږېدلی ماشوم</p></li><li><p>روغتیا</p></li><li><p>امیندوارۍ</p></li><li><p>زېږون</p></li><li><p>له زېږون وروسته پاملرنه</p></li><li><p>مسلکي پاملرنه</p></li><li><p>شواهد</p></li><li><p>درناوی</p></li></ul><p>هره یوه به تشریح کړو.</p><hr><h1>۴. قابلګي یوازې د زېږون مرسته نه ده</h1><h3 dir="rtl"></h3><p>راځئ یو مثال وګورو.</p><p>یوه ښځه چې امیندواره شوې، د روغتیايي مرکز ته راځي.</p><p>ایا قابله یوازې هغه وخت ورته اړتیا لري چې د زېږون دردونه پیل شي؟</p><p><strong>نه.</strong></p><p>قابله کولی شي د امیندوارۍ په جریان کې:</p><ul><li><p>د مور روغتیا ارزونه وکړي.</p></li><li><p>د امیندوارۍ پرمختګ وڅاري.</p></li><li><p>روغتیايي مشوره ورکړي.</p></li><li><p>د تغذیې په اړه معلومات ورکړي.</p></li><li><p>د خطر نښې وپېژني.</p></li><li><p>اړینې معاینې او خدمات تنظیم یا ترسره کړي، د خپل مسلکي صلاحیت له مخې.</p></li><li><p>د زېږون لپاره د مور چمتووالی پیاوړی کړي.</p></li><li><p>د مور رواني او ټولنیزې اړتیاوې هم په پام کې ونیسي.</p></li></ul><p>نو:</p><blockquote><p><strong>Midwifery starts before labour.</strong></p></blockquote><hr><h1>۵. د قابلګۍ د پاملرنې مهم پړاوونه</h1><h3 dir="rtl"></h3><p>د قابلګۍ د کار یوه مهمه برخه د ښځې د روغتیا د مختلفو پړاوونو پاملرنه ده.</p><h3>۱. د امیندوارۍ پاملرنه</h3><h3 dir="rtl"></h3><p><strong>Antenatal Care (ANC)</strong></p><h3>۲. د زېږون پاملرنه</h3><h3 dir="rtl"></h3><p><strong>Labour and Birth Care</strong></p><h3>۳. له زېږون وروسته پاملرنه</h3><h3 dir="rtl"></h3><p><strong>Postnatal Care (PNC)</strong></p><h3>۴. د نوي زېږېدلي ماشوم پاملرنه</h3><h3 dir="rtl"></h3><p><strong>Newborn Care</strong></p><h3>۵. د تولیدي روغتیا پاملرنه</h3><h3 dir="rtl"></h3><p><strong>Reproductive Health</strong></p><h3>۶. روغتیايي زده‌کړه او مشوره</h3><h3 dir="rtl"></h3><p><strong>Health Education and Counselling</strong></p><hr><h1>۶. د قابلګۍ فلسفه څه ده؟</h1><h3 dir="rtl"></h3><p>اوس د درس تر ټولو مهمې برخې ته راځو:</p><h2>Philosophy of Midwifery</h2><h3 dir="rtl"></h3><p><strong>د قابلګۍ فلسفه</strong> هغه بنسټیز فکرونه، ارزښتونه او اصول دي چې تشریح کوي:</p><blockquote><p>قابله ښځې ته څنګه ګوري، روغتیا څنګه تعریفوي، د مور او ماشوم پاملرنه څنګه کوي، او د خپل مسلک هدف څه ګڼي.</p></blockquote><p>په ساده ژبه:</p><blockquote><p><strong>فلسفه موږ ته وایي چې قابله څنګه فکر کوي.</strong></p></blockquote><hr><h1>۷. د قابلګۍ فلسفه: ښځه یوازې "ناروغه" نه ده</h1><h3 dir="rtl"></h3><p>د قابلګۍ یو مهم اصل دا دی چې:</p><blockquote><p><strong>Pregnancy is not automatically a disease.</strong></p></blockquote><p>یعنې:</p><blockquote><p>امیندوارۍ په خپله ناروغي نه ده.</p></blockquote><p>امیندوارۍ د ښځې د بدن یو طبیعي فزیولوژیک حالت دی.</p><p>خو دا هم مهمه ده چې:</p><blockquote><p>طبیعي حالت د خطر د نشتوالي معنا نه لري.</p></blockquote><p>ځینې امیندوارۍ او زېږونونه له پیچلتیاوو سره مخ کېدای شي.</p><p>نو قابله باید:</p><p><strong>Normal + Risk Recognition</strong></p><p>دواړه درک کړي.</p><hr><h1>۸. Normal Pregnancy څه معنی لري؟</h1><h3 dir="rtl"></h3><p>کله چې موږ وایو:</p><p><strong>Normal Pregnancy</strong></p><p>هدف دا نه دی چې:</p><blockquote><p>"په امیندوارۍ کې هېڅ خطر نشته."</p></blockquote><p>بلکې هدف دا دی چې امیندوارۍ د ښځې د بدن یوه طبیعي فزیولوژیک پروسه ده چې په ډېرو ښځو کې د مناسبې څارنې سره عادي پرمختګ کوي.</p><p>خو قابله باید تل د خطر نښې وپېژني.</p><hr><h1>۹. Woman-Centred Care</h1><h3 dir="rtl"></h3><p>د قابلګۍ یو مهم اصل:</p><h2>Woman-Centred Care</h2><h3 dir="rtl"></h3><p>یعنې:</p><blockquote><p><strong>د ښځې پر اړتیاوو، ارزښتونو، انتخابونو او درناوي تمرکز.</strong></p></blockquote><p>قابله باید یوازې د ناروغۍ یا د جنین په اړه فکر ونه کړي.</p><p>باید ښځه هم د پاملرنې د مرکز په توګه وویني.</p><p>مثلاً:</p><p>یوه امیندواره ښځه اندېښمنه ده.</p><p>قابله یوازې دا نه وایي:</p><blockquote><p>"فشار دې څو دی؟"</p></blockquote><p>بلکې باید د ښځې اندېښنه هم واوري.</p><hr><h1>۱۰. Respectful Maternity Care</h1><h2>Respectful Maternity Care — درناوی لرونکې د میندو پاملرنه</h2><h3 dir="rtl"></h3><p>هره ښځه حق لري چې:</p><ul><li><p>په درناوي ورسره چلند وشي.</p></li><li><p>سپکاوی ورسره ونه شي.</p></li><li><p>د هغې شخصي حریم وساتل شي.</p></li><li><p>د هغې معلومات محرم وساتل شي.</p></li><li><p>د امکان تر حده په پرېکړو کې یې نظر واخیستل شي.</p></li><li><p>د هغې پوښتنو ته واضح ځواب ورکړل شي.</p></li><li><p>له زور، وېرولو او غیرضروري سپکاوي څخه خوندي وي.</p></li></ul><p>دا د قابلګۍ د مسلکي اخلاقو یوه مهمه برخه ده.</p><hr><h1>۱۱. د ښځې د خبرو اورېدل</h1><h3 dir="rtl"></h3><p>یوه ښه قابله یوازې ښه معاینه کوونکې نه ده.</p><p>هغه باید:</p><blockquote><p><strong>Good Listener</strong></p></blockquote><p>هم وي.</p><p>مثلاً یوه ښځه وایي:</p><blockquote><p>"زه د خپل زېږون څخه ډېره وېرېږم."</p></blockquote><p>قابله باید سمدستي ووایي:</p><blockquote><p>"مه وېرېږه، هېڅ ستونزه نشته."</p></blockquote><p>دا تل مناسبه مسلکي اړیکه نه ده.</p><p>ښه طریقه دا ده چې:</p><ul><li><p>د هغې اندېښنه واوري.</p></li><li><p>پوښتنه وکړي چې له څه شي وېرېږي.</p></li><li><p>سم معلومات ورکړي.</p></li><li><p>د امکان تر حده یې ډاډمنه کړي.</p></li><li><p>که خطر موجود وي، مناسبه ارزونه او referral ترسره کړي.</p></li></ul><hr><h1>۱۲. Holistic Care — هر اړخیزه پاملرنه</h1><h3 dir="rtl"></h3><p><strong>Holistic Care</strong> د قابلګۍ په مهمو مفاهیمو کې ده.</p><p>یعنې ښځه یوازې د بدن له نظره نه ارزول کېږي.</p><p>قابله د ښځې لاندې اړخونه هم په پام کې نیسي:</p><h3>Physical</h3><h3 dir="rtl"></h3><p>فزیکي روغتیا</p><h3>Emotional</h3><h3 dir="rtl"></h3><p>احساساتي حالت</p><h3>Psychological</h3><h3 dir="rtl"></h3><p>رواني وضعیت</p><h3>Social</h3><h3 dir="rtl"></h3><p>ټولنیز وضعیت</p><h3>Cultural</h3><h3 dir="rtl"></h3><p>کلتوري اړتیاوې</p><h3>Educational</h3><h3 dir="rtl"></h3><p>د روغتیايي معلوماتو اړتیا</p><hr><h1>۱۳. یو عملي مثال</h1><h3 dir="rtl"></h3><p>یوه امیندواره ښځه د روغتیايي مرکز ته راځي.</p><p>فزیکي معاینه یې عادي ده.</p><p>خو وایي:</p><blockquote><p>"په کور کې ډېر فشار لرم او د امیندوارۍ په اړه اندېښمنه یم."</p></blockquote><p>که قابله یوازې فزیکي معاینه وکړي او لاړه شي، نو د ښځې یوه مهمه اړتیا له پامه غورځول شوې.</p><p><strong>Holistic Midwifery Care</strong> هڅه کوي چې د ښځې روغتیا په پراخ ډول وګوري.</p><hr><h1>۱۴. Mother and Baby — مور او ماشوم</h1><h3 dir="rtl"></h3><p>قابلګي د مور او ماشوم دواړو ته پاملرنه کوي.</p><p>خو یو مهم اصل دا دی:</p><blockquote><p><strong>The woman is not just a carrier of the baby.</strong></p></blockquote><p>یعنې ښځه یوازې د جنین د انتقال وسیله نه ده.</p><p>هغه خپله:</p><ul><li><p>حقوق لري.</p></li><li><p>اړتیاوې لري.</p></li><li><p>احساسات لري.</p></li><li><p>انتخابونه لري.</p></li><li><p>روغتیايي اړتیاوې لري.</p></li></ul><p>نو د مور روغتیا د ماشوم له روغتیا سره نږدې تړاو لري.</p><hr><h1>۱۵. Continuity of Care</h1><h2>Continuity of Care — د پاملرنې دوام</h2><h3 dir="rtl"></h3><p>د قابلګۍ یو مهم مفهوم دا دی چې ښځه باید د امکان تر حده د خپل روغتیايي سفر په اوږدو کې منظم او دوامدار ملاتړ ترلاسه کړي.</p><p>مثلاً:</p><p><strong>Antenatal Care</strong></p><p>↓</p><p><strong>Labour Care</strong></p><p>↓</p><p><strong>Birth</strong></p><p>↓</p><p><strong>Postnatal Care</strong></p><p>↓</p><p><strong>Newborn Care</strong></p><p>د پاملرنې دوام د ښځې لپاره د باور او ثبات احساس زیاتولی شي.</p><hr><h1>۱۶. د قابلې او ډاکټر توپیر</h1><h3 dir="rtl"></h3><p>دا موضوع باید په احتیاط سره زده شي.</p><p>قابله او ډاکټر دواړه روغتیايي مسلکي کسان دي، خو د دوی <strong>تعلیم، مسلکي صلاحیتونه، مسؤلیتونه او د کار ساحې</strong> یو شان نه دي.</p><p>په عمومي ډول:</p><h3>Midwife</h3><h3 dir="rtl"></h3><p>د ښځې د امیندوارۍ، زېږون، postpartum او newborn care په برخه کې ځانګړې روزنه لري او د خپل مسلکي scope په دننه کې پاملرنه وړاندې کوي.</p><h3>Obstetrician/Gynecologist</h3><h3 dir="rtl"></h3><p>د ښځینه تناسلي او تولیدي روغتیا او په ځانګړې توګه د امیندوارۍ او زېږون د طبي او جراحي پیچلتیاوو په تشخیص او مدیریت کې تخصص لري.</p><hr><h1>۱۷. قابله کله Referral کوي؟</h1><h3 dir="rtl"></h3><p>یوه مسلکي قابله باید پوهه ولري چې:</p><blockquote><p><strong>هر حالت د قابله یوازې مسؤلیت نه دی.</strong></p></blockquote><p>که د ناروغې حالت د هغې له مسلکي صلاحیت څخه بهر وي یا جدي خطر موجود وي، باید مناسب <strong>Referral</strong> وشي.</p><p>مثلاً که د امیندوارې ښځې حالت داسې وي چې متخصصې طبي پاملرنې ته اړتیا لري، قابله باید:</p><ul><li><p>خطر وپېژني.</p></li><li><p>مناسب اقدام وکړي.</p></li><li><p>متخصص/لوړ کچې مرکز ته Referral وکړي.</p></li><li><p>د امکان تر حده د مور او ماشوم خوندیتوب وساتي.</p></li></ul><p>دا کمزوري نه ده.</p><blockquote><p><strong>Recognizing the limits of your scope is a sign of professional competence.</strong></p></blockquote><hr><h1>۱۸. Evidence-Based Midwifery</h1><h2>Evidence-Based Practice</h2><h3 dir="rtl"></h3><p>قابلګي باید یوازې د پخوانیو دودونو پر اساس نه وي.</p><p>قابله باید د:</p><ul><li><p>علمي شواهدو</p></li><li><p>مسلکي لارښودونو</p></li><li><p>کلینیکي تجربې</p></li><li><p>د ښځې اړتیاوو او ارزښتونو</p></li></ul><p>ترمنځ مناسب توازن رامنځته کړي.</p><p>یعنې:</p><blockquote><p><strong>Good Midwifery = Evidence + Clinical Skill + Woman''s Needs</strong></p></blockquote><hr><h1>۱۹. د قابلې مهم مسلکي رولونه</h1><h3 dir="rtl"></h3><p>قابله یوازې د زېږون پر مهال "مرسته کوونکې" نه ده.</p><p>قابله کولی شي د خپل مسلکي صلاحیت په حدودو کې لاندې رولونه ولري:</p><h3>1. Care Provider</h3><h3 dir="rtl"></h3><p>روغتیايي پاملرنه وړاندې کوي.</p><h3>2. Health Educator</h3><h3 dir="rtl"></h3><p>ښځې او کورنۍ ته روغتیايي معلومات ورکوي.</p><h3>3. Counsellor</h3><h3 dir="rtl"></h3><p>مشوره او رواني ملاتړ وړاندې کوي.</p><h3>4. Advocate</h3><h3 dir="rtl"></h3><p>د ښځې د حقونو او اړتیاوو ملاتړ کوي.</p><h3>5. Communicator</h3><h3 dir="rtl"></h3><p>له ښځې، کورنۍ او روغتیايي ټیم سره مؤثره اړیکه ساتي.</p><h3>6. Assessor</h3><h3 dir="rtl"></h3><p>د مور او ماشوم وضعیت ارزوي.</p><h3>7. Referral Coordinator</h3><h3 dir="rtl"></h3><p>د اړتیا په وخت کې مناسبه Referral اسانتیا برابروي.</p><h3>8. Health Promoter</h3><h3 dir="rtl"></h3><p>د روغتیا د ښه کولو لپاره کار کوي.</p><hr><h1>۲۰. د قابلې او ناروغې اړیکه</h1><h2>Therapeutic Communication</h2><h3 dir="rtl"></h3><p>د قابلې او ښځې ترمنځ اړیکه باید:</p><ul><li><p>محترمانه</p></li><li><p>واضح</p></li><li><p>مسلکي</p></li><li><p>محرم</p></li><li><p>له قضاوت څخه پاکه</p></li><li><p>د ښځې د اړتیاوو پر بنسټ</p></li></ul><p>وي.</p><p>مثلاً:</p><p>❌ "ته ولې دومره وېرېږې؟"</p><p>ښه:</p><p>✅ "زه غواړم پوه شم چې تر ټولو ډېره اندېښنه مو د څه شي په اړه ده."</p><hr><h1>۲۱. Confidentiality — محرمیت</h1><h3 dir="rtl"></h3><p>د ناروغې معلومات باید له اجازې پرته له غیرمجازو کسانو سره شریک نه شي، پرته له هغو مواردو چې د قانون، خوندیتوب یا مسلکي اصولو له مخې ځانګړي استثناوې ولري.</p><p>د مثال په توګه:</p><ul><li><p>د ناروغې روغتیايي معلومات</p></li><li><p>معاینات</p></li><li><p>طبي تاریخچه</p></li><li><p>د امیندوارۍ معلومات</p></li><li><p>شخصي خبرې</p></li></ul><p>د مسلکي محرمیت برخه دي.</p><hr><h1>۲۲. Informed Choice</h1><h2>Informed Choice — باخبره انتخاب</h2><h3 dir="rtl"></h3><p>ښځه باید د امکان تر حده د خپلې روغتیا په اړه په واضح معلوماتو پوهه شي.</p><p>قابله باید:</p><ol><li><p>معلومات ورکړي.</p></li><li><p>د انتخابونو په اړه تشریح وکړي.</p></li><li><p>د پوښتنو فرصت ورکړي.</p></li><li><p>د ښځې انتخاب ته درناوی وکړي، تر هغه چې له خوندیتوب او مسلکي/قانوني اصولو سره ټکر ونه لري.</p></li></ol><hr><h1>۲۳. Autonomy — خپلواکي</h1><h3 dir="rtl"></h3><p><strong>Autonomy</strong> یعنې د فرد حق چې د خپل بدن او روغتیا په اړه د مناسب معلوماتو پر بنسټ پرېکړه وکړي.</p><p>د قابلګۍ په فلسفه کې دا مهمه ده چې ښځه:</p><blockquote><p>د پاملرنې فعاله برخه وي، نه یوازې د پاملرنې ترلاسه کوونکې.</p></blockquote><hr><h1>۲۴. Consent — رضایت</h1><h3 dir="rtl"></h3><p>د هرې مناسبې معاینې یا پروسیجر مخکې، قابله باید د خپل مسلکي او قانوني چوکاټ له مخې د ښځې <strong>Informed Consent</strong> ته درناوی وکړي.</p><p>مثلاً که د یوې معاینې اړتیا وي:</p><p>قابله باید تشریح کړي:</p><ul><li><p>څه به کوي؟</p></li><li><p>ولې یې کوي؟</p></li><li><p>څه ډول به ترسره کېږي؟</p></li></ul><p>او د رضایت اړوند اصول رعایت کړي.</p><hr><h1>۲۵. د قابلګۍ فلسفه او د ښځې عزت</h1><h3 dir="rtl"></h3><p>قابلګي ښځه د:</p><p><strong>Dignity</strong></p><p>په لرلو سره ویني.</p><p>Dignity یعنې:</p><blockquote><p>انساني عزت او ارزښت.</p></blockquote><p>یوه ښځه حتی د زېږون پر مهال هم باید:</p><ul><li><p>په سپکاوي ونه ښودل شي.</p></li><li><p>بې ځایه ونه وېرول شي.</p></li><li><p>په درد یې ملنډې ونه وهل شي.</p></li><li><p>د هغې محرمیت وساتل شي.</p></li><li><p>د هغې پوښتنې جدي واخیستل شي.</p></li></ul><hr><h1>۲۶. د قابلګۍ فلسفه او کورنۍ</h1><h3 dir="rtl"></h3><p>قابله یوازې له ښځې سره نه، بلکې د مناسبې پاملرنې په چوکاټ کې له کورنۍ سره هم اړیکه لري.</p><p>کورنۍ ته:</p><ul><li><p>روغتیايي معلومات</p></li><li><p>د نوي زېږېدلي ماشوم پاملرنه</p></li><li><p>د خطر نښې</p></li><li><p>د مور ملاتړ</p></li></ul><p>په اړه معلومات ورکول د قابلګۍ مهمه برخه کېدای شي.</p><p>خو د ښځې <strong>محرمیت، رضایت او خپلواکي</strong> باید تل مراعات شي.</p><hr><h1>۲۷. د قابلګۍ فلسفه او کلتور</h1><h3 dir="rtl"></h3><p>په افغانستان کې د روغتیايي خدمتونو پر مهال د:</p><p><strong>Culture and Values</strong></p><p>پوهه ډېره مهمه ده.</p><p>قابله باید د ښځې کلتوري او ټولنیز چاپېریال درک کړي، خو داسې دودونه چې د مور یا ماشوم خوندیتوب ته جدي خطر جوړوي باید په مسلکي او درناوي لرونکې توګه و ارزول شي.</p><p>هدف:</p><blockquote><p><strong>Respect the person, protect health.</strong></p></blockquote><hr><h1>۲۸. کلینیکي سناریو ۱ — د زېږون وېره</h1><h3 dir="rtl"></h3><p>یوه ښځه د لومړي ځل لپاره امیندواره ده.</p><p>هغه وایي:</p><blockquote><p>"زه د زېږون څخه ډېره وېرېږم."</p></blockquote><h3>کمزوری ځواب</h3><h3 dir="rtl"><blockquote><p>"هیڅ شی نه کېږي، مه وېرېږه."</p></blockquote></h3><h3>مسلکي ځواب</h3><h3 dir="rtl"></h3><p>قابله:</p><ul><li><p>د هغې خبرې اوري.</p></li><li><p>د وېرې دلیل معلوموي.</p></li><li><p>سم معلومات ورکوي.</p></li><li><p>د زېږون پروسه تشریح کوي.</p></li><li><p>د پوښتنو فرصت ورکوي.</p></li><li><p>که اړتیا وي، اضافي ملاتړ ته یې راجع کوي.</p></li></ul><h3>د قابلګۍ فلسفه</h3><h3 dir="rtl"></h3><p><strong>Woman-centred care + Communication + Education</strong></p><hr><h1>۲۹. کلینیکي سناریو ۲ — ښځه د معاینې په اړه ناراحته ده</h1><h3 dir="rtl"></h3><p>قابله غواړي یوه معاینه ترسره کړي، خو ښځه اندېښمنه ده.</p><h3>قابله باید څه وکړي؟</h3><h3 dir="rtl"></h3><p>د معاینې هدف او طریقه باید تشریح کړي، د ښځې پوښتنو ته ځواب ورکړي او د رضایت اصول مراعات کړي.</p><h3>مهم مفاهیم</h3><h3 dir="rtl"><ul><li><p>Consent</p></li><li><p>Privacy</p></li><li><p>Dignity</p></li><li><p>Respectful Care</p></li></ul><hr></h3><h1>۳۰. کلینیکي سناریو ۳ — د خطر نښه</h1><h3 dir="rtl"></h3><p>یوه امیندواره ښځه داسې نښه لري چې ممکن جدي ارزونې ته اړتیا ولري.</p><p>قابله باید څه وکړي؟</p><p>❌ یوازې ووایي:</p><blockquote><p>"دا عادي ده."</p></blockquote><p>بلکې:</p><ol><li><p>وضعیت ارزوي.</p></li><li><p>خطر نښه پېژني.</p></li><li><p>اړین لومړنی اقدام د خپل صلاحیت له مخې کوي.</p></li><li><p>مناسب Referral تنظیموي.</p></li><li><p>د مور او ماشوم خوندیتوب ته لومړیتوب ورکوي.</p></li></ol><h3>مهم درس</h3><h3 dir="rtl"></h3><p><strong>Midwife must know not only how to provide care, but also when to seek higher-level care.</strong></p><hr><h1>۳۱. کلینیکي سناریو ۴ — د ناروغې محرم معلومات</h1><h3 dir="rtl"></h3><p>یوه ښځه د خپل روغتیا په اړه شخصي معلومات قابله ته وایي.</p><p>بل کس پوښتنه کوي:</p><blockquote><p>"هغې څه ستونزه لري؟"</p></blockquote><p>قابله باید د ناروغې د محرمیت اصول رعایت کړي او معلومات یوازې د مناسب مسلکي/قانوني چوکاټ له مخې شریک کړي.</p><h3>مهم درس</h3><h3 dir="rtl"></h3><p><strong>Confidentiality is a professional responsibility.</strong></p><hr><h1>۳۲. کلینیکي سناریو ۵ — د ښځې انتخاب</h1><h3 dir="rtl"></h3><p>یوه ښځه غواړي د خپل پاملرنې په اړه پوښتنې وکړي.</p><p>قابله باید:</p><ul><li><p>معلومات ورکړي.</p></li><li><p>انتخابونه تشریح کړي.</p></li><li><p>د هغې پوښتنې واوري.</p></li><li><p>د هغې خپلواکي او رضایت ته درناوی وکړي.</p></li></ul><h3>مهم درس</h3><h3 dir="rtl"></h3><p>ښځه باید د پاملرنې په پروسه کې فعاله برخه وي.</p><hr><h1>۳۳. کلینیکي سناریو ۶ — مور او ماشوم</h1><h3 dir="rtl"></h3><p>یوه مور د ماشوم له زېږون وروسته ډېره ستړې ده او د ماشوم د پاملرنې په اړه پوښتنې لري.</p><p>قابله باید یوازې ماشوم ونه ارزوي.</p><p>بلکې:</p><p><strong>Mother + Newborn</strong></p><p>دواړه باید د پاملرنې په پلان کې شامل وي.</p><h3>مهم درس</h3><h3 dir="rtl"></h3><p>د نوي زېږېدلي ماشوم روغتیا د مور له روغتیا او ملاتړ سره نږدې تړاو لري.</p><hr><h1>۳۴. کلینیکي سناریو ۷ — د قابله د صلاحیت حدود</h1><h3 dir="rtl"></h3><p>یوه ناروغه داسې پیچلتیا لري چې د قابلې له مسلکي صلاحیت څخه بهر ده.</p><p>ایا قابله باید د متخصص پر ځای خپله درملنه وکړي؟</p><p><strong>نه.</strong></p><p>مسلکي قابله باید د خپل <strong>Scope of Practice</strong> حدود وپېژني او مناسب Referral وکړي.</p><h3>مهم درس</h3><h3 dir="rtl"><blockquote><p>د خپل حد پېژندل د مسلکي کمزورۍ نښه نه ده؛ د مسلکي وړتیا نښه ده.</p></blockquote><hr></h3><h1>۳۵. د قابلګۍ فلسفې مهم اصول</h1><h3 dir="rtl"></h3><p>د دې برخې لپاره دا لس اصول زده کړئ:</p><h3>۱. Woman-Centred Care</h3><h3 dir="rtl"></h3><p>د ښځې اړتیاوې د پاملرنې په مرکز کې.</p><h3>۲. Respect</h3><h3 dir="rtl"></h3><p>درناوی.</p><h3>۳. Dignity</h3><h3 dir="rtl"></h3><p>انساني عزت.</p><h3>۴. Autonomy</h3><h3 dir="rtl"></h3><p>خپلواکي.</p><h3>۵. Informed Choice</h3><h3 dir="rtl"></h3><p>باخبره انتخاب.</p><h3>۶. Consent</h3><h3 dir="rtl"></h3><p>رضایت.</p><h3>۷. Confidentiality</h3><h3 dir="rtl"></h3><p>محرمیت.</p><h3>۸. Holistic Care</h3><h3 dir="rtl"></h3><p>هر اړخیزه پاملرنه.</p><h3>۹. Evidence-Based Practice</h3><h3 dir="rtl"></h3><p>د شواهدو پر بنسټ عمل.</p><h3>۱۰. Referral and Collaboration</h3><h3 dir="rtl"></h3><p>د اړتیا پر مهال Referral او له روغتیايي ټیم سره همکاري.</p><hr><h1>۳۶. قابله باید څه ډول مسلکي شخصیت ولري؟</h1><h3 dir="rtl"></h3><p>یوه ښه قابله یوازې علمي معلومات نه لري.</p><p>هغې ته لاندې ځانګړتیاوې هم مهمې دي:</p><ul><li><p>علمي پوهه</p></li><li><p>عملي مهارت</p></li><li><p>ښه اړیکه</p></li><li><p>صبر</p></li><li><p>همدردي</p></li><li><p>مسلکي اخلاق</p></li><li><p>دقت</p></li><li><p>مسؤلیت</p></li><li><p>محرمیت</p></li><li><p>د خطر پېژندنه</p></li><li><p>د پرېکړې وړتیا</p></li><li><p>د ټیم کار</p></li><li><p>د زده‌کړې دوام</p></li></ul><hr><h1>۳۷. Midwife ≠ فقط Delivery Assistant</h1><h3 dir="rtl"></h3><p>دا جمله حتماً زده کړئ:</p><blockquote><p><strong>A midwife is not simply a person who assists with childbirth.</strong></p></blockquote><p>قابله یوه مسلکي روغتیايي کارکوونکې ده چې د خپل مسلکي صلاحیت په حدودو کې د ښځې د تولیدي روغتیا او د امیندوارۍ، زېږون، postpartum او newborn care په برخه کې پاملرنه وړاندې کوي.</p><hr><h1>۳۸. د قابلګۍ او طب اړیکه</h1><h3 dir="rtl"></h3><p>قابلګي او طب د یو بل مخالف مسلکونه نه دي.</p><p>په روغتیايي سیستم کې دوی کولی شي یو له بل سره همکاري وکړي.</p><p>مثلاً:</p><p><strong>Midwife</strong></p><p>↓</p><p>د ښځې ارزونه</p><p>↓</p><p>Normal/Abnormal حالت پېژندنه</p><p>↓</p><p>که عادي وي → د خپل صلاحیت دننه پاملرنه</p><p>↓</p><p>که پیچلتیا وي → Referral / Collaboration</p><p>↓</p><p><strong>Obstetric/Medical Team</strong></p><p>دا د مور او ماشوم د خوندیتوب لپاره مهم سیستم دی.</p><hr><h1>۳۹. د زده‌کوونکې لپاره د یادولو مهم فورمول</h1><h3 dir="rtl"></h3><p>د قابلګۍ فلسفه په دې ډول یادولای شئ:</p><blockquote><p><strong>Respect + Safety + Evidence + Choice + Continuity + Holistic Care</strong></p></blockquote><p>یعنې:</p><p><strong>درناوی + خوندیتوب + شواهد + انتخاب + دوامداره پاملرنه + هر اړخیزه پاملرنه</strong></p><hr><h1>۴۰. Online Individual Activity</h1><h3 dir="rtl"></h3><p>د آنلاین سیستم لپاره د Group Activity پر ځای دا انفرادي فعالیت مناسب دی.</p><h2>Activity: "What Would a Midwife Do?"</h2><h3 dir="rtl"></h3><p>زده‌کوونکې ته لاندې سناریو ورکړئ:</p><blockquote><p>یوه امیندواره ښځه د لومړي ځل لپاره د روغتیايي مرکز ته راغلې. هغه د زېږون څخه وېرېږي او وایي چې نه پوهېږي څه باید وکړي.</p></blockquote><p>زده‌کوونکې باید له لاندې انتخابونو څخه مناسب کارونه انتخاب کړي:</p><p>☐ د هغې خبرې واوري.</p><p>☐ د هغې وېره مسخره کړي.</p><p>☐ د هغې پوښتنو ته واضح معلومات ورکړي.</p><p>☐ د هغې محرمیت وساتي.</p><p>☐ د خطر نښې و ارزوي.</p><p>☐ پرته له وضاحت څخه هره پروسیجر ترسره کړي.</p><h3>صحیح انتخابونه:</h3><h3 dir="rtl"></h3><p>✅ د هغې خبرې واوري.</p><p>✅ واضح معلومات ورکړي.</p><p>✅ محرمیت وساتي.</p><p>✅ د خطر نښې وارزوي.</p><h3>هدف</h3><h3 dir="rtl"></h3><p>زده‌کوونکې د <strong>Midwifery Philosophy</strong> اصول په یوه واقعي حالت کې تطبیقوي.</p><hr><h1>۴۱. مهم مسلکي لغات</h1><h3 dir="rtl"></h3><table><thead><tr><th>پښتو</th><th>English</th><th>ساده تشریح</th></tr></thead><tbody><tr><td>قابلګي</td><td>Midwifery</td><td>د ښځو او میندو اړوند مسلکي روغتیايي رشته</td></tr><tr><td>قابله</td><td>Midwife</td><td>روزل شوې مسلکي روغتیايي کارکوونکې</td></tr><tr><td>امیندوارۍ</td><td>Pregnancy</td><td>د جنین د ودې دوره</td></tr><tr><td>زېږون</td><td>Childbirth / Birth</td><td>د ماشوم د زېږېدو پروسه</td></tr><tr><td>د زېږون دردونه</td><td>Labour</td><td>هغه فزیولوژیکه پروسه چې د زېږون پر لور ځي</td></tr><tr><td>له زېږون وروسته دوره</td><td>Postpartum/Postnatal Period</td><td>د زېږون وروسته دوره</td></tr><tr><td>د نوي زېږېدلي ماشوم پاملرنه</td><td>Newborn Care</td><td>د نوي ماشوم روغتیايي پاملرنه</td></tr><tr><td>فلسفه</td><td>Philosophy</td><td>بنسټیز فکرونه او ارزښتونه</td></tr><tr><td>درناوی</td><td>Respect</td><td>د شخص ارزښت ته درناوی</td></tr><tr><td>انساني عزت</td><td>Dignity</td><td>د انسان ذاتي ارزښت</td></tr><tr><td>خپلواکي</td><td>Autonomy</td><td>د خپل بدن او روغتیا په اړه د پرېکړې حق</td></tr><tr><td>رضایت</td><td>Consent</td><td>د معلوماتو وروسته موافقه</td></tr><tr><td>محرمیت</td><td>Confidentiality</td><td>د شخصي معلوماتو ساتنه</td></tr><tr><td>هر اړخیزه پاملرنه</td><td>Holistic Care</td><td>فزیکي، رواني او ټولنیزې اړتیاوې</td></tr><tr><td>د ښځې پر محور پاملرنه</td><td>Woman-Centred Care</td><td>د ښځې اړتیاوې د پاملرنې مرکز ګرځول</td></tr><tr><td>Referral</td><td>Referral</td><td>لوړ/مناسب روغتیايي خدمت ته لېږل</td></tr><tr><td>مسلکي حدود</td><td>Scope of Practice</td><td>هغه کارونه چې مسلکي کس یې د خپل صلاحیت له مخې ترسره کولی شي</td></tr><tr><td>د شواهدو پر بنسټ عمل</td><td>Evidence-Based Practice</td><td>د علمي شواهدو پر بنسټ پاملرنه</td></tr></tbody></table><hr><h1>۴۲. د درس لنډه نقشه</h1><h3>Midwifery</h3><h3 dir="rtl"></h3><p><strong>Woman</strong></p><p>↓</p><p><strong>Pregnancy</strong></p><p>↓</p><p><strong>Labour &amp; Birth</strong></p><p>↓</p><p><strong>Postnatal Care</strong></p><p>↓</p><p><strong>Newborn Care</strong></p><p>او د دې تر څنګ:</p><p><strong>Reproductive Health + Health Education + Counselling + Referral</strong></p><hr><h1>۴۳. د درس تر ټولو مهمې جملې</h1><h3>جمله ۱</h3><h3 dir="rtl"><blockquote><p><strong>Midwifery is more than assisting childbirth.</strong></p></blockquote></h3><p>قابلګي یوازې د زېږون مرسته نه ده.</p><h3>جمله ۲</h3><h3 dir="rtl"><blockquote><p><strong>Pregnancy is a physiological process, but complications can occur.</strong></p></blockquote></h3><p>امیندوارۍ فزیولوژیکه پروسه ده، خو پیچلتیاوې رامنځته کېدای شي.</p><h3>جمله ۳</h3><h3 dir="rtl"><blockquote><p><strong>The woman is at the centre of care.</strong></p></blockquote></h3><p>ښځه د پاملرنې په مرکز کې ده.</p><h3>جمله ۴</h3><h3 dir="rtl"><blockquote><p><strong>Respect, dignity, privacy and informed choice are essential.</strong></p></blockquote></h3><p>درناوی، عزت، محرمیت او باخبره انتخاب مهم دي.</p><h3>جمله ۵</h3><h3 dir="rtl"><blockquote><p><strong>A skilled midwife knows when to provide care and when to refer.</strong></p></blockquote></h3><p>مسلکي قابله پوهېږي چې کله پاملرنه وړاندې کړي او کله Referral وکړي.</p><hr><h1>۴۴. Assessment — ارزونه</h1><h2>A. Multiple Choice — Single Answer</h2><h3>۱. Midwifery څه ده؟</h3><h3 dir="rtl"></h3><p>A. یوازې د ماشوم زېږولو مرسته<br>B. یوازې د نوي ماشوم درملنه<br>C. د ښځې، امیندوارۍ، زېږون، postpartum او اړوندو روغتیايي اړتیاوو مسلکي پاملرنه<br>D. یوازې د ښځینه جراحي عملیات</p><p><strong>صحیح ځواب: C</strong></p><p><strong>تشریح:</strong> قابلګي د ښځې د تولیدي روغتیا او د امیندوارۍ، زېږون، postpartum او newborn care پراخه مسلکي ساحه لري.</p><hr><h3>۲. Woman-Centred Care څه معنی لري؟</h3><h3 dir="rtl"></h3><p>A. یوازې د جنین پاملرنه<br>B. د ښځې اړتیاوې او ارزښتونه د پاملرنې په مرکز کې ساتل<br>C. یوازې د کورنۍ پاملرنه<br>D. یوازې د ډاکټر پرېکړه منل</p><p><strong>صحیح ځواب: B</strong></p><p><strong>تشریح:</strong> د ښځې اړتیاوې، انتخابونه، ارزښتونه، خوندیتوب او درناوی د پاملرنې مهم عناصر دي.</p><hr><h3>۳. کوم یو د قابلګۍ د فلسفې مهم اصل دی؟</h3><h3 dir="rtl"></h3><p>A. Disrespect<br>B. Confidentiality<br>C. Ignoring the patient<br>D. Unnecessary intervention</p><p><strong>صحیح ځواب: B</strong></p><p><strong>تشریح:</strong> محرمیت د مسلکي روغتیايي پاملرنې مهم اصل دی.</p><hr><h3>۴. کله Referral مهم دی؟</h3><h3 dir="rtl"></h3><p>A. کله چې حالت د قابلې له مسلکي صلاحیت څخه بهر وي<br>B. هېڅکله<br>C. یوازې کله چې ناروغه وغواړي<br>D. یوازې د عادي امیندوارۍ پر مهال</p><p><strong>صحیح ځواب: A</strong></p><p><strong>تشریح:</strong> قابله باید د خپل Scope of Practice حدود وپېژني او د اړتیا پر مهال مناسب Referral وکړي.</p><hr><h3>۵. Holistic Care څه معنی لري؟</h3><h3 dir="rtl"></h3><p>A. یوازې د بدن معاینه<br>B. یوازې د ماشوم پاملرنه<br>C. د ښځې فزیکي، رواني، احساساتي، ټولنیزې او اړوندې اړتیاوې په پام کې نیول<br>D. یوازې د درملو ورکول</p><p><strong>صحیح ځواب: C</strong></p><hr><h1>۴۵. True / False</h1><h3>۶. قابلګي یوازې د ماشوم د زېږون پر مهال کار دی.</h3><h3 dir="rtl"></h3><p><strong>ځواب: False ❌</strong></p><p><strong>تشریح:</strong> قابلګي د امیندوارۍ، زېږون، postpartum، newborn او تولیدي روغتیا پراخه برخه لري.</p><hr><h3>۷. یوه قابله باید د خپل مسلکي صلاحیت حدود وپېژني.</h3><h3 dir="rtl"></h3><p><strong>ځواب: True ✅</strong></p><p><strong>تشریح:</strong> د مسلکي حدودو پېژندل د خوندي پاملرنې لپاره ضروري دي.</p><hr><h3>۸. د ښځې محرمیت د قابلګۍ له مسلکي اصولو څخه دی.</h3><h3 dir="rtl"></h3><p><strong>ځواب: True ✅</strong></p><p><strong>تشریح:</strong> Confidentiality د مسلکي او اخلاقي پاملرنې مهم اصل دی.</p><hr><h1>۴۶. Short Answer</h1><h3>۹. Midwifery په خپلو الفاظو تعریف کړئ.</h3><h3 dir="rtl"></h3><p><strong>نمونوي ځواب:</strong></p><p>قابلګي یوه مسلکي روغتیايي رشته ده چې د ښځې د تولیدي روغتیا او د امیندوارۍ، زېږون، له زېږون وروسته دورې او نوي زېږېدلي ماشوم لپاره د خپل مسلکي صلاحیت په حدودو کې پاملرنه وړاندې کوي.</p><hr><h3>۱۰. د قابلګۍ د فلسفې درې مهم اصول ولیکئ.</h3><h3 dir="rtl"></h3><p><strong>نمونوي ځواب:</strong></p><p>هر درې مناسب اصول منل کېږي، لکه:</p><ul><li><p>Woman-Centred Care</p></li><li><p>Respect</p></li><li><p>Dignity</p></li><li><p>Confidentiality</p></li><li><p>Autonomy</p></li><li><p>Informed Choice</p></li><li><p>Holistic Care</p></li><li><p>Evidence-Based Practice</p></li></ul><hr><h1>۴۷. جامع کلینیکي سناریو</h1><h3 dir="rtl"></h3><p>یوه ۲۴ کلنه امیندواره ښځه د ANC لپاره روغتیايي مرکز ته راځي. هغه وایي:</p><blockquote><p>"زه د خپل لومړي ماشوم د زېږون په اړه ډېره وېرېدلې یم."</p></blockquote><p>قابله باید څه وکړي؟</p><h3>لومړی</h3><h3 dir="rtl"></h3><p>د ښځې خبرې په دقت واوري.</p><h3>دوهم</h3><h3 dir="rtl"></h3><p>د هغې د وېرې علت معلوم کړي.</p><h3>درېیم</h3><h3 dir="rtl"></h3><p>مناسب او واضح روغتیايي معلومات ورکړي.</p><h3>څلورم</h3><h3 dir="rtl"></h3><p>د هغې محرمیت او عزت وساتي.</p><h3>پنځم</h3><h3 dir="rtl"></h3><p>د امیندوارۍ وضعیت او اړوند خطر نښې د خپل مسلکي صلاحیت په حدودو کې وارزوي.</p><h3>شپږم</h3><h3 dir="rtl"></h3><p>که کومه ستونزه یا خطر موجود وي، مناسب Referral وکړي.</p><h3>اووم</h3><h3 dir="rtl"></h3><p>ښځه د پاملرنې فعاله برخه وګرځوي.</p><h3>د دې سناریو مهم اصول</h3><h3 dir="rtl"></h3><p><strong>Woman-Centred Care</strong></p><ul><li></ul><p><strong>Respect</strong></p><ul><li></ul><p><strong>Communication</strong></p><ul><li></ul><p><strong>Health Education</strong></p><ul><li></ul><p><strong>Safety</strong></p><ul><li></ul><p><strong>Informed Choice</strong></p><hr><h1>۴۸. د استاد وروستی پیغام</h1><h3 dir="rtl"></h3><p>ګرانو زده‌کوونکو!</p><p>قابله کېدل یوازې د دې معنا نه لري چې تاسو د زېږون پروسه زده کړئ.</p><p>یوه ښه قابله باید:</p><p><strong>علم ولري،</strong></p><p><strong>مهارت ولري،</strong></p><p><strong>ښه واوري،</strong></p><p><strong>درناوی وکړي،</strong></p><p><strong>د ښځې عزت وساتي،</strong></p><p><strong>محرمیت وساتي،</strong></p><p><strong>خطر وپېژني،</strong></p><p><strong>د خپل مسلکي حدودو په اړه پوهه ولري،</strong></p><p>او تر ټولو مهم:</p><blockquote><p><strong>ښځه د یوه بشپړ انسان په توګه وویني، نه یوازې د یوه طبي حالت په توګه.</strong></p></blockquote><p>د قابلګۍ فلسفه په دې یوه جمله کې راټولولای شو:</p><blockquote><p><strong>"د ښځې ترڅنګ اوسېدل، د هغې خبرې اورېدل، د هغې عزت ساتل، د هغې خوندیتوب ته پاملرنه کول، د علم او شواهدو پر بنسټ خدمت وړاندې کول، او د اړتیا پر مهال د مناسبې لوړې کچې پاملرنې لپاره اقدام کول."</strong></p></blockquote><p>دا هغه بنسټ دی چې ستاسو په راتلونکو ټولو Midwifery درسونو کې به پرې نور مهارتونه جوړېږي.</p>', 'rtl', 'none', NULL, NULL, 30, 'intro', 2, TRUE, 1, TRUE, '2026-09-13 04:39:29'),
(369, 34, 'د قابلګي تاریخ په نړۍ کې', '<p dir="rtl" style="text-align:right">قابلګي د بشر تر ټولو زوړ روغتیايي مسلک دی.</p>', '<h1>درس: د قابلګۍ تاریخ په نړۍ کې</h1><h2>History of Midwifery in the World</h2><h3 dir="rtl"></h3><p>دا درس به د پخوانیو تمدنونو څخه پیل شي او په تدریجي ډول به د <strong>عصري مسلکي قابلګۍ (Modern Professional Midwifery)</strong> تر جوړېدو پورې راشي. هدف یوازې د تاریخونو حفظ کول نه دي؛ بلکې دا درک کول دي چې <strong>قابلګي څنګه له دودیزې تجربې څخه یوې علمي، مسلکي او شواهدو پر بنسټ روغتیايي رشتې ته بدله شوه.</strong></p><hr><h1>۱. د درس عمومي هدفونه</h1><h3 dir="rtl"></h3><p>د دې درس تر پای پورې به زده‌کوونکې وکولای شي:</p><ol><li><p>د قابلګۍ د تاریخ عمومي پرمختګ تشریح کړي.</p></li><li><p>پوه شي چې د قابلګۍ لومړني ډولونه څنګه رامنځته شول.</p></li><li><p>د پخوانیو تمدنونو په روغتیايي پاملرنه کې د قابلې رول بیان کړي.</p></li><li><p>د مصر، یونان، روم او نورو تمدنونو د قابلګۍ تاریخي ونډه وپېژني.</p></li><li><p>د منځنیو پېړیو په جریان کې د قابلګۍ وضعیت تشریح کړي.</p></li><li><p>د <strong>16th–18th centuries</strong> په جریان کې د مسلکي قابلګۍ د بدلونونو په اړه پوه شي.</p></li><li><p>د <strong>19th او 20th centuries</strong> مهم بدلونونه تشریح کړي.</p></li><li><p>د Florence Nightingale، Ignaz Semmelweis او نورو مهمو شخصیتونو ونډه درک کړي.</p></li><li><p>د قابله‌ګۍ د رسمي تعلیم او مسلکي تنظیم اهمیت تشریح کړي.</p></li><li><p>د قابلګۍ له تاریخي پرمختګ څخه د نننۍ قابلې مسلکي هویت درک کړي.</p></li></ol><hr><h1>۲. له تېر درس سره اړیکه</h1><h3 dir="rtl"></h3><p>په تېر درس کې مو زده کړل:</p><blockquote><p><strong>قابلګي څه ده؟</strong></p></blockquote><p>موږ پوه شو چې قابلګي یوازې د ماشوم د زېږولو مرسته نه ده.</p><p>قابله د:</p><ul><li><p>امیندوارۍ</p></li><li><p>زېږون</p></li><li><p>له زېږون وروسته دورې</p></li><li><p>نوي زېږېدلي ماشوم</p></li><li><p>تولیدي روغتیا</p></li><li><p>روغتیايي زده‌کړې</p></li><li><p>مشورې</p></li><li><p>خطر پېژندنې</p></li><li><p>Referral</p></li></ul><p>په برخو کې مهم رول لري.</p><p>اوس یوه طبیعي پوښتنه پیدا کېږي:</p><blockquote><p><strong>دا مسلک څنګه رامنځته شو؟</strong></p></blockquote><p>ایا په پخوانیو وختونو کې هم قابله موجوده وه؟</p><p><strong>هو.</strong></p><p>خو د نننۍ قابلې او د زرګونو کلونو مخکې د زېږون مرستندویې ترمنځ د تعلیم، علم، مسؤلیت او مسلکي تنظیم له نظره ډېر لوی توپیر شته.</p><hr><h1>۳. د قابلګۍ تاریخ ولې مهم دی؟</h1><h3 dir="rtl"></h3><p>کېدای شي یوه زده‌کوونکې ووایي:</p><blockquote><p>"ولې باید د تاریخ درس ولولم؟ زه خو قابله کېږم، تاریخپوهه نه."</p></blockquote><p>دا یوه مهمه پوښتنه ده.</p><p>د قابلګۍ تاریخ موږ ته ښيي:</p><ul><li><p>دا مسلک څنګه رامنځته شو؟</p></li><li><p>ښځو څنګه یو بل سره د زېږون پر مهال مرسته کوله؟</p></li><li><p>علم څنګه د دودیزې تجربې ځای ونیو؟</p></li><li><p>ولې Hygiene مهمه شوه؟</p></li><li><p>ولې Antenatal Care رامنځته شوه؟</p></li><li><p>ولې Professional Education ضروري شوه؟</p></li><li><p>ولې Evidence-Based Practice مهمه ده؟</p></li><li><p>ولې د مور او ماشوم خوندیتوب د قابلګۍ مرکزي هدف دی؟</p></li></ul><p>نو تاریخ یوازې د تېر وخت کیسه نه ده.</p><blockquote><p><strong>تاریخ موږ سره مرسته کوي چې پوه شو ولې نننۍ قابلګي داسې ده.</strong></p></blockquote><hr><h1>۴. د قابلګۍ لومړنی پیل</h1><h3 dir="rtl"></h3><p>قابلګي د هغو پخوانیو روغتیايي فعالیتونو له ډلې څخه ده چې له رسمي روغتیايي ښوونځیو څخه ډېر مخکې موجوده وه.</p><p>په پخوانیو ټولنو کې کله چې یوه ښځه د زېږون په حال کې وه، عموماً نورې تجربه لرونکې ښځې ورسره وې.</p><p>هغوی ممکن:</p><ul><li><p>د زېږون تجربه لرله.</p></li><li><p>د ښځې ملاتړ یې کاوه.</p></li><li><p>د ماشوم د زېږېدو پر مهال یې مرسته کوله.</p></li><li><p>د مور لپاره دودیزې لارې کارولې.</p></li><li><p>د نوي ماشوم لومړنۍ پاملرنه یې کوله.</p></li></ul><p>دا ډول مرسته په ډېرو پخوانیو ټولنو کې د کورنۍ او ټولنې یوه برخه وه.</p><p>خو باید یو مهم ټکی په یاد ولرو:</p><blockquote><p>د دې پخوانیو ښځو ټولې تجربې د نن ورځې د علمي قابلګۍ سره مساوي نه وې.</p></blockquote><hr><h1>۵. Traditional Midwifery — دودیزه قابلګي</h1><h3 dir="rtl"></h3><p><strong>Traditional Midwifery</strong> هغه پاملرنه وه چې د نسلونو د تجربې، مشاهدې او ټولنیزو دودونو له لارې انتقالېدله.</p><p>د مثال په توګه:</p><p>یوه تجربه لرونکې ښځه به خپلې لور یا بلې ځوانې ښځې ته د زېږون د مرستې لارې ښودلې.</p><p>نو پوهه داسې انتقالېدله:</p><p><strong>Experience → Observation → Teaching → Next Generation</strong></p><p>یعنې:</p><p><strong>تجربه → مشاهده → ښوونه → راتلونکی نسل</strong></p><hr><h1>۶. د لرغوني مصر قابلګي</h1><h3 dir="rtl"></h3><p>د لرغوني مصر په ټولنه کې د امیندوارۍ او زېږون لپاره ځانګړې پاملرنه موجوده وه.</p><p>د مصر له تاریخي سرچینو څخه د ښځینه روغتیا او زېږون په اړه معلومات ترلاسه شوي دي.</p><p>د <strong>Ebers Papyrus</strong> په څېر پخوانیو طبي متنونو کې د ښځو او امیندوارۍ اړوند معلومات هم موندل کېږي.</p><p>د لرغوني مصر په ټولنه کې قابله یا د زېږون تجربه لرونکې ښځه د ښځې ترڅنګ د زېږون پر مهال مهمه وه.</p><hr><h1>۷. د لرغوني مصر د زېږون یوه مهمه ځانګړتیا</h1><h3 dir="rtl"></h3><p>په پخواني مصر کې د زېږون لپاره ځانګړي ځایونه او د زېږون اړوند دودونه موجود وو.</p><p>د تاریخ له مخې ښځو د زېږون پر مهال په ځانګړو حالتونو کې زېږون کاوه، او د زېږون د مرستې لپاره تجربه لرونکې ښځې موجودې وې.</p><p>دا موږ ته ښيي چې:</p><blockquote><p>د زېږون پاملرنه له ډېرو پخوانیو وختونو راهیسې د ټولنې یوه مهمه اړتیا وه.</p></blockquote><hr><h1>۸. لرغونی یونان</h1><h3 dir="rtl"></h3><p>په لرغوني یونان کې د طب او فلسفې پرمختګ د روغتیايي پوهې پر تاریخ مهم اغېز وکړ.</p><p><strong>Hippocrates</strong> د طب په تاریخ کې یو له مهمو شخصیتونو څخه دی.</p><p>د هغه له مکتب سره تړلو لیکنو کې د ښځینه روغتیا، امیندوارۍ او زېږون په اړه بحثونه هم موجود دي.</p><p>خو په دې دوره کې د ښځو د روغتیا پاملرنه په ډېرو مواردو کې د ښځینه تجربه لرونکو مرستندویانو او د نارینه طبیبانو ترمنځ جلا شوې وه.</p><hr><h1>۹. Soranus of Ephesus</h1><h3 dir="rtl"></h3><p>د قابلګۍ د تاریخ په مطالعه کې:</p><p><strong>Soranus of Ephesus</strong></p><p>یو ډېر مهم نوم دی.</p><p>هغه د یونان له سیمې سره تړلی طبي لیکوال و چې د روم په دوره کې یې فعالیت کاوه.</p><p>د هغه لیکنې د ښځینه ناروغیو او زېږون په اړه مهم تاریخي معلومات لري.</p><p>د هغه اثر:</p><p><strong>Gynecology</strong></p><p>د لرغوني وخت د ښځینه روغتیا له مهمو پاتې شویو طبي اثارو څخه ګڼل کېږي.</p><hr><h1>۱۰. Soranus د قابلې په اړه</h1><h3 dir="rtl"></h3><p>د Soranus په لیکنو کې د قابلې د ځانګړتیاوو په اړه هم معلومات شته.</p><p>د یوې وړې قابلې لپاره یوازې تجربه کافي نه ګڼل کېده.</p><p>د هغې لپاره:</p><ul><li><p>پوهه</p></li><li><p>عملي مهارت</p></li><li><p>ښه اخلاق</p></li><li><p>د ناروغې د حالت درک</p></li><li><p>د زېږون اړوند مهارت</p></li></ul><p>مهم ګڼل شوي وو.</p><p>دا یو مهم تاریخي ټکی دی:</p><blockquote><p>حتی په لرغوني وخت کې هم د "ښه قابله" لپاره یوازې د زېږون تجربه کافي نه ګڼل کېده.</p></blockquote><hr><h1>۱۱. لرغونی روم</h1><h3 dir="rtl"></h3><p>د روم په دوره کې د طب او د ښځینه روغتیا اړوند پوهه نوره هم پراخه شوه.</p><p>قابلې د زېږون په پروسه کې مهمې وې.</p><p>په ډېرو مواردو کې قابله د ښځې د زېږون اصلي مسلکي مرسته کوونکې وه.</p><p>طبیبان عموماً هغه وخت ډېر مهم کېدل چې:</p><ul><li><p>جدي پیچلتیا موجوده وه.</p></li><li><p>جراحي اړتیا وه.</p></li><li><p>د مور یا ماشوم وضعیت غیرعادي و.</p></li></ul><p>دا د نننۍ:</p><p><strong>Midwife + Medical/Obstetric Team</strong></p><p>همکارۍ سره یو څه تاریخي ورته والی لري، که څه هم د دواړو دورو سیستمونه یو شان نه وو.</p><hr><h1>۱۲. د منځنیو پېړیو دوره</h1><h2>Middle Ages</h2><h3 dir="rtl"></h3><p>تقریباً د پنځمې څخه تر پنځلسمې پېړۍ پورې د اروپا په ډېرو برخو کې د روغتیايي پوهې پرمختګ ورو و.</p><p>قابلګي تر ډېره:</p><ul><li><p>په کورونو کې</p></li><li><p>د ټولنې په کچه</p></li><li><p>د تجربه لرونکو ښځو له لارې</p></li></ul><p>پر مخ تلله.</p><p>ډېری قابله‌ګانې رسمي عصري طبي تعلیم نه درلود.</p><p>د هغوی پوهه د:</p><p><strong>Experience + Tradition</strong></p><p>پر بنسټ وه.</p><hr><h1>۱۳. د قابلو ټولنیز رول</h1><h3 dir="rtl"></h3><p>په منځنیو پېړیو کې قابله یوازې د زېږون پر مهال نه کارېده.</p><p>په ځینو ټولنو کې هغې ته د:</p><ul><li><p>ښځینه روغتیا</p></li><li><p>د نوي ماشوم لومړنۍ پاملرنه</p></li><li><p>د زېږون اړوند دودونه</p></li><li><p>د کورنۍ ملاتړ</p></li></ul><p>په برخه کې هم مراجعه کېده.</p><p>نو قابله د ټولنې یوه مهمه ښځینه روغتیايي مرستندویه وه.</p><hr><h1>۱۴. د دود او علم ترمنځ ستونزه</h1><h3 dir="rtl"></h3><p>په پخوانیو وختونو کې یوه مهمه ستونزه دا وه چې:</p><blockquote><p>هره تجربه شوې طریقه لازماً علمي او خوندي نه وه.</p></blockquote><p>ځینې دودونه ممکن ګټور وو.</p><p>خو ځینې نور:</p><ul><li><p>علمي بنسټ نه درلود.</p></li><li><p>د انتان خطر یې زیاتولی شو.</p></li><li><p>د مور یا ماشوم لپاره خطرناک کېدای شو.</p></li></ul><p>دلته د <strong>Evidence-Based Practice</strong> اړتیا ورو ورو څرګندېږي.</p><hr><h1>۱۵. د Renaissance دوره</h1><h3 dir="rtl"></h3><p>د <strong>Renaissance</strong> په دوره کې، په ځانګړې توګه په اروپا کې، د علم، هنر او انساني بدن د مطالعې په برخه کې لوی بدلونونه راغلل.</p><p>د انسان د بدن د جوړښت مطالعه زیاته شوه.</p><p><strong>Anatomy</strong></p><p>ورو ورو د طبي تعلیم مهمه برخه شوه.</p><p>د Anatomical dissection او علمي مشاهدې له زیاتېدو سره د بدن په اړه پوهه پراخه شوه.</p><p>دا بدلون وروسته د قابلګۍ او Obstetrics په علم باندې هم اغېز وکړ.</p><hr><h1>۱۶. Andreas Vesalius</h1><h3 dir="rtl"></h3><p><strong>Andreas Vesalius</strong> د Anatomy په تاریخ کې مهم شخصیت دی.</p><p>په 1543 کال کې یې:</p><p><strong>De Humani Corporis Fabrica</strong></p><p>خپور کړ.</p><p>دې اثر د انسان د بدن د اناتومي په علم کې لوی بدلون رامنځته کړ.</p><p>د قابلګۍ لپاره یې غیرمستقیم اهمیت دا و چې:</p><blockquote><p>د ښځینه تولیدي سیستم، pelvis او د بدن د جوړښت په اړه علمي پوهه د وخت په تېرېدو لا زیاته شوه.</p></blockquote><hr><h1>۱۷. د قابلو رسمي تنظیم</h1><h3 dir="rtl"></h3><p>په اروپا کې د وخت په تېرېدو ځینې ځایونه داسې شول چې قابلو ته:</p><ul><li><p>رسمي اجازه</p></li><li><p>مقررات</p></li><li><p>روزنه</p></li><li><p>د کار حدود</p></li></ul><p>ټاکل کېدل.</p><p>دا د قابلګۍ د:</p><p><strong>Traditional Practice → Regulated Profession</strong></p><p>په لوري د حرکت یوه برخه وه.</p><hr><h1>۱۸. د 17مې او 18مې پېړۍ بدلون</h1><h3 dir="rtl"></h3><p>په دې دوره کې:</p><ul><li><p>Anatomy پرمختګ وکړ.</p></li><li><p>Medical education پراخه شوه.</p></li><li><p>Obstetrics د طب یوه مهمه برخه شوه.</p></li><li><p>د زېږون اړوند وسایل پراخ شول.</p></li><li><p>په ځینو ځایونو کې نارینه طبیبان د زېږون په برخه کې زیات دخیل شول.</p></li></ul><p>دلته یو مهم بدلون رامنځته شو:</p><blockquote><p>د زېږون پاملرنه ورو ورو له یوازې کورني دود څخه روغتیايي مسلکي چاپېریال ته هم انتقالېده.</p></blockquote><hr><h1>۱۹. Obstetrics او Midwifery</h1><h3 dir="rtl"></h3><p>د دې دورې په جریان کې:</p><p><strong>Obstetrics</strong></p><p>د طبي تخصص په توګه ورو ورو پراخ شو.</p><p>د دې تر څنګ:</p><p><strong>Midwifery</strong></p><p>هم په بېلابېلو هېوادونو کې د خپل مسلکي هویت د جوړولو په حال کې وه.</p><p>په ځینو ځایونو کې:</p><ul><li><p>قابله د نورمال زېږون پاملرنه کوله.</p></li><li><p>طبيب د پیچلو حالتونو لپاره کار کاوه.</p></li></ul><p>خو د هېوادونو ترمنځ سیستمونه ډېر توپیر درلودل.</p><hr><h1>۲۰. د ماشوم د زېږون وسایل</h1><h3 dir="rtl"></h3><p>د Obstetric Instruments په تاریخ کې <strong>Forceps</strong> ډېر مشهور دي.</p><p>Forceps د زېږون پر مهال د ماشوم د سر د مرستې لپاره ځانګړی وسیله ده چې په ځانګړو کلینیکي شرایطو کې کارول کېږي.</p><p>د دې وسایلو پرمختګ د زېږون په طبي مدیریت کې بدلون راوست.</p><p>خو:</p><blockquote><p>د هرې وسیلې کارول باید د مناسبې روزنې، کلینیکي اړتیا او خوندیتوب اصولو پر اساس وي.</p></blockquote><hr><h1>۲۱. Ignaz Semmelweis</h1><h3 dir="rtl"></h3><p>اوس د قابلګۍ د تاریخ له تر ټولو مهمو نومونو څخه یو:</p><h2>Ignaz Semmelweis</h2><h3 dir="rtl"></h3><p>په 19مه پېړۍ کې <strong>Ignaz Semmelweis</strong> د ماشوم زېږون وروسته د تبې یا:</p><p><strong>Puerperal Fever</strong></p><p>د زیاتې مړینې ستونزه مطالعه کړه.</p><p>هغه ولیدل چې د روغتیايي کارکوونکو د لاسونو پاکول د مور د انتاني ناروغۍ د کمېدو سره تړاو لري.</p><p>هغه د:</p><p><strong>Handwashing</strong></p><p>پر اهمیت ټینګار وکړ.</p><hr><h1>۲۲. ولې Semmelweis مهم دی؟</h1><h3 dir="rtl"></h3><p>نن موږ پوهېږو چې د لاسونو پاکوالی د Infection Prevention یوه اساسي برخه ده.</p><p>خو په هغه وخت کې د میکروبونو علم لا بشپړ نه و.</p><p>Semmelweis وښوده چې:</p><blockquote><p>د لاسونو پاکول کولی شي د مور د زېږون وروسته د شدیدې ناروغۍ او مړینې کچه کمه کړي.</p></blockquote><p>دا د قابلګۍ لپاره خورا مهم درس دی:</p><p><strong>Hygiene → Infection Prevention → Maternal Safety</strong></p><hr><h1>۲۳. Louis Pasteur او Germ Theory</h1><h3 dir="rtl"></h3><p>وروسته:</p><p><strong>Louis Pasteur</strong></p><p>او نورو ساینسپوهانو د:</p><p><strong>Germ Theory</strong></p><p>د پرمختګ لپاره مهم کارونه وکړل.</p><p>د دې له امله روغتیايي مسلکونه په دې ښه پوه شول چې کوچني مایکرو ارګانیزمونه د ډېرو ناروغیو په رامنځته کولو کې رول لري.</p><p>دا د:</p><ul><li><p>Sterilization</p></li><li><p>Hand Hygiene</p></li><li><p>Infection Prevention</p></li><li><p>Safe Delivery Practices</p></li></ul><p>لپاره لوی بدلون و.</p><hr><h1>۲۴. Florence Nightingale</h1><h3 dir="rtl"></h3><p><strong>Florence Nightingale</strong> د Nursing په تاریخ کې خورا مهمه څېره ده.</p><p>که څه هم هغه قابله نه وه، د هغې کار د روغتیايي پاملرنې په تاریخ کې مهم دی.</p><p>هغې پر:</p><ul><li><p>Hygiene</p></li><li><p>Clean environment</p></li><li><p>Observation</p></li><li><p>Documentation</p></li><li><p>Nursing education</p></li></ul><p>ټینګار وکړ.</p><p>د هغې نظریاتو د روغتیايي خدمتونو په مسلکي کېدو کې مهم اغېز درلود.</p><hr><h1>۲۵. د قابله‌ګۍ رسمي تعلیم</h1><h3 dir="rtl"></h3><p>د 19مې پېړۍ په پای او د 20مې پېړۍ په پیل کې په مختلفو هېوادونو کې د قابلو لپاره:</p><ul><li><p>رسمي ښوونځي</p></li><li><p>روزنیز پروګرامونه</p></li><li><p>امتحانات</p></li><li><p>ثبت/Registration</p></li><li><p>مسلکي معیارونه</p></li></ul><p>رامنځته شول.</p><p>دا یو ستر بدلون و.</p><p>پخوانۍ لړۍ:</p><p><strong>Experience → Tradition</strong></p><p>په تدریج سره داسې شوه:</p><p><strong>Education → Training → Assessment → Registration → Professional Practice</strong></p><hr><h1>۲۶. د 20مې پېړۍ بدلونونه</h1><h3 dir="rtl"></h3><p>په 20مه پېړۍ کې قابلګي د ساینس او عامې روغتیا له پرمختګ سره ډېره بدله شوه.</p><p>مهم پرمختګونه:</p><ul><li><p>Antenatal Care</p></li><li><p>Safer childbirth practices</p></li><li><p>Infection prevention</p></li><li><p>Antibiotics</p></li><li><p>Blood transfusion</p></li><li><p>Improved obstetric care</p></li><li><p>Newborn care</p></li><li><p>Maternal health programs</p></li><li><p>Professional midwifery education</p></li></ul><p>دا ټول د مور او ماشوم د خوندیتوب په ښه کېدو کې مهم وو.</p><hr><h1>۲۷. Antenatal Care</h1><h3 dir="rtl"></h3><p>د امیندوارۍ پاملرنه:</p><p><strong>Antenatal Care (ANC)</strong></p><p>ورو ورو د منظم روغتیايي خدمت یوه مهمه برخه شوه.</p><p>هدف یې دا و چې:</p><ul><li><p>د مور روغتیا وڅارل شي.</p></li><li><p>د امیندوارۍ پرمختګ وکتل شي.</p></li><li><p>خطرونه ژر وپېژندل شي.</p></li><li><p>روغتیايي مشوره ورکړل شي.</p></li><li><p>د مور او ماشوم لپاره مناسب پلان جوړ شي.</p></li></ul><p>دا د نننۍ قابلګۍ له مهمو برخو څخه ده.</p><hr><h1>۲۸. د نوي زېږېدلي ماشوم پاملرنه</h1><h3 dir="rtl"></h3><p>د وخت په تېرېدو:</p><p><strong>Newborn Care</strong></p><p>هم ډېر پرمختګ وکړ.</p><p>د نوي ماشوم لپاره:</p><ul><li><p>Temperature control</p></li><li><p>Breastfeeding support</p></li><li><p>Infection prevention</p></li><li><p>Assessment</p></li><li><p>Resuscitation skills</p></li></ul><p>او نورې برخې مهمې شوې.</p><p>قابلګي یوازې د مور تر پاملرنې محدود نه شوه؛ د مور او نوي ماشوم ګډه پاملرنه یې نوره هم پیاوړې شوه.</p><hr><h1>۲۹. WHO او نړیواله قابلګي</h1><h3 dir="rtl"></h3><p>په نړیواله کچه:</p><p><strong>World Health Organization (WHO)</strong></p><p>او نور نړیوال روغتیايي سازمانونه د مور او نوي زېږېدلي ماشوم د روغتیا لپاره مهم پروګرامونه او لارښوونې رامنځته کړي دي.</p><p>په معاصره دوره کې د قابلګۍ تمرکز پر:</p><ul><li><p>Quality of Care</p></li><li><p>Respectful Care</p></li><li><p>Evidence-Based Practice</p></li><li><p>Maternal and Newborn Safety</p></li><li><p>Skilled Birth Attendance</p></li><li><p>Continuity of Care</p></li></ul><p>زیات شوی دی.</p><hr><h1>۳۰. د معاصرې قابلګۍ فلسفه</h1><h3 dir="rtl"></h3><p>هغه څه چې په تېر درس کې مو زده کړل، د تاریخ له اوږده پرمختګ سره تړاو لري.</p><p>نننۍ قابلګي پر داسې مفاهیمو ولاړه ده:</p><p><strong>Woman-Centred Care</strong></p><p><strong>Respect</strong></p><p><strong>Dignity</strong></p><p><strong>Safety</strong></p><p><strong>Evidence-Based Practice</strong></p><p><strong>Continuity of Care</strong></p><p><strong>Informed Choice</strong></p><p><strong>Referral</strong></p><p>یعنې د زرګونو کلونو تجربې وروسته قابلګي یوازې د "زېږون مرسته" نه ده پاتې شوې.</p><p>دا یوه:</p><blockquote><p><strong>Professional Health Discipline</strong></p></blockquote><p>ګرځېدلې ده.</p><hr><h1>۳۱. د قابلګۍ د تاریخ عمومي Timeline</h1><h3 dir="rtl"></h3><p>د یادولو لپاره دا لړۍ ډېره مهمه ده:</p><h3>Ancient Communities</h3><h3 dir="rtl"></h3><p>دودیزه تجربه او د ښځو ترمنځ مرسته</p><p>↓</p><h3>Ancient Egypt</h3><h3 dir="rtl"></h3><p>د ښځینه روغتیا او زېږون اړوند پخوانۍ پوهه</p><p>↓</p><h3>Ancient Greece</h3><h3 dir="rtl"></h3><p>طبي فکر او د ښځینه روغتیا لیکنې</p><p>↓</p><h3>Roman Period</h3><h3 dir="rtl"></h3><p>Soranus او د Gynecology لیکنې</p><p>↓</p><h3>Middle Ages</h3><h3 dir="rtl"></h3><p>ټولنیزه/دودیزه قابلګي</p><p>↓</p><h3>Renaissance</h3><h3 dir="rtl"></h3><p>Anatomy او علمي مشاهده</p><p>↓</p><h3>17th–18th Centuries</h3><h3 dir="rtl"></h3><p>Obstetrics او مسلکي بدلونونه</p><p>↓</p><h3>19th Century</h3><h3 dir="rtl"></h3><p>Hygiene، Germ Theory او طبي پرمختګ</p><p>↓</p><h3>Early 20th Century</h3><h3 dir="rtl"></h3><p>Formal Midwifery Education</p><p>↓</p><h3>Modern Era</h3><h3 dir="rtl"></h3><p>Evidence-Based Professional Midwifery</p><hr><h1>۳۲. کلینیکي سناریو ۱ — پخوانۍ قابله</h1><h3 dir="rtl"></h3><p>تصور وکړئ چې زرګونه کاله مخکې یوه ښځه د زېږون درد لري.</p><p>یوه تجربه لرونکې ښځه ورسره مرسته کوي.</p><h3>پوښتنه</h3><h3 dir="rtl"></h3><p>ایا دا د نننۍ مسلکي قابلې په شان ده؟</p><p><strong>ځواب: نه په بشپړه توګه.</strong></p><h3>ولې؟</h3><h3 dir="rtl"></h3><p>ځکه نننۍ قابله:</p><ul><li><p>رسمي روزنه لري.</p></li><li><p>علمي پوهه لري.</p></li><li><p>مسلکي معیارونه لري.</p></li><li><p>د خطر نښې پېژني.</p></li><li><p>Evidence-Based Practice کاروي.</p></li><li><p>د Referral سیستم پېژني.</p></li></ul><h3>مهم درس</h3><h3 dir="rtl"></h3><p><strong>Traditional experience ≠ Modern professional midwifery</strong></p><hr><h1>۳۳. کلینیکي سناریو ۲ — د لاسونو پاکوالی</h1><h3 dir="rtl"></h3><p>تصور وکړئ چې د زېږون وروسته د میندو د تبې پېښې ډېرې دي.</p><p>که روغتیايي کارکوونکي د ناروغې له معاینې مخکې او وروسته خپل لاسونه په مناسب ډول پاک کړي، د Infection Transmission خطر کمېږي.</p><h3>تاریخي درس</h3><h3 dir="rtl"></h3><p>د Semmelweis کار موږ ته دا ښيي چې:</p><blockquote><p>یو ساده Infection Prevention Practice کولی شي د مور ژوند وژغوري.</p></blockquote><hr><h1>۳۴. کلینیکي سناریو ۳ — تجربه او علم</h1><h3 dir="rtl"></h3><p>یوه تجربه لرونکې ښځه وایي:</p><blockquote><p>"زه ۳۰ کاله د زېږون تجربه لرم، نو هر څه چې کوم، حتماً سم دي."</p></blockquote><p>ایا یوازې تجربه کافي ده؟</p><p><strong>نه.</strong></p><h3>ولې؟</h3><h3 dir="rtl"></h3><p>ځکه طبي او قابلګۍ علم د وخت په تېرېدو بدلېږي.</p><p>یو مسلکي روغتیايي کارکوونکی باید:</p><p><strong>Experience + Evidence + Training</strong></p><p>سره یو ځای وکاروي.</p><hr><h1>۳۵. کلینیکي سناریو ۴ — د قابلې مسلکي کېدل</h1><h3 dir="rtl"></h3><p>یوه ځوانه زده‌کوونکې د قابلګۍ رسمي پروګرام ته داخلېږي.</p><p>هغې زده کوي:</p><ul><li><p>Anatomy</p></li><li><p>Physiology</p></li><li><p>Pregnancy</p></li><li><p>Labour</p></li><li><p>Newborn Care</p></li><li><p>Infection Prevention</p></li><li><p>Communication</p></li><li><p>Ethics</p></li><li><p>Emergency Recognition</p></li></ul><h3>پوښتنه</h3><h3 dir="rtl"></h3><p>ولې دا ټول شیان زده کوي؟</p><p>ځکه نننۍ قابلګي یوازې د دودیزې تجربې پر بنسټ نه ده.</p><p>دا:</p><blockquote><p><strong>Knowledge + Skills + Professional Ethics</strong></p></blockquote><p>ته اړتیا لري.</p><hr><h1>۳۶. کلینیکي سناریو ۵ — د تاریخ او نننۍ قابلګۍ اړیکه</h1><h3 dir="rtl"></h3><p>یوه قابله نن په روغتیايي مرکز کې د امیندواره ښځې پاملرنه کوي.</p><p>هغه:</p><ul><li><p>Blood Pressure ارزوي.</p></li><li><p>د خطر نښې پوښتي.</p></li><li><p>روغتیايي مشوره ورکوي.</p></li><li><p>د جنین وضعیت ارزوي.</p></li><li><p>معلومات ثبتوي.</p></li><li><p>اړتیا وي Referral کوي.</p></li></ul><h3>پوښتنه</h3><h3 dir="rtl"></h3><p>ایا دا کارونه ناڅاپه رامنځته شوي؟</p><p><strong>نه.</strong></p><p>دا د څو پېړیو د:</p><p><strong>Medical Knowledge + Midwifery Experience + Public Health + Professional Education</strong></p><p>د پرمختګ پایله ده.</p><hr><h1>۳۷. د تاریخ له موږ څخه څه غواړي؟</h1><h3 dir="rtl"></h3><p>د قابلګۍ تاریخ درې لوی درسونه لري:</p><h3>۱. تجربه مهمه ده</h3><h3 dir="rtl"></h3><p>خو:</p><h3>۲. تجربه باید له علم سره یوځای شي.</h3><h3 dir="rtl"></h3><p>او:</p><h3>۳. علم باید د ښځې د خوندیتوب لپاره وکارول شي.</h3><h3 dir="rtl"></h3><p>نو:</p><blockquote><p><strong>Good Midwifery = Knowledge + Skills + Experience + Evidence + Compassion</strong></p></blockquote><hr><h1>۳۸. د قابلګۍ د پرمختګ لوی بدلون</h1><h3 dir="rtl"></h3><p>د تاریخ په اوږدو کې دا بدلون وګورئ:</p><h3>پخوا:</h3><h3 dir="rtl"></h3><p><strong>Traditional Knowledge</strong></p><p>↓</p><p><strong>Experience</strong></p><p>↓</p><p><strong>Home Birth Support</strong></p><hr><h3>وروسته:</h3><h3 dir="rtl"></h3><p><strong>Formal Education</strong></p><p>↓</p><p><strong>Clinical Training</strong></p><p>↓</p><p><strong>Professional Standards</strong></p><hr><h3>نن:</h3><h3 dir="rtl"></h3><p><strong>Evidence-Based Practice</strong></p><p>↓</p><p><strong>Woman-Centred Care</strong></p><p>↓</p><p><strong>Safe, Respectful, Professional Midwifery</strong></p><p>دا د دې درس تر ټولو مهم تاریخي مفهوم دی.</p><hr><h1>۳۹. مهم تاریخي شخصیتونه</h1><h3 dir="rtl"></h3><table><thead><tr><th>شخصیت</th><th>تاریخي اهمیت</th></tr></thead><tbody><tr><td>Hippocrates</td><td>د لرغوني طب مهم شخصیت</td></tr><tr><td>Soranus of Ephesus</td><td>د Gynecology او ښځینه روغتیا مهم تاریخي لیکوال</td></tr><tr><td>Andreas Vesalius</td><td>د Anatomy د علم مهم پرمختګ</td></tr><tr><td>Ignaz Semmelweis</td><td>د Hand Hygiene او puerperal infection د مخنیوي تاریخي اهمیت</td></tr><tr><td>Louis Pasteur</td><td>Germ Theory ته مهم علمي بنسټ</td></tr><tr><td>Florence Nightingale</td><td>د Nursing، Hygiene او مسلکي روغتیايي پاملرنې مهم پرمختګ</td></tr></tbody></table><p><strong>مهم:</strong> Florence Nightingale قابله نه وه؛ د هغې ونډه د Nursing په تاریخ کې ده، خو د روغتیايي پاملرنې د مسلکي کېدو لپاره یې پراخ اغېز درلود.</p><hr><h1>۴۰. د قابلګۍ تاریخ مهم اصطلاحات</h1><h3 dir="rtl"></h3><table><thead><tr><th>پښتو</th><th>English</th><th>ساده تشریح</th></tr></thead><tbody><tr><td>تاریخ</td><td>History</td><td>د تېر پرمختګ مطالعه</td></tr><tr><td>قابلګي</td><td>Midwifery</td><td>د ښځو او میندو اړوند مسلکي رشته</td></tr><tr><td>قابله</td><td>Midwife</td><td>مسلکي قابلګۍ کارکوونکې</td></tr><tr><td>دودیزه قابلګي</td><td>Traditional Midwifery</td><td>د تجربې او دود پر بنسټ پاملرنه</td></tr><tr><td>عصري قابلګي</td><td>Modern Midwifery</td><td>علمي او مسلکي قابلګي</td></tr><tr><td>زېږون</td><td>Childbirth</td><td>د ماشوم د زېږېدو پروسه</td></tr><tr><td>طب</td><td>Medicine</td><td>د روغتیا او ناروغۍ علم</td></tr><tr><td>ولادي طب</td><td>Obstetrics</td><td>د امیندوارۍ، زېږون او اړوندو پیچلتیاوو طبي تخصص</td></tr><tr><td>ښځینه ناروغۍ</td><td>Gynecology</td><td>د ښځینه تولیدي سیستم روغتیا</td></tr><tr><td>حفظ‌الصحې</td><td>Hygiene</td><td>د پاکوالي او انتان مخنیوي اصول</td></tr><tr><td>انتان</td><td>Infection</td><td>د مایکرو ارګانیزمونو له امله ناروغي</td></tr><tr><td>د لاسونو پاکوالی</td><td>Hand Hygiene</td><td>د انتان د انتقال د کمولو مهم اقدام</td></tr><tr><td>شواهد</td><td>Evidence</td><td>علمي معلومات چې د پریکړو ملاتړ کوي</td></tr><tr><td>مسلکي روزنه</td><td>Professional Training</td><td>رسمي علمي او عملي تعلیم</td></tr><tr><td>ثبت</td><td>Registration</td><td>د مسلک رسمي ثبت</td></tr><tr><td>د پاملرنې کیفیت</td><td>Quality of Care</td><td>د روغتیايي خدمت د کیفیت معیار</td></tr><tr><td>د مور مړینه</td><td>Maternal Mortality</td><td>د امیندوارۍ یا زېږون اړوند د مور مړینه</td></tr></tbody></table><hr><h1>۴۱. Individual Online Activity</h1><h3 dir="rtl"></h3><p>ستاسو د آنلاین LMS لپاره دا فعالیت مناسب دی:</p><h2>Activity: Build the Midwifery Timeline</h2><h3 dir="rtl"></h3><p>زده‌کوونکې ته لاندې کارتونه ګډ ورکړئ:</p><ul><li><p>Ancient Communities</p></li><li><p>Ancient Egypt</p></li><li><p>Ancient Greece</p></li><li><p>Roman Period</p></li><li><p>Middle Ages</p></li><li><p>Renaissance</p></li><li><p>17th–18th Centuries</p></li><li><p>19th Century</p></li><li><p>20th Century</p></li><li><p>Modern Midwifery</p></li></ul><p>زده‌کوونکې باید هغوی په تاریخي ترتیب کې تنظیم کړي.</p><h3>دوهم فعالیت</h3><h3 dir="rtl"></h3><p>د شخصیتونو او ونډو Matching:</p><p><strong>Soranus</strong></p><p>→ Gynecology</p><p><strong>Semmelweis</strong></p><p>→ Hand Hygiene / Puerperal Fever prevention</p><p><strong>Vesalius</strong></p><p>→ Anatomy</p><p><strong>Pasteur</strong></p><p>→ Germ Theory</p><p><strong>Nightingale</strong></p><p>→ Nursing / Hygiene / Professional healthcare</p><hr><h1>۴۲. د زده‌کوونکې لپاره مهمې غلط فهمۍ</h1><h3>غلط فهمي ۱</h3><h3 dir="rtl"></h3><p>"قابلګي د 19مې پېړۍ په وخت کې پیدا شوې."</p><p>❌ غلط.</p><p>قابلګي له پخوانیو انساني ټولنو سره تړلی اوږد تاریخ لري.</p><hr><h3>غلط فهمي ۲</h3><h3 dir="rtl"></h3><p>"پخوانۍ قابله هېڅ علم نه درلود."</p><p>دا هم ډېر ساده بیان دی.</p><p>هغوی د خپلې زمانې د:</p><ul><li><p>تجربې</p></li><li><p>مشاهدې</p></li><li><p>دودیزې پوهې</p></li></ul><p>پر بنسټ معلومات لرل.</p><p>خو دا د نن ورځې له <strong>scientific evidence-based education</strong> سره یو شان نه وو.</p><hr><h3>غلط فهمي ۳</h3><h3 dir="rtl"></h3><p>"Florence Nightingale قابله وه."</p><p>❌ نه.</p><p>هغه د Nursing په تاریخ کې مهمه څېره وه.</p><hr><h3>غلط فهمي ۴</h3><h3 dir="rtl"></h3><p>"Semmelweis د قابلګۍ بنسټ ایښودونکی و."</p><p>❌ نه.</p><p>هغه د طبي تاریخ مهم شخصیت و چې د لاسونو پاکوالي او د puerperal fever د کمولو په برخه کې یې مهم کار وکړ.</p><hr><h1>۴۳. Assessment</h1><h2>Multiple Choice — Single Answer</h2><h3>۱. قابلګي په اصل کې کله پیل شوه؟</h3><h3 dir="rtl"></h3><p>A. یوازې په 20مه پېړۍ کې<br>B. یوازې د روغتونونو له جوړېدو وروسته<br>C. د انساني ټولنو له لومړنیو وختونو سره تړلې ده<br>D. یوازې د Florence Nightingale وروسته</p><p><strong>صحیح ځواب: C</strong></p><p><strong>تشریح:</strong> د زېږون پر مهال د تجربه لرونکو ښځو مرسته له پخوانیو انساني ټولنو سره تړلې ده.</p><hr><h3>۲. Soranus of Ephesus د څه لپاره مهم دی؟</h3><h3 dir="rtl"></h3><p>A. Anatomy<br>B. Gynecology<br>C. Germ Theory<br>D. Nursing</p><p><strong>صحیح ځواب: B</strong></p><p><strong>تشریح:</strong> Soranus د ښځینه روغتیا او Gynecology په اړه مهم تاریخي لیکنې لري.</p><hr><h3>۳. Semmelweis د څه اهمیت څرګند کړ؟</h3><h3 dir="rtl"></h3><p>A. Anatomy<br>B. Hand Hygiene<br>C. Ultrasound<br>D. Caesarean section</p><p><strong>صحیح ځواب: B</strong></p><p><strong>تشریح:</strong> د هغه کار د لاسونو پاکوالي او د puerperal fever د کمولو له اهمیت سره تړاو لري.</p><hr><h3>۴. Vesalius په کوم علم کې مهم شخصیت دی؟</h3><h3 dir="rtl"></h3><p>A. Anatomy<br>B. Psychology<br>C. Pharmacy<br>D. Midwifery education</p><p><strong>صحیح ځواب: A</strong></p><hr><h3>۵. د عصري قابلګۍ مهمه ځانګړتیا کومه ده؟</h3><h3 dir="rtl"></h3><p>A. یوازې دود<br>B. یوازې تجربه<br>C. Evidence-Based Practice<br>D. یوازې شفاهي معلومات</p><p><strong>صحیح ځواب: C</strong></p><hr><h1>۴۴. True / False</h1><h3>۶. قابلګي له رسمي روغتیايي ښوونځیو څخه مخکې هم موجوده وه.</h3><h3 dir="rtl"></h3><p><strong>True ✅</strong></p><p><strong>تشریح:</strong> د زېږون دودیزه مرسته له پخوانیو ټولنو سره تړاو لري.</p><hr><h3>۷. Florence Nightingale قابله وه.</h3><h3 dir="rtl"></h3><p><strong>False ❌</strong></p><p><strong>تشریح:</strong> هغه د Nursing په تاریخ کې مهمه څېره وه، نه قابله.</p><hr><h3>۸. Semmelweis د لاسونو پاکوالي پر اهمیت ټینګار وکړ.</h3><h3 dir="rtl"></h3><p><strong>True ✅</strong></p><p><strong>تشریح:</strong> د هغه کار د puerperal fever د کمولو له لارې د Hand Hygiene اهمیت وښود.</p><hr><h1>۴۵. Short Answer</h1><h3>۹. Traditional Midwifery او Modern Midwifery کې یو مهم توپیر ولیکئ.</h3><h3 dir="rtl"></h3><p><strong>نمونوي ځواب:</strong></p><p>Traditional Midwifery تر ډېره د تجربې او دود پر بنسټ وه، خو Modern Midwifery پر رسمي تعلیم، عملي روزنه، مسلکي معیارونو، شواهدو او Evidence-Based Practice ولاړه ده.</p><hr><h3>۱۰. ولې د قابلګۍ تاریخ د یوې قابله لپاره مهم دی؟</h3><h3 dir="rtl"></h3><p><strong>نمونوي ځواب:</strong></p><p>ځکه د قابلګۍ تاریخ موږ سره مرسته کوي چې پوه شو دا مسلک څنګه له دودیزې تجربې څخه یوې علمي، مسلکي، شواهدو پر بنسټ او د مور او ماشوم د خوندیتوب پر محور روغتیايي رشتې ته وده کړې.</p><hr><h1>۴۶. جامع کلینیکي سناریو</h1><h3 dir="rtl"></h3><p>یوه قابله نن په روغتیايي مرکز کې یوه امیندواره ښځه ګوري.</p><p>هغه:</p><ul><li><p>د ښځې روغتیا ارزوي.</p></li><li><p>د خطر نښې پوښتي.</p></li><li><p>د Hygiene اصول مراعاتوي.</p></li><li><p>معلومات ثبتوي.</p></li><li><p>ښځې ته روغتیايي مشوره ورکوي.</p></li><li><p>د ښځې محرمیت ساتي.</p></li><li><p>د اړتیا په وخت کې Referral کوي.</p></li></ul><h3>پوښتنه ۱</h3><h3 dir="rtl"></h3><p>ایا دا د دودیزې قابلګۍ او عصري قابلګۍ ترمنځ توپیر ښيي؟</p><p><strong>هو.</strong></p><h3>پوښتنه ۲</h3><h3 dir="rtl"></h3><p>ولې؟</p><p>ځکه عصري قابله یوازې پر شخصي تجربه تکیه نه کوي.</p><p>هغه کاروي:</p><p><strong>Education + Clinical Skills + Evidence + Professional Ethics</strong></p><h3>پوښتنه ۳</h3><h3 dir="rtl"></h3><p>د Semmelweis له تاریخ څخه څه زده کوو؟</p><p><strong>Hand Hygiene او Infection Prevention د مور د خوندیتوب لپاره مهم دي.</strong></p><h3>پوښتنه ۴</h3><h3 dir="rtl"></h3><p>د Soranus تاریخي اهمیت څه دی؟</p><p>هغه د ښځینه روغتیا او Gynecology په اړه د لرغوني وخت له مهمو طبي لیکوالانو څخه دی.</p><h3>پوښتنه ۵</h3><h3 dir="rtl"></h3><p>د تاریخ تر ټولو لوی درس څه دی؟</p><blockquote><p><strong>قابلګي تل د بدلون په حال کې ده، او مسلکي قابله باید له علم سره یوځای په دوامداره توګه خپله پوهه او مهارتونه تازه کړي.</strong></p></blockquote><hr><h1>۴۷. د درس وروستۍ خلاصه</h1><h3 dir="rtl"></h3><p>د قابلګۍ تاریخ په یوه کرښه کې:</p><blockquote><p><strong>Traditional Birth Support → Experience → Medical Knowledge → Formal Education → Professional Regulation → Evidence-Based Midwifery</strong></p></blockquote><p>یعنې:</p><p><strong>دودیزه مرسته</strong></p><p>↓</p><p><strong>تجربه</strong></p><p>↓</p><p><strong>علمي پوهه</strong></p><p>↓</p><p><strong>رسمي تعلیم</strong></p><p>↓</p><p><strong>مسلکي تنظیم</strong></p><p>↓</p><p><strong>د شواهدو پر بنسټ عصري قابلګي</strong></p><hr><h1>۴۸. د زده‌کوونکې لپاره د یادولو ۱۰ مهم ټکي</h1><h3 dir="rtl"><ol><li><p>قابلګي ډېر پخوانی مسلک دی.</p></li><li><p>لومړنۍ قابلګي تر ډېره د تجربې او دود پر بنسټ وه.</p></li><li><p>لرغوني مصر د ښځینه روغتیا او زېږون اړوند تاریخي معلومات لري.</p></li><li><p>Soranus د Gynecology په تاریخ کې مهم دی.</p></li><li><p>Renaissance د Anatomy علم پیاوړی کړ.</p></li><li><p>Vesalius د Anatomy په پرمختګ کې مهم رول لري.</p></li><li><p>Semmelweis د Hand Hygiene اهمیت وښود.</p></li><li><p>Germ Theory د Infection Prevention پوهه پیاوړې کړه.</p></li><li><p>Formal Midwifery Education د قابلګۍ د مسلکي کېدو لپاره مهمه شوه.</p></li><li><p>نننۍ قابلګي پر <strong>Evidence, Safety, Respect, Skills and Professional Ethics</strong> ولاړه ده.</p></li></ol><hr></h3><h1>۴۹. د استاد وروستی پیغام</h1><h3 dir="rtl"></h3><p>ګرانو زده‌کوونکو!</p><p>کله چې تاسو د قابلګۍ سپین لباس اغوندئ، یوازې د یوې دندې پیل نه کوئ؛ تاسو د یوه <strong>ډېر اوږد تاریخي مسلک</strong> برخه ګرځئ.</p><p>له هغو تجربه لرونکو ښځو څخه چې زرګونه کاله مخکې به یې د زېږون پر مهال له نورو ښځو سره مرسته کوله، تر نننۍ هغې مسلکي قابلې پورې چې:</p><ul><li><p>Anatomy زده کوي،</p></li><li><p>Physiology زده کوي،</p></li><li><p>د خطر نښې پېژني،</p></li><li><p>Evidence-Based Practice کاروي،</p></li><li><p>د Infection Prevention اصول مراعاتوي،</p></li><li><p>د ښځې عزت ساتي،</p></li><li><p>د مور او ماشوم خوندیتوب ته لومړیتوب ورکوي،</p></li></ul><p>قابلګي په اوږده لاره کې بدله شوې ده.</p><p>خو د دې مسلک یو بنسټیز هدف لا هم هماغه دی:</p><blockquote><p><strong>د ښځې او ماشوم د روغتیا، خوندیتوب، عزت او هوساینې لپاره مسلکي پاملرنه.</strong></p></blockquote><p>او د یوې راتلونکې قابلې لپاره تر ټولو مهم پیغام:</p><blockquote><p><strong>"د پخوانیو نسلونو تجربه زده کړه، د نن ورځې علم درک کړه، او د راتلونکو میندو لپاره لا ښه مسلکي پاملرنه رامنځته کړه."</strong></p></blockquote>', 'rtl', 'none', NULL, NULL, 26, 'intro', 5, TRUE, 2, TRUE, '2026-09-13 04:39:29'),
(370, 34, 'قابلګي په افغانستان کې', '<p dir="rtl" style="text-align:right">په افغانستان کې قابلګي د مور او ماشوم د مړینې په کمولو کې کلیدي رول لري.</p>', '<h3 dir="rtl" style="text-align:right"></h3><p>هو. د تېر درس <strong>«د قابلګي تاریخ په نړۍ کې»</strong> وروسته، بل مناسب درس دا دی چې زده‌کوونکي پوه شي چې قابلګي څنګه په افغانستان کې رامنځته شوه، څنګه یې مسلکي بڼه واخیسته، او نننۍ قابلې کوم ځای لري.</p><h1>درس: قابلګي په افغانستان کې</h1><h3>Midwifery in Afghanistan</h3><h3 dir="rtl"></h3><p><strong>کچه:</strong> د قابلګۍ لومړی سمستر – مبتدي زده‌کوونکي<br><strong>د درس موده:</strong> ۶۰ دقیقې<br><strong>د درس ډول:</strong> آنلاین انفرادي زده‌کړه</p><hr><h2>🎯 د درس موخې</h2><h3 dir="rtl"></h3><p>د دې درس تر پای پورې به زده‌کوونکی وکولای شي:</p><ol><li><p>په افغانستان کې د قابلګۍ د تاریخي پرمختګ مهم پړاوونه تشریح کړي.</p></li><li><p>د عنعنوي قابلې او مسلکي قابلې ترمنځ توپیر بیان کړي.</p></li><li><p>تشریح کړي چې ولې په افغانستان کې مسلکي قابلو ته اړتیا زیاته ده.</p></li><li><p>د قابلې د زده‌کړې او مسلکي روزنې اهمیت درک کړي.</p></li><li><p>د افغانستان په روغتیايي سیستم کې د قابلې مهم رولونه وپېژني.</p></li><li><p>د میندو او نویو زېږېدلو ماشومانو د روغتیا په برخه کې د قابلې ونډه تشریح کړي.</p></li><li><p>د کلتوري درناوي، خوندي زېږون، راجع کولو (Referral) او مسلکي اخلاقو اهمیت درک کړي.</p></li></ol><hr><h1>۱. د درس پیل – یوه مهمه پوښتنه</h1><h3 dir="rtl"></h3><p>راځئ له یوې ساده پوښتنې څخه شروع وکړو:</p><p><strong>که یوه ښځه په یوه لرې کلي کې د زېږون دردونه ولري، خو روغتون ورته ډېر لرې وي، نو څوک باید ورسره مرسته وکړي؟</strong></p><p>په افغانستان کې د تاریخ په اوږدو کې ډېری وخت د ښځې تر څنګ یوه تجربه لرونکې ښځه موجوده وه چې د زېږون په وخت کې به یې مرسته کوله.</p><p>دې ښځې ته په بېلابېلو سیمو کې د <strong>دودیزې قابلې (Traditional Birth Attendant)</strong> په توګه کتل کېدل.</p><p>خو دلته یو مهم ټکی دی:</p><blockquote><p><strong>تجربه مهمه ده، خو یوازې تجربه د مسلکي روغتیايي خدمت بدیل نه شي کېدای.</strong></p></blockquote><p>همدا اړتیا وه چې د قابلګۍ زده‌کړه په تدریجي ډول له دودیزې تجربې څخه <strong>رسمي، علمي او مسلکي زده‌کړې</strong> ته ولاړه شي.</p><hr><h1>۲. په افغانستان کې پخوانۍ دودیزه قابلګي</h1><h3 dir="rtl"></h3><p>د مسلکي ښوونځیو او روغتیايي مرکزونو له پراختیا څخه مخکې، د افغانستان په ډېرو ټولنو کې زېږون عموماً په کور کې ترسره کېده.</p><p>یوه تجربه لرونکې ښځه به:</p><ul><li><p>د امیندواره ښځې سره وه؛</p></li><li><p>د زېږون پر مهال به یې مرسته کوله؛</p></li><li><p>د مور د حالت څارنه به یې کوله؛</p></li><li><p>د نوي ماشوم لومړنۍ پاملرنه به یې کوله؛</p></li><li><p>د خپلې تجربې له لارې به یې نورو ښځو ته زده‌کړه ورکوله.</p></li></ul><p>دا پوهه ډېری وخت د:</p><p><strong>تجربې → مشاهده → تمرین → د نسلونو انتقال</strong></p><p>له لارې انتقالېدله.</p><h3>خو ستونزه څه وه؟</h3><h3 dir="rtl"></h3><p>د هغه وخت په دودیزه پاملرنه کې د لاندې حالتونو د علمي پېژندنې او مدیریت امکانات محدود وو:</p><ul><li><p>شدید خونریزي (Severe Bleeding)</p></li><li><p>د وینې لوړ فشار او پری‌اکلامپسیا (Preeclampsia)</p></li><li><p>اوږد یا ستونزمن زېږون (Prolonged/Obstructed Labour)</p></li><li><p>انتان (Infection)</p></li><li><p>د نوي ماشوم د تنفس ستونزه (Newborn Respiratory Problem)</p></li></ul><p>نو کله چې جدي عارضه رامنځته شوه، د مناسبې مرستې تر لاسه کول ډېر ستونزمن کېدل.</p><hr><h1>۳. له دودیزې قابلګۍ څخه مسلکي قابلګۍ ته</h1><h3 dir="rtl"></h3><p>د روغتیايي خدمتونو د پراختیا سره، په افغانستان کې اړتیا پیدا شوه چې ښځې د قابلګۍ په برخه کې <strong>رسمي او علمي زده‌کړه</strong> ترلاسه کړي.</p><p>د مسلکي قابلګۍ په زده‌کړه کې یوازې د ماشوم زېږولو طریقه نه زده کېږي.</p><p>زده‌کوونکې قابله زده کوي چې:</p><ul><li><p>د امیندوارۍ څارنه وکړي؛</p></li><li><p>د مور حیاتي نښې (Vital Signs) وارزوي؛</p></li><li><p>د جنین حالت وڅاري؛</p></li><li><p>د زېږون پرمختګ تعقیب کړي؛</p></li><li><p>د خطر نښې وپېژني؛</p></li><li><p>د نوي زېږېدلي ماشوم لومړنۍ پاملرنه وکړي؛</p></li><li><p>د مور له زېږون وروسته پاملرنه وکړي؛</p></li><li><p>روغتیايي مشوره ورکړي؛</p></li><li><p>او د خطر په وخت کې ښځه مناسب مرکز ته راجع کړي.</p></li></ul><hr><h1>۴. په افغانستان کې د قابلګۍ د مسلکي کېدو اهمیت</h1><h3 dir="rtl"></h3><p>افغانستان یو داسې هېواد دی چې:</p><ul><li><p>غرني او لرې پراته سیمې لري؛</p></li><li><p>په ځینو سیمو کې روغتیايي مرکزونو ته لاسرسی محدود دی؛</p></li><li><p>د مسلکي روغتیايي کارکوونکو اړتیا زیاته ده؛</p></li><li><p>د میندو او نویو زېږېدلو ماشومانو روغتیا د عامې روغتیا مهمه موضوع ده.</p></li></ul><p>له همدې امله <strong>قابله (Midwife)</strong> یوازې د زېږون پر مهال مرسته کوونکې نه ده.</p><p>قابله د ښځې لپاره د روغتیايي خدمتونو په یوه مهمه مرحله کې <strong>مسلکي ملاتړ کوونکې</strong> ده.</p><hr><h1>۵. د افغانستان د قابلې مهم رول</h1><h3 dir="rtl"></h3><p>یوه مسلکي قابله کولای شي د ښځې د روغتیا په بېلابېلو پړاوونو کې رول ولري.</p><h3>① د امیندوارۍ پاملرنه</h3><h3 dir="rtl"></h3><p><strong>Antenatal Care (ANC)</strong></p><p>قابله د امیندوارې ښځې وضعیت ارزوي او د امیندوارۍ د خطر نښې پېژني.</p><p>مثلاً:</p><blockquote><p>یوه امیندواره ښځه د شدید سر درد او د سترګو د لید د خرابوالي شکایت کوي.</p></blockquote><p>قابله باید پوه شي چې دا ډول نښې د جدي حالت نښه کېدای شي او باید د مناسبې طبي ارزونې لپاره اقدام وشي.</p><hr><h3>② د زېږون پاملرنه</h3><h3 dir="rtl"></h3><p><strong>Labour and Birth Care</strong></p><p>قابله د زېږون پر مهال:</p><ul><li><p>مور څاري؛</p></li><li><p>د زېږون پرمختګ ارزوي؛</p></li><li><p>د مور او جنین وضعیت څاري؛</p></li><li><p>د انتان د مخنیوي اصول مراعاتوي؛</p></li><li><p>او د اړتیا په وخت کې مرسته غواړي یا راجع کوي.</p></li></ul><hr><h3>③ د زېږون وروسته پاملرنه</h3><h3 dir="rtl"></h3><p><strong>Postnatal Care (PNC)</strong></p><p>د ماشوم له زېږېدو سره د قابلې کار پای ته نه رسېږي.</p><p>قابله باید د مور او ماشوم حالت وڅاري.</p><p>د مور لپاره:</p><ul><li><p>خونریزي</p></li><li><p>حیاتي نښې</p></li><li><p>درد</p></li><li><p>د انتان نښې</p></li><li><p>د شیدو ورکولو ستونزې</p></li></ul><p>او د ماشوم لپاره:</p><ul><li><p>تنفس</p></li><li><p>د بدن تودوخه</p></li><li><p>تغذیه</p></li><li><p>عمومي وضعیت</p></li></ul><p>مهم دي.</p><hr><h1>۶. قابله او کلتور</h1><h3 dir="rtl"></h3><p>په افغانستان کې د قابلې لپاره یوازې طبي پوهه کافي نه ده.</p><p>قابله باید د ټولنې:</p><ul><li><p>کلتور</p></li><li><p>دودونه</p></li><li><p>د کورنۍ جوړښت</p></li><li><p>د ښځو محرمیت</p></li><li><p>ژبه</p></li><li><p>ټولنیز حساسیتونه</p></li></ul><p>په درناوي سره درک کړي.</p><h3>خو مهم اصل:</h3><h3 dir="rtl"></h3><p><strong>کلتور ته درناوی ≠ د خطرناک عمل منل</strong></p><p>مثلاً که یوه کورنۍ داسې دود ولري چې د شدیدې خونریزۍ پر مهال روغتون ته تګ ځنډوي، قابله باید په درناوي او مسلکي ډول د ژر طبي مرستې اهمیت تشریح کړي.</p><hr><h1>۷. یوه مهمه موضوع: Referral</h1><h3 dir="rtl"></h3><p>په افغانستان کې د قابلې لپاره د <strong>Referral – راجع کولو</strong> مفهوم ډېر مهم دی.</p><p>فرض کړئ قابله یوه ښځه معاینه کوي او داسې نښې ویني چې د هغې د مسلکي صلاحیت څخه بهر جدي ارزونې ته اړتیا لري.</p><p>ښه قابله نه وایي:</p><blockquote><p>«زه هر څه پخپله کولی شم.»</p></blockquote><p>بلکې وایي:</p><blockquote><p><strong>«دا حالت تخصصي ارزونې ته اړتیا لري.»</strong></p></blockquote><p>او ښځه مناسب روغتیايي مرکز ته راجع کوي.</p><h3>دا کمزوري نه ده.</h3><h3 dir="rtl"></h3><p><strong>Referral د مسلکي وړتیا یوه مهمه برخه ده.</strong></p><hr><h1>۸. له دودیزې قابلې او مسلکي قابلې سره پرتله</h1><h3 dir="rtl"></h3><table><thead><tr><th>ځانګړنه</th><th>دودیزه قابله</th><th>مسلکي قابله</th></tr></thead><tbody><tr><td>د پوهې سرچینه</td><td>تجربه او دود</td><td>علمي زده‌کړه + عملي روزنه</td></tr><tr><td>رسمي تحصیلي پروګرام</td><td>عموماً نه</td><td>هو</td></tr><tr><td>علمي ارزونه</td><td>محدوده</td><td>منظمه</td></tr><tr><td>د خطر نښو پېژندنه</td><td>ممکن محدوده وي</td><td>مسلکي روزنه لري</td></tr><tr><td>مستند کول</td><td>محدود</td><td>مسلکي Documentation</td></tr><tr><td>Referral</td><td>ممکن محدود</td><td>د مسلکي کار مهمه برخه</td></tr><tr><td>Evidence-based Practice</td><td>محدوده</td><td>مهم اصل</td></tr><tr><td>د روغتیايي ټیم سره همکاري</td><td>محدوده</td><td>مهمه</td></tr></tbody></table><h3>مهمه خبره</h3><h3 dir="rtl"></h3><p>موږ باید د پخوانیو دودیزو قابلو تجربه بې‌ارزښته ونه بولو.</p><p>هغوی د خپلو ټولنو لپاره مهم رول درلود.</p><p>خو:</p><p><strong>Traditional Knowledge ≠ Modern Professional Midwifery</strong></p><hr><h1>۹. سناریو ۱ – دودیزه تجربه او علمي پوهه</h1><h3>سناریو</h3><h3 dir="rtl"></h3><p>یوه تجربه لرونکې ښځه وايي:</p><blockquote><p>«ما شل کاله ښځو سره زېږونونه کړي، نو زه د هرې ستونزې درملنه کولی شم.»</p></blockquote><h3>پوښتنه:</h3><h3 dir="rtl"></h3><p>ایا یوازې شل کلنه تجربه دا معنا لري چې هغه د هرې طبي ستونزې د مدیریت لپاره مسلکي صلاحیت لري؟</p><h3>صحیح ځواب:</h3><h3 dir="rtl"></h3><p><strong>نه.</strong></p><h3>علمي تشریح:</h3><h3 dir="rtl"></h3><p>تجربه ارزښت لري، خو مسلکي قابلګي د:</p><p><strong>علمي پوهې + عملي مهارت + مسلکي معیارونو + شواهدو + د خطر پېژندنې + Referral</strong></p><p>ترکیب دی.</p><h3>د قابلې لپاره درس:</h3><h3 dir="rtl"></h3><p><strong>Experience is valuable, but experience alone is not enough.</strong></p><hr><h1>۱۰. سناریو ۲ – د افغانستان په لرې سیمه کې امیندواره ښځه</h1><h3 dir="rtl"></h3><p>یوه ښځه په یوه لرې سیمه کې ده.</p><p>د زېږون پر مهال یې:</p><ul><li><p>شدید کمزوري؛</p></li><li><p>د هوښیارۍ د کمېدو نښې؛</p></li><li><p>او زیاته وینه بهېدنه</p></li></ul><p>پیل شوې ده.</p><h3>قابله څه باید وکړي؟</h3><h3 dir="rtl"></h3><p>قابله باید وضعیت جدي وګڼي، لومړنۍ مناسبه مرسته د خپل مسلکي صلاحیت مطابق ترسره کړي او <strong>د عاجلې طبي مرستې/Referral</strong> لپاره اقدام وکړي.</p><h3>مهم درس:</h3><h3 dir="rtl"><blockquote><p>قابله باید خطر وپېژني، وخت ضایع نه کړي، او مناسب Referral ترسره کړي.</p></blockquote><hr></h3><h1>۱۱. سناریو ۳ – کلتوري درناوی</h1><h3 dir="rtl"></h3><p>یوه کورنۍ غواړي چې یوه امیندواره ښځه د زېږون پر مهال یوازې ښځینه روغتیايي کارکوونکي ولري.</p><h3>قابله څه کوي؟</h3><h3 dir="rtl"></h3><p>د ښځې غوښتنې، محرمیت او کلتوري حساسیت ته درناوی کوي، تر هغه چې دا کار د خوندي روغتیايي خدمتونو له اصولو سره ټکر ونه لري.</p><h3>مهم درس:</h3><h3 dir="rtl"></h3><p><strong>Respectful Care</strong> د مسلکي قابلګۍ یوه مهمه برخه ده.</p><hr><h1>۱۲. سناریو ۴ – قابله د ښوونکې په توګه</h1><h3 dir="rtl"></h3><p>یوه نوې مور وايي:</p><blockquote><p>«زه فکر کوم چې د ماشوم لپاره زما شیدې کافي نه دي.»</p></blockquote><p>قابله یوازې دا نه وايي:</p><blockquote><p>«شیدې ورکړه.»</p></blockquote><p>بلکې:</p><ul><li><p>د مور اندېښنه اوري؛</p></li><li><p>د شیدو ورکولو وضعیت ارزوي؛</p></li><li><p>مناسبه مشوره ورکوي؛</p></li><li><p>د ماشوم د تغذیې اړوند مهمې نښې تشریح کوي؛</p></li><li><p>او د اړتیا په صورت کې اضافي مرسته برابروي.</p></li></ul><h3>مهم درس:</h3><h3 dir="rtl"></h3><p>قابله یوازې <strong>Care Provider</strong> نه ده؛</p><p>بلکې <strong>Health Educator</strong> هم ده.</p><hr><h1>۱۳. د افغانستان د قابلې دندې یوازې زېږون نه دی</h1><h3 dir="rtl"></h3><p>دا جمله حتماً په یاد وساتئ:</p><blockquote><p><strong>Midwifery is not only about childbirth.</strong></p></blockquote><p>قابله کولی شي په لاندې برخو کې رول ولري:</p><p><strong>Pregnancy → Labour → Birth → Postnatal Care → Newborn Care → Health Education → Counselling → Referral</strong></p><hr><h1>💻 آنلاین انفرادي فعالیت</h1><h2>Activity: «قابله څه باید وکړي؟»</h2><h3 dir="rtl"></h3><p>په LMS کې زده‌کوونکي ته ۵ سناریوګانې وړاندې کړئ.</p><p>د هرې سناریو لپاره درې انتخابونه:</p><p><strong>A.</strong> حالت له پامه غورځول<br><strong>B.</strong> مناسب ارزونه او اقدام کول<br><strong>C.</strong> یوازې کورنۍ ته پرېښودل</p><p>زده‌کوونکی باید مناسب انتخاب وکړي او وروسته سیستم ورته <strong>تشریح (Explanation)</strong> ښکاره کړي.</p><h3>بېلګه:</h3><h3 dir="rtl"></h3><p><strong>یوه امیندواره ښځه شدید سر درد او د لید ستونزه لري.</strong></p><p>زده‌کوونکی: <strong>B</strong></p><p>سیستم:</p><blockquote><p>صحیح ځواب. شدید سر درد او د لید ستونزه د امیندوارۍ د جدي عارضې له نښو څخه کېدای شي. قابله باید حالت وارزوي او د اړتیا په صورت کې د عاجلې طبي ارزونې لپاره Referral وکړي.</p></blockquote><hr><h1>📚 مهمې اصطلاحات</h1><h3 dir="rtl"></h3><table><thead><tr><th>پښتو</th><th>English</th><th>ساده تشریح</th></tr></thead><tbody><tr><td>قابله</td><td>Midwife</td><td>مسلکي روغتیايي کارکوونکې</td></tr><tr><td>قابلګي</td><td>Midwifery</td><td>د ښځو او نوي زېږېدلي ماشوم د پاملرنې مسلکي برخه</td></tr><tr><td>دودیزه قابله</td><td>Traditional Birth Attendant</td><td>د تجربې او دود پر اساس د زېږون مرسته کوونکې</td></tr><tr><td>مسلکي قابله</td><td>Professional Midwife</td><td>رسمي علمي او عملي روزنه لرونکې قابله</td></tr><tr><td>امیندوارۍ پاملرنه</td><td>Antenatal Care</td><td>د امیندوارۍ پر مهال روغتیايي پاملرنه</td></tr><tr><td>د زېږون پاملرنه</td><td>Labour Care</td><td>د زېږون پر مهال پاملرنه</td></tr><tr><td>زېږون وروسته پاملرنه</td><td>Postnatal Care</td><td>د زېږون وروسته د مور پاملرنه</td></tr><tr><td>نوی زېږېدلی</td><td>Newborn</td><td>تازه زېږېدلی ماشوم</td></tr><tr><td>راجع کول</td><td>Referral</td><td>ناروغ مناسب روغتیايي مرکز/متخصص ته لېږل</td></tr><tr><td>درناوی لرونکې پاملرنه</td><td>Respectful Care</td><td>د ښځې عزت، محرمیت او حقونو ته درناوی</td></tr><tr><td>شواهدو پر بنسټ عمل</td><td>Evidence-Based Practice</td><td>د علمي شواهدو پر اساس روغتیايي عمل</td></tr></tbody></table><hr><h1>📝 ارزونه</h1><h2>برخه ۱: Single Answer</h2><h3>1. په افغانستان کې دودیزه قابلګي تر ډېره پر څه ولاړه وه؟</h3><h3 dir="rtl"></h3><p>A. MRI<br>B. تجربه او مشاهده<br>C. لابراتوار<br>D. جراحي</p><p><strong>صحیح ځواب: B</strong></p><p><strong>تشریح:</strong> دودیزه قابلګي تر ډېره د تجربې، مشاهدې او د نسلونو د انتقال پر بنسټ وه.</p><hr><h3>2. د مسلکي قابلې له مهمو دندو څخه کومه یوه ده؟</h3><h3 dir="rtl"></h3><p>A. یوازې د ماشوم نوم ټاکل<br>B. د خطر نښې پېژندل<br>C. یوازې د درملو پلورل<br>D. یوازې د روغتون پاکول</p><p><strong>صحیح ځواب: B</strong></p><p><strong>تشریح:</strong> د خطر نښو ژر پېژندل د مور او ماشوم د خوندي پاملرنې لپاره ډېر مهم دي.</p><hr><h3>3. Referral څه معنا لري؟</h3><h3 dir="rtl"></h3><p>A. ناروغ له پامه غورځول<br>B. ناروغ مناسب روغتیايي مرکز یا متخصص ته راجع کول<br>C. یوازې د ناروغ نوم لیکل<br>D. د کورنۍ سره بحث کول</p><p><strong>صحیح ځواب: B</strong></p><p><strong>تشریح:</strong> کله چې حالت تخصصي ارزونې یا درملنې ته اړتیا ولري، قابله باید مناسب Referral ترسره کړي.</p><hr><h3>4. آیا مسلکي قابلګي یوازې د ماشوم زېږولو په اړه ده؟</h3><h3 dir="rtl"></h3><p>A. هو<br>B. نه<br>C. یوازې په روغتون کې<br>D. یوازې په کور کې</p><p><strong>صحیح ځواب: B</strong></p><p><strong>تشریح:</strong> قابلګي د امیندوارۍ، زېږون، زېږون وروسته پاملرنې، نوي ماشوم، روغتیايي زده‌کړې او نورو برخو کې شامل خدمتونه لري.</p><hr><h3>5. د افغانستان لپاره ولې مسلکي قابلې مهمې دي؟</h3><h3 dir="rtl"></h3><p>A. یوازې د اسنادو لپاره<br>B. د مور او ماشوم د خوندي روغتیايي خدمتونو لپاره<br>C. یوازې د روغتون د مدیریت لپاره<br>D. یوازې د درملتون لپاره</p><p><strong>صحیح ځواب: B</strong></p><p><strong>تشریح:</strong> قابله د مور او نوي زېږېدلي ماشوم په روغتیا کې مهم مسلکي رول لري، په ځانګړي ډول د امیندوارۍ، زېږون او زېږون وروسته پاملرنه کې.</p><hr><h1>✅ True / False</h1><h3>6. دودیزه قابلګي د افغانستان په ټولنو کې تاریخي سابقه لري.</h3><h3 dir="rtl"></h3><p><strong>صحیح: True</strong></p><p><strong>تشریح:</strong> د رسمي مسلکي زده‌کړو له پراختیا مخکې تجربه لرونکو ښځو د زېږون پر مهال مهم رول درلود.</p><hr><h3>7. یوازې تجربه د مسلکي قابلې د کار لپاره کافي ده.</h3><h3 dir="rtl"></h3><p><strong>صحیح: False</strong></p><p><strong>تشریح:</strong> مسلکي قابلګي علمي زده‌کړې، عملي مهارت، مسلکي معیارونو او شواهدو ته اړتیا لري.</p><hr><h3>8. Referral د قابلې د مسلکي کار یوه مهمه برخه ده.</h3><h3 dir="rtl"></h3><p><strong>صحیح: True</strong></p><p><strong>تشریح:</strong> د جدي یا له خپل مسلکي صلاحیت څخه بهر حالتونو په وخت کې مناسب Referral د خوندي پاملرنې برخه ده.</p><hr><h1>✍️ لنډې پوښتنې</h1><h3>9. د دودیزې قابلې او مسلکي قابلې ترمنځ دوه مهم توپیرونه ولیکئ.</h3><h3 dir="rtl"></h3><p><strong>نمونه ځواب:</strong></p><p>دودیزه قابله تر ډېره د تجربې او دود پر اساس کار کوي، خو مسلکي قابله رسمي علمي او عملي روزنه لري او د مسلکي معیارونو او شواهدو پر اساس کار کوي.</p><hr><h3>10. ولې Referral د قابلې لپاره مهم دی؟</h3><h3 dir="rtl"></h3><p><strong>نمونه ځواب:</strong></p><p>ځکه چې ځینې روغتیايي حالتونه تخصصي ارزونې او درملنې ته اړتیا لري. قابله باید خطر وپېژني او ښځه په مناسب وخت کې مناسب روغتیايي مرکز یا متخصص ته راجع کړي.</p><hr><h1>🧠 د درس مهمه نقشه</h1><h3 dir="rtl"></h3><p>د دې درس اصلي مفهوم داسې په یاد وساتئ:</p><p><strong>دودیزه قابلګي</strong><br>↓<br><strong>تجربه او مشاهده</strong><br>↓<br><strong>رسمي زده‌کړه</strong><br>↓<br><strong>مسلکي قابلګي</strong><br>↓<br><strong>Evidence-Based Practice</strong><br>↓<br><strong>Safe &amp; Respectful Maternity Care</strong></p><hr><h1>🩺 جامع کلینیکي سناریو</h1><h3 dir="rtl"></h3><p>یوه امیندواره ښځه په یوه لرې افغانه سیمه کې له یوې قابلې سره مراجعه کوي.</p><p>ښځه د امیندوارۍ په وروستیو کې ده او وايي:</p><blockquote><p>«له پرون راهیسې مې شدید سر درد دی او کله کله مې سترګې تیاره کېږي.»</p></blockquote><p>قابله باید یوازې دا ونه وايي:</p><blockquote><p>«دا د امیندوارۍ عادي ستونزه ده.»</p></blockquote><p>بلکې باید:</p><ol><li><p>د ښځې وضعیت وارزوي؛</p></li><li><p>حیاتي نښې وګوري؛</p></li><li><p>د خطر نښې جدي ونیسي؛</p></li><li><p>مناسب اقدام وکړي؛</p></li><li><p>که اړتیا وي، د تخصصي ارزونې لپاره Referral وکړي؛</p></li><li><p>ښځې او کورنۍ ته واضح معلومات ورکړي؛</p></li><li><p>د ښځې عزت، محرمیت او درناوی وساتي.</p></li></ol><h3>د دې سناریو اصلي درس:</h3><h3 dir="rtl"></h3><p><strong>یوه ښه قابله یوازې هغه څوک نه ده چې ماشوم زېږوي؛ ښه قابله هغه څوک ده چې خطر ژر پېژني، خوندي اقدام کوي، د خپلې وړتیا حدود پېژني او د اړتیا پر وخت Referral کوي.</strong></p><hr><h1>📌 د درس لنډیز</h1><h3 dir="rtl"></h3><p>په افغانستان کې قابلګي له اوږدې دودیزې تجربې څخه د <strong>علمي او مسلکي روغتیايي مسلک</strong> په لور پرمختګ کړی دی.</p><p>د نن ورځې مسلکي قابله باید:</p><ul><li><p>علمي پوهه ولري؛</p></li><li><p>عملي مهارت ولري؛</p></li><li><p>د خطر نښې وپېژني؛</p></li><li><p>د مور او ماشوم خوندیتوب ته لومړیتوب ورکړي؛</p></li><li><p>کلتوري حساسیت ولري؛</p></li><li><p>د ښځې عزت او محرمیت وساتي؛</p></li><li><p>Evidence-Based Practice تعقیب کړي؛</p></li><li><p>او د اړتیا پر وخت Referral ترسره کړي.</p></li></ul><h3>⭐ د ښوونکي وروستی پیغام</h3><h3 dir="rtl"><blockquote><p><strong>«ګرانو زده‌کوونکو، د افغانستان یوه ښه قابله یوازې د زېږون په وخت کې د یوې ښځې تر څنګ نه درېږي؛ هغه د ښځې د امیندوارۍ، زېږون، زېږون وروسته دورې او د نوي ماشوم د ژوند په لومړیو شېبو کې د خوندي پاملرنې یوه مهمه برخه ده. ستاسو زده‌کړه یوازې د یوه سند لپاره نه ده؛ ستاسو پوهه په راتلونکي کې د یوې مور او ماشوم د ژوند په خوندي کولو کې ارزښت لري. له همدې امله هره موضوع په دقت زده کړئ، پوښتنې وکړئ، خپل مسلکي حدود وپېژنئ، او تل د خوندي او درناوي وړ پاملرنې لپاره کار وکړئ.»</strong></p></blockquote></h3>', 'rtl', 'none', NULL, NULL, 28, 'intro', 8, TRUE, 3, TRUE, '2026-09-13 04:39:29'),
(371, 34, 'د قابلګي د پاملرنې ماډل', '<p dir="rtl" style="text-align:right">د قابلګي ماډل د طبي ماډل څخه توپیر لري — پر تداوم او اړیکه ولاړ دی.</p>', '<h1>📘 درس: د قابلګي د پاملرنې ماډل</h1><h3>Midwifery Model of Care</h3><h3 dir="rtl"></h3><p><strong>کچه:</strong> د قابلګۍ لومړی سمستر – مبتدي<br><strong>د درس موده:</strong> ۶۰ دقیقې<br><strong>د درس ډول:</strong> آنلاین انفرادي زده‌کړه</p><hr><h1>🎯 د درس موخې</h1><h3 dir="rtl"></h3><p>د دې درس تر پای پورې به زده‌کوونکی وکولای شي:</p><ol><li><p>د قابلګي د پاملرنې ماډل (Midwifery Model of Care) تعریف کړي.</p></li><li><p>تشریح کړي چې د قابلګي پاملرنه له یوازې طبي/ناروغۍ-محور پاملرنې سره څه توپیر لري.</p></li><li><p>د ښځې-محور پاملرنې (Woman-Centred Care) مفهوم تشریح کړي.</p></li><li><p>د Continuity of Care اهمیت درک کړي.</p></li><li><p>د عادي امیندوارۍ (Normal Pregnancy) او د خطر حالتونو ترمنځ د قابلې رول درک کړي.</p></li><li><p>د احترام، انتخاب، رضایت، محرمیت او شواهدو پر بنسټ پاملرنې اهمیت وپېژني.</p></li><li><p>په کلینیکي سناریو کې د قابلګي د پاملرنې ماډل تطبیق کړي.</p></li></ol><hr><h1>۱. د تېر درس سره اړیکه</h1><h3 dir="rtl"></h3><p>په تېر درس کې مو زده کړل چې <strong>قابلګي په افغانستان کې</strong> له دودیزې تجربې څخه د علمي او مسلکي روغتیايي خدمت په لور پرمختګ کړی دی.</p><p>اوس یوه مهمه پوښتنه راولاړېږي:</p><blockquote><p><strong>مسلکي قابله باید ښځې ته څنګه پاملرنه وکړي؟</strong></p></blockquote><p>یوازې دا کافي نه ده چې قابله پوهه ولري.</p><p>موږ باید پوه شو چې:</p><p><strong>قابله څنګه فکر کوي؟</strong><br><strong>د ښځې اړتیا څنګه ارزوي؟</strong><br><strong>څنګه پرېکړه کوي؟</strong><br><strong>څنګه له ښځې سره اړیکه جوړوي؟</strong><br><strong>او څنګه د امیندوارۍ څخه تر زېږون وروسته دورې پورې پاملرنه تنظیموي؟</strong></p><p>همدې ته <strong>د قابلګي د پاملرنې ماډل (Midwifery Model of Care)</strong> ویل کېږي.</p><hr><h1>۲. د قابلګي د پاملرنې ماډل څه شی دی؟</h1><h3 dir="rtl"></h3><p>په ساده ژبه:</p><blockquote><p><strong>د قابلګي د پاملرنې ماډل هغه طریقه ده چې قابله د ښځې روغتیا، امیندوارۍ، زېږون، زېږون وروسته دورې او نوي ماشوم ته د پاملرنې لپاره کاروي.</strong></p></blockquote><p>په دې ماډل کې ښځه یوازې د یوې ناروغې په توګه نه لیدل کېږي.</p><p>بلکې ښځه د:</p><p><strong>انسان + مور/راتلونکې مور + تصمیم نیوونکې + کورنۍ او ټولنې غړې</strong></p><p>په توګه لیدل کېږي.</p><hr><h1>۳. د قابلګي د پاملرنې ماډل اصلي فکر</h1><h3 dir="rtl"></h3><p>د دې ماډل مرکزي ټکی دا دی:</p><h2>👩 ښځه د پاملرنې مرکز دی</h2><h3 dir="rtl"></h3><p>نه یوازې:</p><blockquote><p>«ماشوم څنګه دی؟»</p></blockquote><p>بلکې:</p><blockquote><p><strong>«مور څنګه ده؟ څه اړتیا لري؟ څه احساس کوي؟ څه غواړي؟ کوم خطرونه لري؟ او څنګه کولی شو خوندي پاملرنه ورته برابره کړو؟»</strong></p></blockquote><hr><h1>۴. Woman-Centred Care – ښځه‌محوره پاملرنه</h1><h3 dir="rtl"></h3><p><strong>Woman-Centred Care</strong> د قابلګي د پاملرنې یو مهم اصل دی.</p><p>یعنې قابله د ښځې:</p><ul><li><p>اړتیاوې؛</p></li><li><p>ارزښتونه؛</p></li><li><p>انتخابونه؛</p></li><li><p>اندېښنې؛</p></li><li><p>احساسات؛</p></li><li><p>کلتوري شرایط؛</p></li><li><p>روغتیايي وضعیت؛</p></li><li><p>او شخصي غوښتنې</p></li></ul><p>په پام کې نیسي.</p><h3>مثال</h3><h3 dir="rtl"></h3><p>یوه امیندواره ښځه قابله ته وایي:</p><blockquote><p>«زه د زېږون څخه ډېره وېرېږم.»</p></blockquote><p>کمزوری ځواب:</p><blockquote><p>«مه وېرېږه، ټولې ښځې زېږون کوي.»</p></blockquote><p>مسلکي ځواب:</p><blockquote><p>«زه پوهېږم چې دا اندېښنه درته مهمه ده. راځئ وګورو چې تر ټولو زیات له څه شي وېرېږئ، بیا به یې په اړه معلومات درکړم او د خوندي زېږون لپاره به مو پلان جوړ کړو.»</p></blockquote><h3>دلته څه وشول؟</h3><h3 dir="rtl"></h3><p>قابله:</p><p><strong>اورېدنه → درک → معلومات → انتخاب → ملاتړ</strong></p><p>وکارول.</p><hr><h1>۵. Midwife–Woman Partnership</h1><h3 dir="rtl"></h3><p>د قابلګي پاملرنه باید د <strong>Partnership – مشارکت</strong> پر بنسټ وي.</p><p>یعنې قابله ځان د ښځې «امر کوونکې» نه ګڼي.</p><p>بلکې:</p><p><strong>قابله + ښځه = د پاملرنې شریکان</strong></p><p>قابله خپل علم او تجربه وړاندې کوي.</p><p>ښځه خپل:</p><ul><li><p>احساس؛</p></li><li><p>اړتیا؛</p></li><li><p>انتخاب؛</p></li><li><p>او ترجیح</p></li></ul><p>بیانوي.</p><p>بیا د معلوماتو پر اساس مناسب تصمیم نیول کېږي.</p><hr><h1>۶. Informed Choice – باخبره انتخاب</h1><h3 dir="rtl"></h3><p>یوه قابله باید ښځې ته مناسب معلومات ورکړي.</p><p>مثلاً:</p><blockquote><p>«د دې حالت لپاره څو انتخابونه شته. دا یې ګټې دي، دا یې احتمالي خطرونه دي، او دا هغه حالتونه دي چې باید روغتون ته مراجعه وشي.»</p></blockquote><p>وروسته ښځه کولای شي د خپل حالت، طبي اړتیاوو او مسلکي مشورې په رڼا کې تصمیم ونیسي.</p><h3>مهم فرق:</h3><h3 dir="rtl"></h3><p><strong>Informed Choice ≠ ښځې ته هر څه پرېښودل</strong></p><p>که یو حالت جدي خطر ولري، قابله باید خطر واضح تشریح کړي او د مناسبې طبي مرستې/Referral لپاره اقدام وکړي.</p><hr><h1>۷. Respect – درناوی</h1><h3 dir="rtl"></h3><p>د قابلګي په پاملرنه کې ښځه باید د عزت وړ انسان وګڼل شي.</p><p>قابله باید:</p><ul><li><p>په درناوي خبرې وکړي؛</p></li><li><p>سپکاوی ونه کړي؛</p></li><li><p>بې‌ځایه و نه غندي؛</p></li><li><p>د ښځې خبرې واوري؛</p></li><li><p>محرمیت وساتي؛</p></li><li><p>د معاینې پر مهال مناسب Privacy برابر کړي.</p></li></ul><h3>یوه ساده جمله:</h3><h3 dir="rtl"><blockquote><p><strong>«ستاسې بدن، ستاسې محرمیت او ستاسې عزت مهم دي.»</strong></p></blockquote><hr></h3><h1>۸. Consent – رضایت</h1><h3 dir="rtl"></h3><p>د هرې مناسبې معاینې یا پروسې څخه مخکې باید ښځې ته تشریح وشي چې څه ترسره کېږي او ولې.</p><p>مثلاً:</p><blockquote><p>«زه غواړم ستاسې حیاتي نښې وګورم. اجازه راکوئ؟»</p></blockquote><p>یا:</p><blockquote><p>«د دې معاینې هدف دا دی چې د ماشوم او ستاسې وضعیت وارزول شي. که موافقه یاست، معاینه به ترسره کړو.»</p></blockquote><h3>ولې مهم دی؟</h3><h3 dir="rtl"></h3><p>ځکه ښځه باید پوه شي چې:</p><p><strong>څه کېږي؟ → ولې کېږي؟ → څنګه کېږي؟</strong></p><p>او د خپل مسلکي او قانوني چوکاټ په دننه کې د رضایت حق ولري.</p><hr><h1>۹. Privacy او Confidentiality</h1><h3>Privacy – محرمیت/شخصي فضا</h3><h3 dir="rtl"></h3><p>ښځه باید د معاینې او پاملرنې پر مهال مناسبه شخصي فضا ولري.</p><h3>Confidentiality – د معلوماتو محرم ساتل</h3><h3 dir="rtl"></h3><p>د ښځې روغتیايي معلومات باید بې‌ځایه له نورو سره شریک نه شي.</p><p>مثلاً:</p><p>یوه ښځه قابله ته د خپلې روغتیا په اړه شخصي موضوع بیانوي.</p><p>قابله باید دا معلومات د نورو خلکو سره د غیرضروري خبرو لپاره شریک نه کړي.</p><hr><h1>۱۰. Holistic Care – هراړخیزه پاملرنه</h1><h3 dir="rtl"></h3><p>د قابلګي ماډل یوازې فزیکي بدن نه ګوري.</p><p>قابله باید د ښځې څو اړخونه په پام کې ونیسي:</p><h3>🫀 Physical</h3><h3 dir="rtl"></h3><p>فزیکي روغتیا</p><h3>🧠 Psychological</h3><h3 dir="rtl"></h3><p>رواني او احساساتي حالت</p><h3>👨‍👩‍👧 Social</h3><h3 dir="rtl"></h3><p>ټولنیز او کورنی وضعیت</p><h3>🌍 Cultural</h3><h3 dir="rtl"></h3><p>کلتوري شرایط</p><h3>📚 Educational</h3><h3 dir="rtl"></h3><p>د روغتیا په اړه پوهه</p><h3>❤️ Emotional</h3><h3 dir="rtl"></h3><p>احساسات او وېرې</p><p>نو:</p><blockquote><p><strong>Woman ≠ فقط Body</strong></p></blockquote><p>ښځه له بدن، احساساتو، فکرونو، اړیکو او ټولنیز چاپېریال څخه جوړه یوه بشپړه انساني موجوده ده.</p><hr><h1>۱۱. Continuity of Care – د پاملرنې دوام</h1><h3 dir="rtl"></h3><p>دا د قابلګي د پاملرنې یو ډېر مهم مفهوم دی.</p><p><strong>Continuity of Care</strong> یعنې ښځه د روغتیايي خدمتونو په مختلفو پړاوونو کې د منظمې او دوامدارې پاملرنې احساس ولري.</p><p>مثلاً:</p><p><strong>Pregnancy</strong><br>↓<br><strong>Labour</strong><br>↓<br><strong>Birth</strong><br>↓<br><strong>Postnatal Period</strong><br>↓<br><strong>Newborn Care</strong></p><p>د ښځې معلومات، اړتیاوې او د پاملرنې پلان باید تر ممکنه حده منظم او یو له بل سره تړلي وي.</p><h3>ولې مهم دی؟</h3><h3 dir="rtl"></h3><p>ځکه قابله د ښځې حالت، تاریخچه، اړتیاوې او پرمختګ ښه پېژني.</p><hr><h1>۱۲. Midwife as a Professional Care Provider</h1><h3 dir="rtl"></h3><p>قابله باید یوازې «د ماشوم د زېږولو مرسته کوونکې» ونه ګڼل شي.</p><p>قابله کولی شي:</p><ul><li><p>Assessor — ارزونکې</p></li><li><p>Care Provider — د پاملرنې برابروونکې</p></li><li><p>Educator — ښوونکې</p></li><li><p>Counsellor — مشاورې</p></li><li><p>Advocate — د ښځې د حقونو ملاتړ کوونکې</p></li><li><p>Communicator — مسلکي اړیکه جوړوونکې</p></li><li><p>Referral Coordinator — د اړتیا پر مهال د راجع کولو تنظیموونکې</p></li></ul><p>وي.</p><hr><h1>۱۳. Normal Pregnancy – عادي امیندوارۍ</h1><h3 dir="rtl"></h3><p>د قابلګي ماډل کې یو مهم اصل دا دی چې <strong>عادي امیندوارۍ د فزیولوژیکي پروسې په توګه لیدل کېږي</strong>، نه دا چې هره امیندواره ښځه له پیل څخه «ناروغه» وګڼل شي.</p><p>مثلاً:</p><p>یوه سالمه امیندواره ښځه منظم مراقبت ته مراجعه کوي او د خطر نښې نه لري.</p><p>قابله:</p><ul><li><p>وضعیت څاري؛</p></li><li><p>روغتیايي مشوره ورکوي؛</p></li><li><p>د عادي بدلونونو په اړه معلومات ورکوي؛</p></li><li><p>خطر نښې تشریح کوي؛</p></li><li><p>او د اړتیا پر وخت Referral کوي.</p></li></ul><h3>خو:</h3><h3 dir="rtl"></h3><p><strong>Normal ≠ No Risk</strong></p><p>یعنې عادي امیندوارۍ هم باید منظمې وڅارل شي، ځکه ځینې ستونزې وروسته رامنځته کېدای شي.</p><hr><h1>۱۴. Evidence-Based Practice</h1><h3 dir="rtl"></h3><p>مسلکي قابله باید یوازې پر دې تکیه ونه کړي:</p><blockquote><p>«زموږ په کلي کې همیشه همداسې شوي دي.»</p></blockquote><p>بلکې باید وپوښتي:</p><blockquote><p><strong>«د دې کار لپاره علمي شواهد څه وایي؟»</strong></p></blockquote><p><strong>Evidence-Based Practice</strong> د:</p><p><strong>Scientific Evidence + Professional Expertise + Woman''s Needs/Preferences</strong></p><p>ترکیب دی.</p><hr><h1>۱۵. Safety – خوندیتوب</h1><h3 dir="rtl"></h3><p>د قابلګي ماډل کې ښځې ته درناوی مهم دی، خو <strong>Safety</strong> هم مهم دی.</p><p>د مثال په ډول:</p><p>یوه ښځه غواړي په کور کې زېږون وکړي.</p><p>قابله باید:</p><ol><li><p>د هغې غوښتنه واوري؛</p></li><li><p>د هغې شرایط وارزوي؛</p></li><li><p>د خوندي زېږون اړوند معلومات ورکړي؛</p></li><li><p>احتمالي خطرونه تشریح کړي؛</p></li><li><p>د موجودو روغتیايي خدماتو په اړه معلومات ورکړي؛</p></li><li><p>او که خطر موجود وي، مناسب Referral/Medical Care ته لومړیتوب ورکړي.</p></li></ol><hr><h1>🩺 کلینیکي سناریو ۱</h1><h3>حالت</h3><h3 dir="rtl"></h3><p>یوه ۲۴ کلنه امیندواره ښځه د ANC لپاره مراجعه کوي.</p><p>هغه روغتیايي ستونزه نه لري، خو ډېره اندېښمنه ده.</p><p>مور یې ورسره ده او ټولې پوښتنې د هغې پر ځای ځوابوي.</p><h3>پوښتنه:</h3><h3 dir="rtl"></h3><p>قابله باید څه وکړي؟</p><h3>صحیح چلند:</h3><h3 dir="rtl"></h3><p>قابله باید:</p><ul><li><p>خپله ښځه مستقیمه مخاطب کړي؛</p></li><li><p>د هغې خبرې واوري؛</p></li><li><p>د هغې د رضایت او انتخاب حق ته درناوی وکړي؛</p></li><li><p>مور ته هم د مناسب رول اجازه ورکړي، که ښځه یې غواړي؛</p></li><li><p>او اړین روغتیايي معلومات ورکړي.</p></li></ul><h3>مهم درس:</h3><h3 dir="rtl"></h3><p><strong>Family Support مهم دی، خو Woman-Centred Care کې د ښځې خپل غږ مهم دی.</strong></p><hr><h1>🩺 کلینیکي سناریو ۲</h1><h3 dir="rtl"></h3><p>یوه ښځه وایي:</p><blockquote><p>«زه نه پوهېږم چې د زېږون پر مهال څه پېښېږي، ډېر وېرېږم.»</p></blockquote><h3>قابله:</h3><h3 dir="rtl"></h3><p>پر ځای د دې چې ووایي:</p><blockquote><p>«هیڅ مه وېرېږه.»</p></blockquote><p>باید:</p><ul><li><p>د هغې اندېښنه واوري؛</p></li><li><p>د زېږون پروسه تشریح کړي؛</p></li><li><p>د درد د مدیریت موجودې لارې تشریح کړي؛</p></li><li><p>د خطر نښې بیان کړي؛</p></li><li><p>پوښتنو ته یې ځواب ووایي؛</p></li><li><p>او د هغې د پاملرنې لپاره مناسب پلان جوړ کړي.</p></li></ul><h3>دلته کوم اصول کارول شوي؟</h3><h3 dir="rtl"></h3><p><strong>Communication + Education + Respect + Informed Choice + Emotional Support</strong></p><hr><h1>🩺 کلینیکي سناریو ۳</h1><h3 dir="rtl"></h3><p>یوه امیندواره ښځه داسې نښې لري چې د جدي روغتیايي ستونزې احتمال مطرح کوي.</p><p>کورنۍ وایي:</p><blockquote><p>«قابله، ته یې همدلته درملنه وکړه، روغتون ته اړتیا نشته.»</p></blockquote><h3>قابله باید څه وکړي؟</h3><h3 dir="rtl"></h3><p>قابله باید د کورنۍ فشار له امله خطر له پامه ونه غورځوي.</p><p>بلکې:</p><p><strong>Assess → Recognize Risk → Explain → Stabilize/Initial Appropriate Care → Refer</strong></p><p>د خپل مسلکي صلاحیت او موجودو لارښونو مطابق.</p><h3>مهم درس:</h3><h3 dir="rtl"><blockquote><p><strong>د قابلې وفاداري د خوندي پاملرنې او د ښځې روغتیا ته ده، نه یوازې د کورنۍ غوښتنې ته.</strong></p></blockquote><hr></h3><h1>🩺 کلینیکي سناریو ۴</h1><h3 dir="rtl"></h3><p>یوه نوې مور د زېږون وروسته وایي:</p><blockquote><p>«زه ډېر ستړې یم او احساس کوم چې څوک مې خبرې نه اوري.»</p></blockquote><p>قابله یوازې د ماشوم وزن نه ګوري.</p><p>بلکې د مور:</p><ul><li><p>فزیکي حالت؛</p></li><li><p>احساساتي وضعیت؛</p></li><li><p>د شیدو ورکولو ستونزې؛</p></li><li><p>کورنۍ ملاتړ؛</p></li><li><p>او نورو اړتیاوو</p></li></ul><p>ته هم پام کوي او که د جدي رواني یا طبي ستونزې نښې موجودې وي، مناسب اقدام/Referral کوي.</p><h3>مهم درس:</h3><h3 dir="rtl"></h3><p><strong>Postnatal Care یوازې د ماشوم پاملرنه نه ده؛ مور هم د پاملرنې مهم مرکز دی.</strong></p><hr><h1>🔑 د قابلګي د پاملرنې ماډل ۸ مهم اصول</h1><h3 dir="rtl"></h3><p>دا اته ټکي د زده‌کوونکي لپاره د درس اصلي نقشه وګرځوئ:</p><h3>1. Woman-Centred</h3><h3 dir="rtl"></h3><p>ښځه د پاملرنې مرکز ده.</p><h3>2. Respect</h3><h3 dir="rtl"></h3><p>د ښځې عزت او وقار.</p><h3>3. Choice</h3><h3 dir="rtl"></h3><p>د باخبره انتخاب ملاتړ.</p><h3>4. Consent</h3><h3 dir="rtl"></h3><p>رضایت.</p><h3>5. Privacy &amp; Confidentiality</h3><h3 dir="rtl"></h3><p>محرمیت او د معلوماتو ساتنه.</p><h3>6. Holistic Care</h3><h3 dir="rtl"></h3><p>فزیکي، رواني، ټولنیز او کلتوري اړخونه.</p><h3>7. Continuity</h3><h3 dir="rtl"></h3><p>د پاملرنې دوام.</p><h3>8. Safety &amp; Evidence</h3><h3 dir="rtl"></h3><p>خوندي او د شواهدو پر بنسټ پاملرنه.</p><hr><h1>🧩 د قابلې د فکر کولو ساده فورمول</h1><h3 dir="rtl"></h3><p>کله چې یوه ښځه قابله ته مراجعه کوي، قابله باید داسې فکر وکړي:</p><p><strong>Listen</strong><br>⬇️<br><strong>Assess</strong><br>⬇️<br><strong>Identify Needs &amp; Risks</strong><br>⬇️<br><strong>Explain</strong><br>⬇️<br><strong>Plan Together</strong><br>⬇️<br><strong>Provide Care</strong><br>⬇️<br><strong>Monitor</strong><br>⬇️<br><strong>Refer When Needed</strong><br>⬇️<br><strong>Follow Up</strong></p><p>دا د زده‌کوونکو لپاره یو ډېر مهم عملي ذهني ماډل دی.</p><hr><h1>💻 آنلاین انفرادي فعالیت</h1><h2>Activity: «د قابلې پرېکړه»</h2><h3 dir="rtl"></h3><p>په LMS کې لاندې سناریو وړاندې کړئ:</p><blockquote><p>«یوه امیندواره ښځه وایي چې د زېږون څخه وېرېږي او غواړي چې قابله د هغې ټولې پوښتنې ځواب کړي.»</p></blockquote><p>سیستم دې زده‌کوونکي ته لاندې کړنې ورکړي او زده‌کوونکی دې په مناسب ترتیب کې کېږدي:</p><ul><li><p>د ښځې خبرې اورېدل</p></li><li><p>د هغې اندېښنه پېژندل</p></li><li><p>معلومات ورکول</p></li><li><p>د ښځې پوښتنو ته ځواب ورکول</p></li><li><p>د انتخابونو تشریح کول</p></li><li><p>د پاملرنې پلان جوړول</p></li><li><p>Follow-up</p></li></ul><h3>صحیح ترتیب:</h3><h3 dir="rtl"></h3><p><strong>Listen → Assess/Understand → Explain → Discuss Choices → Plan → Follow-up</strong></p><p>د هر انتخاب وروسته دې LMS د صحیح ترتیب تشریح هم ښکاره کړي.</p><hr><h1>📚 مهمې اصطلاحات</h1><h3 dir="rtl"></h3><table><thead><tr><th>پښتو</th><th>English</th><th>ساده تشریح</th></tr></thead><tbody><tr><td>د قابلګي د پاملرنې ماډل</td><td>Midwifery Model of Care</td><td>د قابلې د پاملرنې مسلکي طریقه</td></tr><tr><td>ښځه‌محوره پاملرنه</td><td>Woman-Centred Care</td><td>د ښځې اړتیاوې او انتخابونه د پاملرنې په مرکز کې</td></tr><tr><td>دوامداره پاملرنه</td><td>Continuity of Care</td><td>د پاملرنې منظم دوام</td></tr><tr><td>باخبره انتخاب</td><td>Informed Choice</td><td>د معلوماتو له ترلاسه کولو وروسته انتخاب</td></tr><tr><td>رضایت</td><td>Consent</td><td>د پاملرنې/پروسې لپاره د ښځې موافقه</td></tr><tr><td>محرمیت</td><td>Privacy</td><td>د شخصي فضا او شخصي معلوماتو ساتنه</td></tr><tr><td>هراړخیزه پاملرنه</td><td>Holistic Care</td><td>د انسان ټولو مهمو اړخونو ته پاملرنه</td></tr><tr><td>شواهدو پر بنسټ عمل</td><td>Evidence-Based Practice</td><td>د علمي شواهدو پر اساس عمل</td></tr><tr><td>Referral</td><td>Referral</td><td>مناسب متخصص/مرکز ته راجع کول</td></tr><tr><td>ملاتړ کوونکې</td><td>Advocate</td><td>د ښځې د حقونو او اړتیاوو ملاتړ</td></tr></tbody></table><hr><h1>📝 ارزونه</h1><h2>برخه ۱: Single Answer</h2><h3>1. د قابلګي د پاملرنې ماډل اصلي مرکز څوک دی؟</h3><h3 dir="rtl"></h3><p>A. یوازې ماشوم<br>B. یوازې قابله<br>C. ښځه او د هغې اړتیاوې<br>D. یوازې کورنۍ</p><p><strong>صحیح ځواب: C</strong></p><p><strong>تشریح:</strong> Woman-Centred Care د قابلګي د پاملرنې مهم اصل دی؛ ښځه، د هغې روغتیا، اړتیاوې، ارزښتونه او انتخابونه باید په پام کې ونیول شي.</p><hr><h3>2. Informed Choice څه معنا لري؟</h3><h3 dir="rtl"></h3><p>A. ښځې ته هېڅ معلومات نه ورکول<br>B. ښځې ته معلومات ورکول ترڅو باخبره انتخاب وکړي<br>C. قابله د ښځې پر ځای هره پرېکړه وکړي<br>D. کورنۍ هره پرېکړه وکړي</p><p><strong>صحیح ځواب: B</strong></p><p><strong>تشریح:</strong> ښځه باید د اړوندو انتخابونو، ګټو او احتمالي خطرونو په اړه مناسب معلومات ترلاسه کړي.</p><hr><h3>3. Holistic Care څه ته وایي؟</h3><h3 dir="rtl"></h3><p>A. یوازې د بدن معاینه<br>B. یوازې د ماشوم پاملرنه<br>C. د ښځې فزیکي، رواني، ټولنیزو او نورو مهمو اړتیاوو ته پاملرنه<br>D. یوازې درمل ورکول</p><p><strong>صحیح ځواب: C</strong></p><p><strong>تشریح:</strong> هراړخیزه پاملرنه انسان یوازې د بدن په توګه نه ګوري.</p><hr><h3>4. Referral ولې مهم دی؟</h3><h3 dir="rtl"></h3><p>A. ځکه قابله باید هېڅ کار ونه کړي<br>B. ځکه هره ښځه باید روغتون ته ولاړه شي<br>C. ځکه ځینې حالتونه تخصصي ارزونې او درملنې ته اړتیا لري<br>D. یوازې د اسنادو لپاره</p><p><strong>صحیح ځواب: C</strong></p><p><strong>تشریح:</strong> قابله باید خپل مسلکي حدود وپېژني او د اړتیا پر مهال ښځه مناسب روغتیايي خدمت ته راجع کړي.</p><hr><h3>5. Continuity of Care څه ته اشاره کوي؟</h3><h3 dir="rtl"></h3><p>A. د پاملرنې بشپړ بندول<br>B. د ښځې لپاره د پاملرنې دوام او تسلسل<br>C. یوازې یوه معاینه<br>D. یوازې د زېږون وخت</p><p><strong>صحیح ځواب: B</strong></p><p><strong>تشریح:</strong> د پاملرنې دوام د امیندوارۍ، زېږون او زېږون وروسته پړاوونو کې د منظمې پاملرنې مهم اصل دی.</p><hr><h1>✅ True / False</h1><h3>6. د قابلګي ماډل کې د ښځې نظر او انتخاب مهم دی.</h3><h3 dir="rtl"></h3><p><strong>صحیح: True</strong></p><p><strong>تشریح:</strong> Woman-Centred Care د ښځې اړتیاوې، ارزښتونه او انتخابونه په پام کې نیسي.</p><hr><h3>7. قابله باید د ښځې ټولې پرېکړې د هغې پر ځای وکړي.</h3><h3 dir="rtl"></h3><p><strong>صحیح: False</strong></p><p><strong>تشریح:</strong> قابله معلومات، مسلکي مشوره او ملاتړ وړاندې کوي؛ د ښځې د باخبره انتخاب ملاتړ کوي.</p><hr><h3>8. د قابلګي پاملرنه یوازې فزیکي بدن ته محدودېږي.</h3><h3 dir="rtl"></h3><p><strong>صحیح: False</strong></p><p><strong>تشریح:</strong> Holistic Care د ښځې فزیکي، رواني، احساساتي، ټولنیز او کلتوري اړخونه هم په پام کې نیسي.</p><hr><h1>✍️ لنډې پوښتنې</h1><h3>9. Woman-Centred Care په خپلو الفاظو کې تشریح کړئ.</h3><h3 dir="rtl"></h3><p><strong>نمونه ځواب:</strong></p><p>Woman-Centred Care هغه پاملرنه ده چې ښځه د پاملرنې په مرکز کې ساتي او د هغې روغتیا، اړتیاوې، احساسات، ارزښتونه، انتخابونه، محرمیت او درناوی په پام کې نیسي.</p><hr><h3>10. د قابلګي د پاملرنې د ماډل پنځه مهم اصول ولیکئ.</h3><h3 dir="rtl"></h3><p><strong>نمونه ځواب:</strong></p><ul><li><p>Woman-Centred Care</p></li><li><p>Respect</p></li><li><p>Informed Choice</p></li><li><p>Consent</p></li><li><p>Holistic Care</p></li></ul><p>نور مهم اصول Continuity، Privacy/Confidentiality، Safety او Evidence-Based Practice دي.</p><hr><h1>🧠 د ټول درس تر ټولو مهم مفهوم</h1><h3 dir="rtl"></h3><p>که زده‌کوونکی یوازې <strong>یوه جمله</strong> له دې درس څخه یادوي، باید دا وي:</p><h3><strong>«قابله یوازې د ناروغۍ درملنه نه کوي؛ قابله د ښځې، د هغې د اړتیاوو، انتخابونو، خوندیتوب او د مور او ماشوم د روغتیا لپاره هراړخیزه او مسلکي پاملرنه برابروي.»</strong></h3><h3 dir="rtl"><blockquote></blockquote><hr></h3><h1>🩺 وروستی جامع سناریو</h1><h3 dir="rtl"></h3><p>یوه امیندواره ښځه قابله ته مراجعه کوي.</p><p>هغه له زېږون څخه وېرېږي، کورنۍ یې ورسره ده، او غواړي چې د زېږون په اړه معلومات ترلاسه کړي.</p><p>قابله:</p><p><strong>اورېدل</strong><br>→ د ښځې اندېښنه درک کوي.</p><p><strong>ارزونه</strong><br>→ د مور او امیندوارۍ وضعیت ارزوي.</p><p><strong>معلومات</strong><br>→ د زېږون پروسه او مهمې نښې تشریح کوي.</p><p><strong>انتخاب</strong><br>→ موجود مناسب انتخابونه ورسره شریکوي.</p><p><strong>درناوی</strong><br>→ د ښځې محرمیت او نظر ته احترام کوي.</p><p><strong>خوندیتوب</strong><br>→ خطر نښې ارزوي.</p><p><strong>Referral</strong><br>→ که اړتیا وي، مناسب روغتیايي مرکز ته یې راجع کوي.</p><p><strong>Follow-up</strong><br>→ د راتلونکي پاملرنې لپاره پلان جوړوي.</p><p>دا ټول یوځای د <strong>Midwifery Model of Care</strong> عملي بڼه جوړوي.</p><hr><h1>🌟 د ښوونکي وروستی پیغام</h1><h3 dir="rtl"><blockquote><p><strong>«ګرانو زده‌کوونکو، د قابلې لویه وړتیا یوازې په دې کې نه ده چې هغه څومره طبي معلومات لري؛ بلکې په دې کې هم ده چې څنګه له یوې ښځې سره چلند کوي. یوه ښځه چې قابله ته مراجعه کوي، یوازې یو طبي حالت نه دی؛ هغه یو انسان دی چې احساسات، اندېښنې، کورنۍ، کلتور او خپل انتخابونه لري. ښه قابله هغه ده چې واوري، درک کړي، وارزوي، معلومات ورکړي، د ښځې عزت وساتي، خوندیتوب ته لومړیتوب ورکړي او د اړتیا پر وخت مرسته او Referral وکړي. له همدې امله د قابلګي د پاملرنې ماډل یوازې یو درسي مفهوم نه دی؛ دا هغه طرز فکر دی چې تاسو به د خپلې مسلکي قابلګۍ په ټول ژوند کې ورسره کار کوئ.»</strong></p></blockquote></h3>', 'rtl', 'url', 'https://www.youtube.com/watch?v=2vAU-H6OG38', NULL, 28, 'intro', 12, TRUE, 4, TRUE, '2026-09-13 04:39:29'),
(372, 34, 'د ماما نړیوال تعریف (ICM)', '<p dir="rtl" style="text-align:right">ICM د ماما لپاره یو نړیوال تعریف لري چې د زده کړې او جواز بنسټ دی.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>د ICM تعریف بیان کړئ.</li><li>د ماما مسؤلیتونه ونومئ.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">ICM د ماما لپاره یو نړیوال تعریف لري چې د زده کړې او جواز بنسټ دی.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>ماما هغه څوک ده چې یو منل شوی د مامایي زده کړې پروګرام بشپړ کړی وي.</li><li>باید د خپل هیواد له خوا جواز (registration) ترلاسه کړي.</li><li>ماما د امیندوارۍ، زیږون او وروسته دورې پاملرنه کوي.</li><li>ماما د نوي زیږیدلي پاملرنه هم کوي.</li><li>ماما د روغتیا ښوونه او مشوره ورکوي.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>تعریف</td><td dir="ltr" style="text-align:left">Definition</td></tr><tr><td>جواز</td><td dir="ltr" style="text-align:left">Registration</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>دا تعریف هغه معیار دی چې ستاسو زده کړه پرې ارزول کیږي.</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'none', NULL, NULL, 26, 'intro', 15, TRUE, 5, TRUE, '2026-09-13 04:39:29'),
(373, 34, 'د ICM اساسي وړتیاوې', '<p dir="rtl" style="text-align:right">ICM څلور کټګورۍ اساسي وړتیاوې ټاکلې دي چې هره ماما باید ولري.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>څلور کټګورۍ ونومئ.</li><li>د هرې کټګورۍ یوه بیلګه ورکړئ.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">ICM څلور کټګورۍ اساسي وړتیاوې ټاکلې دي چې هره ماما باید ولري.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>۱) عمومي وړتیاوې — اخلاق، اړیکې، پریکړه کول.</li><li>۲) د امیندوارۍ دمخه او انټي نیټل پاملرنه.</li><li>۳) د زیږون پر مهال پاملرنه.</li><li>۴) د مور او نوي زیږیدلي وروسته له زیږون پاملرنه.</li><li>هره وړتیا په پوهه، مهارت او چلند ویشل شوې ده.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>وړتیا</td><td dir="ltr" style="text-align:left">Competency</td></tr><tr><td>مهارت</td><td dir="ltr" style="text-align:left">Skill</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>ستاسو د لوګ بوک (logbook) هره مهارت له همدې لیست څخه اخیستل شوې ده.</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'url', 'https://www.youtube.com/watch?v=bnElZe86mxQ', NULL, 30, 'intro', 18, TRUE, 6, TRUE, '2026-09-13 04:39:29'),
(374, 34, 'د عمل ساحه (Scope of practice)', '<p dir="rtl" style="text-align:right">د عمل ساحه هغه پولې ټاکي چې ماما پکې خپلواکه پریکړه کولی شي.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>د عمل ساحه تعریف کړئ.</li><li>ووایاست چې کله باید رجعت ورکړل شي.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">د عمل ساحه هغه پولې ټاکي چې ماما پکې خپلواکه پریکړه کولی شي.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>ماما د نورمال امیندوارۍ او زیږون خپلواکه چمتو کوونکې ده.</li><li>د لوړ خطر پیښې د ډاکټر سره همکاري غواړي.</li><li>له خپلې ساحې بهر عمل کول قانوني مسؤلیت لري.</li><li>د عاجل حالت پر مهال ماما باید ژوند ژغورونکي اقدامات وکړي.</li><li>د عمل ساحه د هیواد قانون او د روغتون پالیسي ټاکي.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>د عمل ساحه</td><td dir="ltr" style="text-align:left">Scope of practice</td></tr><tr><td>خپلواکي</td><td dir="ltr" style="text-align:left">Autonomy</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>«پوهیدل چې څه نه کوې» هومره مهم دي لکه پوهیدل چې څه کوې.</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'none', NULL, NULL, 28, 'core', 22, TRUE, 7, TRUE, '2026-09-13 04:39:29'),
