(376, 34, 'د اخلاقو کود', '<p dir="rtl" style="text-align:right">د اخلاقو کود هغه ارزښتونه دي چې ستاسو هره پریکړه پرې ولاړه ده.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>څلور اخلاقي اصول ونومئ.</li><li>د هر یو بیلګه ورکړئ.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">د اخلاقو کود هغه ارزښتونه دي چې ستاسو هره پریکړه پرې ولاړه ده.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>خپلواکي (Autonomy): د ښځې د پریکړې درناوی.</li><li>ښیګړه (Beneficence): هغه څه کول چې ګټه رسوي.</li><li>زیان نه رسول (Non-maleficence).</li><li>عدالت (Justice): د ټولو سره برابر چلند.</li><li>رازساتنه او رښتینولي هم بنسټیز دي.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>خپلواکي</td><td dir="ltr" style="text-align:left">Autonomy</td></tr><tr><td>عدالت</td><td dir="ltr" style="text-align:left">Justice</td></tr><tr><td>رازساتنه</td><td dir="ltr" style="text-align:left">Confidentiality</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>کله چې ښځه یو تداوي ونه مني، ستاسو دنده پوهاوی ورکول دي — نه اجبار.</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'none', NULL, NULL, 30, 'core', 28, TRUE, 9, TRUE, '2026-09-13 04:39:29'),
(377, 34, 'مسلکي حساب ورکونه', '<p dir="rtl" style="text-align:right">هره ماما د خپلو کړنو مسؤله ده — مخې ښځې، مسلک او قانون ته.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>حساب ورکونه تعریف کړئ.</li><li>د ښه سند لیکنې اهمیت بیان کړئ.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">هره ماما د خپلو کړنو مسؤله ده — مخې ښځې، مسلک او قانون ته.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>حساب ورکونه یعنې د خپلو پریکړو توجیه کولی شې.</li><li>سند (documentation) ستاسو تر ټولو ښه دفاع ده.</li><li>که ولیکل شوي نه وي، ګڼل کیږي چې نه دي شوي.</li><li>غلطي پټول تر غلطۍ پخپله بدتره ده.</li><li>د پیښې راپور ورکول د زده کړې فرصت دی.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>حساب ورکونه</td><td dir="ltr" style="text-align:left">Accountability</td></tr><tr><td>سند لیکنه</td><td dir="ltr" style="text-align:left">Documentation</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>هر څه چې کوې ولیکه: وخت، موندنې، پریکړه او هغه څوک چې خبر شوی.</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'none', NULL, NULL, 28, 'core', 32, TRUE, 10, TRUE, '2026-09-13 04:39:29'),
(378, 34, 'د ښځې پر محور پاملرنه', '<p dir="rtl" style="text-align:right">ښځه د پاملرنې مرکز ده — نه د روغتون تګلاره او نه د ماما اسانتیا.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>د ښځې پر محور پاملرنه بیان کړئ.</li><li>عملي بیلګې ورکړئ.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">ښځه د پاملرنې مرکز ده — نه د روغتون تګلاره او نه د ماما اسانتیا.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>د ښځې غوښتنې، ارزښتونه او کلتور په پام کې ونیسئ.</li><li>د زیږون پلان (birth plan) ورسره جوړ کړئ.</li><li>د دریځ، خوړو او ملګري انتخاب ورته پریږدئ.</li><li>د هرې مداخلې پخوا تشریح او رضایت واخلئ.</li><li>ښځه په خپله ژبه پوه کړئ.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>د ښځې پر محور</td><td dir="ltr" style="text-align:left">Woman-centred</td></tr><tr><td>د زیږون پلان</td><td dir="ltr" style="text-align:left">Birth plan</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>یوه ښه پوښتنه: «تاسو څه غواړئ چې زه پوه شم؟»</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'none', NULL, NULL, 30, 'core', 35, TRUE, 11, TRUE, '2026-09-13 04:39:29'),
(379, 34, 'د درناوي سره د مور پاملرنه', '<p dir="rtl" style="text-align:right">د درناوي سره پاملرنه د هرې ښځې بنسټیز حق دی.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>د بې درناوي چلند بیلګې ونومئ.</li><li>د درناوي سره پاملرنې اصول بیان کړئ.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">د درناوي سره پاملرنه د هرې ښځې بنسټیز حق دی.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>بې درناوي چلند: وهل، رټل، بې رضایته مداخله، پریښودل.</li><li>هره ښځه د محرمیت (privacy) حق لري.</li><li>د درد کمولو غوښتنه باید جدي ونیول شي.</li><li>د ملګري شتون د زیږون پایلې ښه کوي.</li><li>ژبه اهمیت لري — «ښه کار کوې» ډیر ځواک لري.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>درناوی</td><td dir="ltr" style="text-align:left">Respect</td></tr><tr><td>محرمیت</td><td dir="ltr" style="text-align:left">Privacy</td></tr><tr><td>بدچلندي</td><td dir="ltr" style="text-align:left">Mistreatment</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>ډیرې ښځې د بې درناوي چلند له امله بیا روغتون ته نه راځي — دا په مستقیم ډول ژوند ته زیان رسوي.</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'url', 'https://www.youtube.com/watch?v=Mq9CEHpndpU', NULL, 32, 'core', 38, TRUE, 12, TRUE, '2026-09-13 04:39:29'),
(380, 34, 'کلتوري خوندیتوب', '<p dir="rtl" style="text-align:right">کلتوري خوندیتوب یعنې پاملرنه داسې وړاندې کول چې ښځه پکې ځان خوندي وګڼي.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>کلتوري خوندیتوب تعریف کړئ.</li><li>د افغاني شرایطو بیلګې ورکړئ.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">کلتوري خوندیتوب یعنې پاملرنه داسې وړاندې کول چې ښځه پکې ځان خوندي وګڼي.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>هر کلتور د زیږون خپل باورونه او دودونه لري.</li><li>ځینې دودونه بې زیانه دي — درناوی یې وکړئ.</li><li>ځینې زیانمن دي — په نرمۍ سره پوهاوی ورکړئ.</li><li>د ښځینه چمتو کوونکې غوښتنه باید درناوی شي.</li><li>ژباړونکی وکاروئ که ژبه بیله وي.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>کلتور</td><td dir="ltr" style="text-align:left">Culture</td></tr><tr><td>کلتوري خوندیتوب</td><td dir="ltr" style="text-align:left">Cultural safety</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>د دود بدلول د پوهاوي له لارې کیږي، نه د ملامتولو له لارې.</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'none', NULL, NULL, 28, 'core', 42, TRUE, 13, TRUE, '2026-09-13 04:39:29'),
(381, 34, 'خبرتیا سره رضایت', '<p dir="rtl" style="text-align:right">رضایت باید له پوهاوي، له خپلواکۍ او له اجباره پاک وي.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>د معتبر رضایت درې شرطونه ونومئ.</li><li>د رضایت لیکل بیان کړئ.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">رضایت باید له پوهاوي، له خپلواکۍ او له اجباره پاک وي.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>ښځه باید معلومات په خپله ژبه ترلاسه کړي.</li><li>ګټې، زیانونه او بدیلونه باید تشریح شي.</li><li>رضایت باید له خپلې خوښې وي.</li><li>ښځه کولی شي هر وخت رضایت بیرته واخلي.</li><li>د عاجل حالت کې د ژوند ژغورنې لپاره ځانګړي قواعد شته.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>رضایت</td><td dir="ltr" style="text-align:left">Consent</td></tr><tr><td>بدیل</td><td dir="ltr" style="text-align:left">Alternative</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>«لاسلیک کول» رضایت نه دی — پوهیدل رضایت دی.</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'none', NULL, NULL, 30, 'core', 45, TRUE, 14, TRUE, '2026-09-13 04:39:29'),
(382, 34, 'رازساتنه او محرمیت', '<p dir="rtl" style="text-align:right">د ښځې معلومات امانت دي.</p>', '<h3 dir="rtl" style="text-align:right">د زده کړې موخې</h3><ul dir="rtl" style="text-align:right"><li>رازساتنه تعریف کړئ.</li><li>هغه حالتونه ونومئ چې افشا اجازه لري.</li></ul><h3 dir="rtl" style="text-align:right">لنډیز</h3><p dir="rtl" style="text-align:right">د ښځې معلومات امانت دي.</p><h3 dir="rtl" style="text-align:right">اصلي مطالب</h3><ul dir="rtl" style="text-align:right"><li>د ښځې معلومات یوازې د پاملرنې لپاره کارول کیږي.</li><li>په دهلیز یا کور کې د ناروغ په اړه خبرې مه کوئ.</li><li>اسناد باید تړل شوي ځای کې وساتل شي.</li><li>د ښځې اجازې پرته کورنۍ ته معلومات مه ورکوئ.</li><li>استثنا: کله چې قانون غواړي یا د چا ژوند په خطر وي.</li></ul><h3 dir="rtl" style="text-align:right">کلیدي اصطلاحات</h3><table dir="rtl" style="text-align:right"><thead><tr><th>پښتو</th><th>English</th></tr></thead><tbody><tr><td>رازساتنه</td><td dir="ltr" style="text-align:left">Confidentiality</td></tr><tr><td>افشا</td><td dir="ltr" style="text-align:left">Disclosure</td></tr></tbody></table><h3 dir="rtl" style="text-align:right">د مامایي سره اړیکه</h3><blockquote dir="rtl" style="text-align:right"><p>د HIV یا کورنۍ تاوتریخوالي معلومات په ځانګړي ډول حساس دي.</p></blockquote><h3 dir="rtl" style="text-align:right">څه وکړئ</h3><ol dir="rtl" style="text-align:right"><li>ویډیو وګورئ او د پښتو زیرنویس څخه کار واخلئ.</li><li>ضمیمه شوې لوستنې مواد ولولئ.</li><li>په خپلو کلمو کې لنډې یادښتونه ولیکئ.</li><li>که کوز (کویز) شتون ولري، هغه ترسره کړئ، بیا لوست بشپړ نښه کړئ.</li></ol>', 'rtl', 'none', NULL, NULL, 26, 'core', 48, TRUE, 15, TRUE, '2026-09-13 04:39:29'),
